"sidebar-link active\" onclick=\"navigateTo('dashboard')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-speedometer2\"></i>\n            <span>داشبورد اصلی</span>\n          </div>\n        </a>\n\n        <div class=\"nav-category-header\">مدیریت محتوا</div>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('users')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-people-fill\"></i>\n            <span>مدیریت کاربران</span>\n          </div>\n        </a>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('rewards_management')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-gift-fill\"></i>\n            <span>جوایز و بنر هدیه</span>\n          </div>\n          <span class=\"badge bg-danger rounded-pill\" id=\"sidebarClaimsBadge\">۰</span>\n        </a>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('store')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-shop\"></i>\n            <span>فروشگاه و تراکنش‌ها</span>\n          </div>\n        </a>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('ad_banners')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-badge-ad-fill\"></i>\n            <span>مدیریت بنرهای تبلیغاتی</span>\n          </div>\n          <span class=\"badge bg-warning text-dark rounded-pill\" id=\"sidebarAdBannersBadge\" style=\"display: none;\">۰</span>\n        </a>\n        <div class=\"nav-category-header\">سیستم</div>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('settings')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-gear-fill\"></i>\n            <span>تنظیمات پنل</span>\n          </div>\n        </a>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('login_notification')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-megaphone-fill\"></i>\n            <span>مدیریت پیام ورود</span>\n          </div>\n        </a>\n        <a class=\"sidebar-link\" onclick=\"navigateTo('support')\">\n          <div class=\"sidebar-link-content\">\n            <i class=\"bi bi-headset\"></i>\n            <span>پشتیبانی کاربران</span>\n          </div>\n          <span class=\"badge bg-danger rounded-pill\" id=\"sidebarSupportBadge\" style=\"display: none;\">۰</span>\n        </a>\n      </div>\n\n      <!-- Sidebar Footer -->\n      <div class=\"sidebar-footer\">\n        <div class=\"d-flex align-items-center justify-content-between mb-2\">\n          <div class=\"d-flex align-items-center gap-2\">\n            <i class=\"bi bi-shield-check text-warning\"></i>\n            <span class=\"small text-secondary\">وضعیت سرور:</span>\n          </div>\n          <span id=\"authStatusBadge\" class=\"badge bg-secondary\" style=\"cursor: pointer;\" onclick=\"openAdminAuthModal()\" title=\"کلیک برای تنظیم یا ورود کلید\">در حال بررسی...</span>\n        </div>\n        <button class=\"btn btn-sm btn-outline-warning w-100 fw-bold py-2 mb-2\" onclick=\"openAdminAuthModal()\">\n          <i class=\"bi bi-key-fill me-1\"></i> ورود / تغییر کلید مدیریت\n        </button>\n        <button class=\"btn btn-sm btn-outline-danger w-100 fw-bold py-2\" onclick=\"logoutAdmin()\">\n          <i class=\"bi bi-box-arrow-right me-1\"></i> خروج امن از پنل\n        </button>\n      </div>\n    </aside>\n\n    <!-- 2. Main Content Area -->\n    <div class=\"admin-main\">\n      \n      <!-- Topbar Header -->\n      <header class=\"admin-topbar\">\n        <div class=\"topbar-right\">\n          <button class=\"menu-toggle-btn\" onclick=\"toggleSidebar()\" aria-label=\"منو\">\n            <i class=\"bi bi-list\"></i>\n          </button>\n          <div>\n            <h2 class=\"h5 gold-text mb-0 d-flex align-items-center gap-2\" id=\"currentSectionTitle\">\n              <i class=\"bi bi-speedometer2\"></i> داشبورد اصلی\n            </h2>\n            <small class=\"text-secondary d-none d-sm-block\">پایش آنلاین رویدادها، مسابقات دوره‌ای و پیام‌های کاربران</small>\n          </div>\n        </div>\n\n        <div class=\"topbar-left\">\n          <button id=\"refreshBtn\" class=\"btn btn-sm btn-warning fw-bold px-3 py-1.5\" onclick=\"loadDashboard()\">\n            <span id=\"refreshSpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n            <i class=\"bi bi-arrow-clockwise me-1\"></i> به‌روزرسانی\n          </button>\n        </div>\n      </header>\n\n      <!-- Main Body Content -->\n      <main class=\"admin-content\">\n        <!-- ============================================================== -->\n        <!-- Irancell Cellular & Tapsell Rewarded Ads System Alert Banner   -->\n        <!-- Visible across all 9 dashboard sections                         -->\n        <!-- ============================================================== -->\n\n\n        <!-- Global Alert Box -->\n        <div id=\"alertBox\" class=\"alert alert-danger d-none shadow-sm mb-4\" role=\"alert\"></div>\n\n        <!-- ============================================================== -->\n        <!-- SECTION 1: داشبورد اصلی (Dashboard Overview) -->\n        <!-- ============================================================== -->\n        <section id=\"section-dashboard\" class=\"admin-section active\">\n          <!-- Stat Cards Row -->\n          <div class=\"row g-3 mb-4\">\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-info bg-opacity-10 text-info\">\n                  <i class=\"bi bi-people-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">کل کاربران ثبت‌شده</div>\n                <h3 id=\"totalUsers\" class=\"gold-text mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-warning bg-opacity-10 text-warning\">\n                  <i class=\"bi bi-star-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">مجموع امتیازات دوره</div>\n                <h3 id=\"totalScores\" class=\"gold-text mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-success bg-opacity-10 text-success\">\n                  <i class=\"bi bi-cart-check-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">تراکنش‌های فروشگاه</div>\n                <h3 id=\"totalTransactions\" class=\"gold-text mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-danger bg-opacity-10 text-danger\">\n                  <i class=\"bi bi-gift-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">درخواست‌های جایزه</div>\n                <h3 id=\"totalClaims\" class=\"gold-text mb-0\">-</h3>\n              </div>\n            </div>\n          </div>\n\n          <!-- Quick Shortcuts Grid -->\n          <h6 class=\"text-secondary fw-bold mb-3\"><i class=\"bi bi-grid-fill me-1\"></i> دسترسی سریع</h6>\n          <div class=\"row g-3 mb-4\">\n            <div class=\"col-md-3 col-sm-6\">\n              <div class=\"shortcut-card\" onclick=\"navigateTo('users')\">\n                <div class=\"shortcut-icon\"><i class=\"bi bi-people-fill\"></i></div>\n                <div>\n                  <div class=\"fw-bold\">کاربران</div>\n                  <small class=\"text-secondary\">جستجو و امتیازها</small>\n                </div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <div class=\"shortcut-card\" onclick=\"navigateTo('store')\">\n                <div class=\"shortcut-icon\"><i class=\"bi bi-shop\"></i></div>\n                <div>\n                  <div class=\"fw-bold\">فروشگاه</div>\n                  <small class=\"text-secondary\">تراکنش‌ها و قیمت</small>\n                </div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <div class=\"shortcut-card\" onclick=\"navigateTo('rewards_management')\">\n                <div class=\"shortcut-icon\"><i class=\"bi bi-gift-fill\"></i></div>\n                <div>\n                  <div class=\"fw-bold\">جوایز</div>\n                  <small class=\"text-secondary\">بنر و هدایا</small>\n                </div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-sm-6\">\n              <div class=\"shortcut-card\" onclick=\"openAdminAuthModal()\" title=\"کلیک برای ورود یا تغییر کلید مدیریت\">\n                <div class=\"shortcut-icon\"><i class=\"bi bi-shield-lock-fill text-warning\"></i></div>\n                <div>\n                  <div class=\"fw-bold\">تنظیمات</div>\n                  <small class=\"text-secondary\">کلید و امنیت پنل</small>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Active Highlights (Competition & Announcement Summary) -->\n          <!-- Active Highlights (Competition Status) -->\n          <div class=\"row g-4\">\n            <div class=\"col-lg-12\">\n              <div class=\"card p-4 shadow\" style=\"border: 1.5px solid var(--gold-primary); background: linear-gradient(135deg, #152A44 0%, #0E1E36 100%);\">\n                <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-3\">\n                  <div class=\"d-flex align-items-center gap-2\">\n                    <i class=\"bi bi-trophy-fill text-warning fs-4\"></i>\n                    <div>\n                      <h5 class=\"gold-text mb-0 fw-bold\">مدیریت دوره فعال و آغاز مسابقه جدید</h5>\n                      <small class=\"text-secondary\">پایان دوره جاری، آرشیو امتیازات و صفر کردن امتیاز کل کاربران</small>\n                    </div>\n                  </div>\n                  <button class=\"btn btn-danger fw-bold px-4 py-2 shadow-sm\" onclick=\"openStartCompModal()\" style=\"font-size: 14px;\">\n                    <i class=\"bi bi-arrow-repeat me-1 fs-5\"></i> شروع دوره جدید و صفر کردن امتیاز همه کاربران\n                  </button>\n                </div>\n                <div class=\"p-3 rounded mb-2\" style=\"background-color: #0B192C; border: 1px solid var(--border-color);\">\n                  <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                    <span class=\"badge bg-warning text-dark fw-bold\" id=\"dashCompNumber\">دوره فعال</span>\n                    <span class=\"badge bg-success\">در حال برگزاری</span>\n                  </div>\n                  <h5 class=\"text-white mb-2\" id=\"dashCompTitle\">در حال بارگذاری...</h5>\n                  <div class=\"small text-secondary\">مهلت پایان: <span class=\"text-warning fw-bold\" id=\"dashCompEndedAt\">-</span></div>\n                </div>\n              </div>\n            </div>\n\n            <!-- Active Home Page Announcement Banner (Direct Control) -->\n            <div class=\"col-lg-12\">\n              <div class=\"card p-3 shadow\" style=\"border: 1.5px solid rgba(212, 175, 55, 0.4);\">\n                <div class=\"d-flex justify-content-between align-items-center mb-3\">\n                  <div class=\"d-flex align-items-center gap-2\">\n                    <i class=\"bi bi-megaphone-fill text-info fs-5\"></i>\n                    <h6 class=\"gold-text mb-0\">پیام زنده بالای ۱۰۰ مربع در اپلیکیشن</h6>\n                  </div>\n                  <div class=\"d-flex gap-2\">\n                    <button class=\"btn btn-sm btn-outline-info\" onclick=\"editCurrentActiveAnn()\"><i class=\"bi bi-pencil-square me-1\"></i> ویرایش پیام</button>\n                    <button class=\"btn btn-sm btn-outline-danger d-none\" id=\"dashAnnToggleBtn\" onclick=\"toggleCurrentActiveAnn()\">غیرفعال‌سازی</button>\n                  </div>\n                </div>\n                <div class=\"p-3 rounded\" style=\"background: linear-gradient(135deg, #0E1E36, #16253D); border: 1px solid rgba(255,183,3,0.3);\">\n                  <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                    <span class=\"badge bg-primary\" id=\"dashAnnType\">اطلاعیه</span>\n                    <span class=\"badge bg-success\" id=\"dashAnnStatus\">در حال نمایش</span>\n                  </div>\n                  <h5 class=\"text-warning mb-1 fw-bold\" id=\"dashAnnTitle\">در حال بارگذاری...</h5>\n                  <p class=\"text-white small mb-0\" id=\"dashAnnContent\">متن پیام...</p>\n                </div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- SECTION 2: مدیریت کاربران (Users Management) -->\n        <!-- ============================================================== -->\n        <section id=\"section-users\" class=\"admin-section\">\n          <div class=\"card p-4 shadow\">\n            <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4 pb-3 border-bottom border-secondary\">\n              <div>\n                <div class=\"d-flex flex-wrap align-items-center gap-2 mb-1\">\n                  <h4 class=\"gold-text mb-0\"><i class=\"bi bi-people-fill text-warning me-2\"></i> شرکت‌کنندگان دوره مسابقه فعلی</h4>\n                  <span class=\"new-users-summary-badge\" id=\"newUsersCountBadge\">\n                    <i class=\"bi bi-person-plus-fill\"></i>\n                    <span>کاربران جدید (۲۴ ساعت اخیر): ۰ نفر</span>\n                  </span>\n                </div>\n                <p class=\"text-secondary small mb-0\">فهرست زنده کاربران، برچسب ثبت‌نام جدید، تاریخ و ساعت دقیق عضویت (شمسی)، شماره موبایل و امتیازها</p>\n              </div>\n              <div class=\"d-flex flex-wrap align-items-center gap-2\">\n                <div style=\"width: 220px;\">\n                  <input type=\"text\" id=\"userSearchInput\" class=\"form-control form-control-sm form-control-dark\" placeholder=\"جستجو بر اساس نام یا شماره...\" oninput=\"filterUsers()\">\n                </div>\n                <select id=\"userFilterMode\" class=\"form-select form-select-sm form-select-dark\" style=\"width: auto; min-width: 150px;\" onchange=\"filterUsers()\">\n                  <option value=\"all\">همه کاربران</option>\n                  <option value=\"new\">فقط کاربران جدید</option>\n                </select>\n                <select id=\"userSortMode\" class=\"form-select form-select-sm form-select-dark\" style=\"width: auto; min-width: 175px;\" onchange=\"filterUsers()\">\n                  <option value=\"score\">مرتب‌سازی: بیشترین امتیاز</option>\n                  <option value=\"newest\">مرتب‌سازی: جدیدترین ثبت‌نام</option>\n                </select>\n                <button type=\"button\" id=\"exportUsersExcelBtn\" class=\"btn btn-sm btn-excel-export\" onclick=\"exportUsersExcel()\">\n                  <span class=\"spinner-border spinner-border-sm d-none\" id=\"exportUsersExcelSpinner\" role=\"status\" aria-hidden=\"true\"></span>\n                  <i class=\"bi bi-file-earmark-excel-fill\" id=\"exportUsersExcelIcon\"></i>\n                  <span id=\"exportUsersExcelLabel\">دانلود خروجی اکسل</span>\n                </button>\n                <a href=\"/admin/users\" class=\"btn btn-sm btn-outline-warning\" target=\"_blank\">\n                  <i class=\"bi bi-box-arrow-up-right me-1\"></i> صفحه جداگانه\n                </a>\n              </div>\n            </div>\n\n            <div class=\"users-selection-toolbar\">\n              <div class=\"d-flex flex-wrap align-items-center gap-3\">\n                <div class=\"form-check d-flex align-items-center gap-2 m-0 ps-0\">\n                  <input class=\"form-check-input user-select-checkbox m-0\" type=\"checkbox\" id=\"selectAllUsersCheckbox\" onchange=\"toggleSelectAllFilteredUsers(this.checked)\">\n                  <label class=\"form-check-label fw-bold text-light\" for=\"selectAllUsersCheckbox\" style=\"cursor: pointer;\">\n                    انتخاب همه\n                  </label>\n                  <small class=\"text-secondary\" id=\"selectAllScopeHint\">(۰ کاربر در فهرست)</small>\n                </div>\n                <span class=\"selected-count-badge\" id=\"selectedUsersCountBadge\">\n                  <i class=\"bi bi-check2-square\"></i>\n                  <span>انتخاب‌شده: ۰ نفر</span>\n                </span>\n              </div>\n\n              <div class=\"d-flex flex-wrap align-items-center gap-2\">\n                <button type=\"button\" id=\"exportSelectedUsersExcelBtn\" class=\"btn btn-sm btn-excel-selected\" onclick=\"exportSelectedUsersExcel()\">\n                  <span class=\"spinner-border spinner-border-sm d-none\" id=\"exportSelectedUsersExcelSpinner\" role=\"status\" aria-hidden=\"true\"></span>\n                  <i class=\"bi bi-file-earmark-spreadsheet-fill\" id=\"exportSelectedUsersExcelIcon\"></i>\n                  <span id=\"exportSelectedUsersExcelLabel\">دانلود اکسل انتخاب‌شده‌ها</span>\n                </button>\n                <button type=\"button\" id=\"clearUserSelectionBtn\" class=\"btn btn-sm btn-outline-light d-none\" onclick=\"clearUserSelection()\">\n                  <i class=\"bi bi-x-circle me-1\"></i> پاک‌کردن انتخاب‌ها\n                </button>\n              </div>\n            </div>\n\n            <div id=\"usersSelectionNotice\" class=\"alert d-none py-2 px-3 small mb-3\" role=\"alert\"></div>\n\n            <div class=\"table-responsive\">\n              <table class=\"table table-dark table-hover table-striped rounded align-middle\">\n                <thead>\n                  <tr class=\"text-secondary small\">\n                    <th style=\"width: 46px;\" class=\"text-center\">\n                      <input class=\"form-check-input user-select-checkbox m-0\" type=\"checkbox\" id=\"usersPageSelectAll\" title=\"انتخاب کاربران این صفحه\" aria-label=\"انتخاب کاربران این صفحه\" onchange=\"toggleCurrentPageUsersSelection(this.checked)\">\n                    </th>\n                    <th style=\"width: 60px;\">رتبه</th>\n                    <th>نام و نام خانوادگی</th>\n                    <th>شماره همراه</th>\n                    <th style=\"min-width: 165px;\">تاریخ و ساعت ثبت‌نام</th>\n                    <th>مجموع امتیاز</th>\n                    <th style=\"width: 140px;\">عملیات</th>\n                  </tr>\n                </thead>\n                <tbody id=\"usersTbody\">\n                  <tr><td colspan=\"7\" class=\"text-center py-4 text-secondary\">در حال بارگذاری اطلاعات کاربران...</td></tr>\n                </tbody>\n              </table>\n            </div>\n\n            <div id=\"usersPaginationBar\" class=\"users-pagination-bar\">\n              <div class=\"d-flex flex-wrap align-items-center gap-2 small text-secondary\">\n                <span id=\"usersPaginationInfo\">نمایش ۰ کاربر</span>\n                <select id=\"usersPageSizeSelect\" class=\"form-select form-select-sm form-select-dark\" style=\"width: auto;\" onchange=\"changeUsersPageSize(this.value)\" aria-label=\"تعداد کاربر در هر صفحه\">\n                  <option value=\"15\">۱۵ در صفحه</option>\n                  <option value=\"25\" selected>۲۵ در صفحه</option>\n                  <option value=\"50\">۵۰ در صفحه</option>\n                  <option value=\"100\">۱۰۰ در صفحه</option>\n                </select>\n              </div>\n              <div id=\"usersPaginationButtons\" class=\"d-flex flex-wrap align-items-center gap-1\"></div>\n            </div>\n          </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <section id=\"section-store\" class=\"admin-section\">\n          <!-- Overview Metric Cards -->\n          <div class=\"row g-3 mb-4\">\n            <div class=\"col-md-3 col-6\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-header\">\n                  <span class=\"stat-label\">تعداد بسته‌های فروشگاه</span>\n                  <div class=\"stat-icon-wrap\" style=\"color: #FFB703; background: rgba(255,183,3,0.15);\">\n                    <i class=\"bi bi-box-seam-fill\"></i>\n                  </div>\n                </div>\n                <div class=\"stat-value\" id=\"storePackagesCount\">۴ بسته</div>\n                <div class=\"stat-subtext text-warning\"><i class=\"bi bi-check-circle me-1\"></i> فعال و قابل ارتقا</div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-6\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-header\">\n                  <span class=\"stat-label\">تعداد خریدهای موفق</span>\n                  <div class=\"stat-icon-wrap\" style=\"color: #10B981; background: rgba(16,185,129,0.15);\">\n                    <i class=\"bi bi-bag-check-fill\"></i>\n                  </div>\n                </div>\n                <div class=\"stat-value text-success\" id=\"storeTotalPurchases\">۰ تراکنش</div>\n                <div class=\"stat-subtext text-secondary\">ثبت شده در سرور</div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-6\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-header\">\n                  <span class=\"stat-label\">مجموع فروش فروشگاه</span>\n                  <div class=\"stat-icon-wrap\" style=\"color: #38BDF8; background: rgba(56,189,248,0.15);\">\n                    <i class=\"bi bi-cash-stack\"></i>\n                  </div>\n                </div>\n                <div class=\"stat-value text-info\" id=\"storeTotalRevenue\">۰ تومان</div>\n                <div class=\"stat-subtext text-secondary\">درآمد ناخالص بسته‌ها</div>\n              </div>\n            </div>\n            <div class=\"col-md-3 col-6\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-header\">\n                  <span class=\"stat-label\">اتصال پرداخت مایکت</span>\n                  <div class=\"stat-icon-wrap\" style=\"color: #A855F7; background: rgba(168,85,247,0.15);\">\n                    <i class=\"bi bi-shield-check\"></i>\n                  </div>\n                </div>\n                <div class=\"stat-value text-warning\" style=\"font-size: 16px;\" id=\"storeMyketStatus\">آماده‌سازی کنسول</div>\n                <div class=\"stat-subtext text-secondary\">IAB رسمی نسخه ۳ مایکت</div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Product Management Card -->\n          <div class=\"card p-4 shadow mb-4\" style=\"border: 1px solid #FFB703; background-color: #12253B;\">\n            <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3\">\n              <div>\n                <h4 class=\"gold-text fw-bold mb-1\"><i class=\"bi bi-shop me-2\"></i> مدیریت قیمت‌های فروشگاه (۴ بسته اصلی)</h4>\n                <p class=\"text-secondary small mb-0\">امکان تغییر قیمت ۴ بسته ثابت (دو بسته مربع و دو سطح ارتقای نقره‌ای و طلایی). نام، تعداد، ضرایب و مشخصات ثابت هستند.</p>\n              </div>\n              <div class=\"d-flex gap-2\">\n                <button class=\"btn btn-outline-warning btn-sm\" onclick=\"loadStoreProducts()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> بروزرسانی</button>\n              </div>\n            </div>\n\n            <div class=\"table-responsive\">\n              <table class=\"table table-hover align-middle mb-0 text-white\">\n                <thead class=\"table-dark\" style=\"border-bottom: 2px solid var(--border-color);\">\n                  <tr class=\"small text-secondary\">\n                    <th>عنوان بسته</th>\n                    <th>نوع محصول</th>\n                    <th>محتوا / سهمیه</th>\n                    <th>قیمت (تومان) - قابل ویرایش</th>\n                    <th>شناسه مایکت (SKU)</th>\n                    <th>وضعیت نمایش</th>\n                    <th>عملیات ویرایش قیمت</th>\n                  </tr>\n                </thead>\n                <tbody id=\"storeProductsTbody\">\n                  <tr><td colspan=\"7\" class=\"text-center text-secondary py-4\"><span class=\"spinner-border spinner-border-sm me-2\"></span> در حال بارگذاری بسته‌ها...</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n\n          <!-- Purchase Orders & Transactions Audit Card -->\n          <div class=\"card p-4 shadow\" style=\"border: 1px solid var(--border-color); background-color: #12253B;\">\n            <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3\">\n              <div>\n                <h4 class=\"text-info fw-bold mb-1\"><i class=\"bi bi-receipt-cutoff me-2\"></i> گزارش تراکنش‌ها و سفارش‌های خرید مایکت</h4>\n                <p class=\"text-secondary small mb-0\">سوابق اعتبارسنجی توکن، سفارش‌های تکمیل‌شده و لاگ خطاهای پرداخت</p>\n              </div>\n              <button class=\"btn btn-outline-info btn-sm\" onclick=\"loadStorePurchases()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> بروزرسانی لاگ</button>\n            </div>\n\n            <div class=\"table-responsive\">\n              <table class=\"table table-hover align-middle mb-0 text-white\">\n                <thead class=\"table-dark\" style=\"border-bottom: 2px solid var(--border-color);\">\n                  <tr class=\"small text-secondary\">\n                    <th>شناسه سفارش</th>\n                    <th>کاربر / موبایل</th>\n                    <th>بسته خریداری‌شده</th>\n                    <th>مبلغ پرداختی</th>\n                    <th>توکن خرید مایکت</th>\n                    <th>وضعیت وریفای</th>\n                    <th>تاریخ ثبت</th>\n                  </tr>\n                </thead>\n                <tbody id=\"storePurchasesTbody\">\n                  <tr><td colspan=\"7\" class=\"text-center text-secondary py-4\">در حال بارگذاری تراکنش‌ها...</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- Unified Rewards Management Section -->\n        <!-- ============================================================== -->\n        <section id=\"section-rewards_management\" class=\"admin-section\">\n          <div class=\"card p-0 shadow mb-4\" style=\"border: 1px solid var(--border-color); background-color: #12253B; overflow: hidden;\">\n            <!-- Custom Navigation Tabs -->\n            <ul class=\"nav nav-tabs nav-justified border-0 bg-dark bg-opacity-25\" id=\"rewardsTabs\" role=\"tablist\">\n              <li class=\"nav-item\" role=\"presentation\">\n                <button class=\"nav-link active text-white py-3 fw-bold\" id=\"tab-rewards-list\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-rewards-list\" type=\"button\" role=\"tab\" onclick=\"loadRewardsData()\">\n                  <i class=\"bi bi-list-stars me-1\"></i> فهرست هدایا\n                </button>\n              </li>\n              <li class=\"nav-item\" role=\"presentation\">\n                <button class=\"nav-link text-white py-3 fw-bold\" id=\"tab-rewards-banner\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-rewards-banner\" type=\"button\" role=\"tab\" onclick=\"loadRewardAppearance()\">\n                  <i class=\"bi bi-palette-fill me-1\"></i> بنر و ظاهر ویترین\n                </button>\n              </li>\n              <li class=\"nav-item\" role=\"presentation\">\n                <button class=\"nav-link text-white py-3 fw-bold\" id=\"tab-rewards-claims\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-rewards-claims\" type=\"button\" role=\"tab\" onclick=\"loadRewardClaims()\">\n                  <i class=\"bi bi-inbox-fill me-1\"></i> درخواست‌های دریافتی\n                  <span class=\"badge bg-danger rounded-pill ms-1\" id=\"tabClaimsBadge\">۰</span>\n                </button>\n              </li>\n            </ul>\n\n            <div class=\"tab-content p-4\" id=\"rewardsTabsContent\">\n              <!-- Tab 1: Rewards List -->\n              <div class=\"tab-pane fade show active\" id=\"panel-rewards-list\" role=\"tabpanel\">\n                <div class=\"d-flex justify-content-between align-items-center mb-4\">\n                  <div>\n                    <h5 class=\"gold-text mb-1\">تعریف و مدیریت کالاهای جایزه</h5>\n                    <p class=\"text-secondary small mb-0\">تعیین امتیاز لازم، موجودی انبار و تصویر جوایز برای نمایش در اپلیکیشن</p>\n                  </div>\n                  <div class=\"d-flex gap-2\">\n                    <button class=\"btn btn-outline-info btn-sm\" onclick=\"loadRewardsData()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> بروزرسانی</button>\n                    <button class=\"btn btn-warning btn-sm fw-bold\" onclick=\"openAddRewardModal()\"><i class=\"bi bi-plus-circle-fill me-1\"></i> افزودن جایزه جدید</button>\n                  </div>\n                </div>\n                <div class=\"table-responsive\">\n                  <table class=\"table table-hover align-middle mb-0 text-white\">\n                    <thead class=\"table-dark\">\n                      <tr class=\"small text-secondary\">\n                        <th>تصویر & عنوان جایزه</th>\n                        <th>دسته‌بندی</th>\n                        <th>امتیاز لازم</th>\n                        <th>موجودی</th>\n                        <th>ویژه</th>\n                        <th>وضعیت</th>\n                        <th>عملیات</th>\n                      </tr>\n                    </thead>\n                    <tbody id=\"rewardsTbody\"></tbody>\n                  </table>\n                </div>\n              </div>\n\n              <!-- Tab 2: Banner Settings -->\n              <div class=\"tab-pane fade\" id=\"panel-rewards-banner\" role=\"tabpanel\">\n                <h5 class=\"gold-text mb-3\">تنظیمات بصری و بنر اصلی جوایز</h5>\n                <form onsubmit=\"saveRewardAppearance(event)\">\n                  <div class=\"row g-3\">\n                    <div class=\"col-md-8\">\n                      <label class=\"form-label text-secondary small fw-bold\">عنوان بنر هدیه (Hero Title):</label>\n                      <input type=\"text\" id=\"rewAppHeroTitle\" class=\"form-control form-control-dark mb-3\" required>\n                      <label class=\"form-label text-secondary small fw-bold\">زیرعنوان بنر:</label>\n                      <input type=\"text\" id=\"rewAppHeroSubtitle\" class=\"form-control form-control-dark mb-3\">\n                      <label class=\"form-label text-secondary small fw-bold\">متن راهنما و قوانین:</label>\n                      <textarea id=\"rewAppTermsText\" rows=\"3\" class=\"form-control form-control-dark\"></textarea>\n                    </div>\n                    <div class=\"col-md-4\">\n                      <label class=\"form-label text-secondary small fw-bold\">رنگ تم اصلی:</label>\n                      <input type=\"color\" id=\"rewAppColor\" class=\"form-control form-control-color w-100 bg-dark mb-3\" style=\"height: 38px;\">\n                      \n                      <div class=\"form-check form-switch mb-3\">\n                        <input class=\"form-check-input\" type=\"checkbox\" id=\"rewAppIsActive\" checked>\n                        <label class=\"form-check-label text-white small\" for=\"rewAppIsActive\">نمایش بنر در اپلیکیشن</label>\n                      </div>\n\n                      <button type=\"submit\" class=\"btn btn-gold w-100 fw-bold\">\n                        <i class=\"bi bi-save me-1\"></i> ذخیره تنظیمات\n                      </button>\n                    </div>\n                    <div class=\"col-12 mt-3\">\n                      <label class=\"form-label text-secondary small fw-bold\">تصویر بنر (بارگذاری مستقیم):</label>\n                      <div class=\"p-3 rounded bg-dark bg-opacity-50 border border-secondary text-center\">\n                        <input type=\"file\" id=\"rewAppImageFile\" accept=\"image/*\" class=\"d-none\" onchange=\"handleBannerImageSelect(event)\">\n                        <input type=\"hidden\" id=\"rewAppBannerUrl\">\n                        <div id=\"rewAppPreviewContainer\" class=\"mb-3 d-none\">\n                          <img id=\"rewAppPreviewImg\" class=\"rounded shadow border border-warning\" style=\"max-height: 200px; max-width: 100%;\">\n                          <div class=\"mt-2\">\n                            <button type=\"button\" class=\"btn btn-sm btn-outline-danger\" onclick=\"removeBannerImage()\">حذف تصویر</button>\n                          </div>\n                        </div>\n                        <div id=\"rewAppUploadPrompt\">\n                          <button type=\"button\" class=\"btn btn-outline-warning\" onclick=\"document.getElementById('rewAppImageFile').click()\">\n                            <i class=\"bi bi-upload me-1\"></i> انتخاب تصویر جدید\n                          </button>\n                        </div>\n                        <div id=\"rewAppUploadProgressWrapper\" class=\"mt-3 d-none\">\n                          <div class=\"progress\" style=\"height: 8px;\">\n                            <div id=\"rewAppUploadProgressBar\" class=\"progress-bar bg-warning\" style=\"width: 0%\"></div>\n                          </div>\n                          <small id=\"rewAppUploadStatusText\" class=\"text-secondary mt-1 d-block\">در حال آپلود...</small>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </form>\n              </div>\n\n              <!-- Tab 3: Claims Management -->\n              <div class=\"tab-pane fade\" id=\"panel-rewards-claims\" role=\"tabpanel\">\n                <div class=\"d-flex justify-content-between align-items-center mb-4\">\n                  <div>\n                    <h5 class=\"gold-text mb-1\">درخواست‌های ثبت‌شده توسط کاربران</h5>\n                    <p class=\"text-secondary small mb-0\">مدیریت وضعیت ارسال هدایا و تایید نهایی</p>\n                  </div>\n                  <button class=\"btn btn-outline-info btn-sm\" onclick=\"loadRewardClaims()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> بروزرسانی لیست</button>\n                </div>\n                <div class=\"table-responsive\">\n                  <table class=\"table table-hover align-middle mb-0 text-white\">\n                    <thead class=\"table-dark\">\n                      <tr class=\"small text-secondary\">\n                        <th>کد پیگیری</th>\n                        <th>کاربر</th>\n                        <th>جایزه</th>\n                        <th>امتیاز</th>\n                        <th>گیرنده & آدرس</th>\n                        <th>وضعیت</th>\n                        <th>مدیریت</th>\n                      </tr>\n                    </thead>\n                    <tbody id=\"rewardClaimsTbody\"></tbody>\n                  </table>\n                </div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n\n\n        <!-- ============================================================== -->\n        <!-- SECTION 5: پشتیبانی (Support) -->\n        <!-- ============================================================== -->\n        <!-- ============================================================== -->\n        <!-- SECTION 6: مدیریت پیام صفحه ورود (Login Notification Management) -->\n        <!-- ============================================================== -->\n        <section id=\"section-login_notification\" class=\"admin-section\">\n          <div class=\"row g-4\">\n            <!-- Form Column -->\n            <div class=\"col-lg-7\">\n              <div class=\"card p-4 shadow h-100\">\n                <div class=\"d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom border-secondary\">\n                  <div>\n                    <h4 class=\"gold-text mb-1\"><i class=\"bi bi-megaphone-fill me-2\"></i> تنظیمات محتوای صفحه ورود</h4>\n                    <p class=\"text-secondary small mb-0\">ویرایش متن‌ها، آیکون‌ها و وضعیت نمایش کارت اطلاع‌رسانی ایرانسل</p>\n                  </div>\n                  <button class=\"btn btn-outline-warning btn-sm\" onclick=\"loadLoginNotification()\"><i class=\"bi bi-arrow-clockwise\"></i></button>\n                </div>\n\n                <form id=\"loginNotifForm\" onsubmit=\"saveLoginNotification(event)\">\n                  <div class=\"row g-3\">\n                    <div class=\"col-12\">\n                      <div class=\"form-check form-switch p-3 rounded bg-dark bg-opacity-25 border border-secondary mb-3\">\n                        <input class=\"form-check-input ms-0 me-2\" type=\"checkbox\" id=\"ln_isVisible\" checked onchange=\"updateLNPreview()\">\n                        <label class=\"form-check-label text-white fw-bold\" for=\"ln_isVisible\">نمایش کل کارت اطلاع‌رسانی در اپلیکیشن</label>\n                      </div>\n                    </div>\n\n                    <div class=\"col-md-8\">\n                      <label class=\"form-label text-secondary small fw-bold\">متن برچسب (Badge):</label>\n                      <input type=\"text\" id=\"ln_badgeText\" class=\"form-control form-control-dark mb-3\" placeholder=\"مثلاً: سرویس اختصاصی مشترکین ایرانسل\" oninput=\"updateLNPreview()\">\n                    </div>\n                    <div class=\"col-md-4\">\n                      <label class=\"form-label text-secondary small fw-bold\">آیکون برچسب:</label>\n                      <select id=\"ln_badgeIcon\" class=\"form-select form-select-dark mb-3\" onchange=\"updateLNPreview()\">\n                        <option value=\"verified\">Verified (تایید شده)</option>\n                        <option value=\"stars\">Stars (ستاره)</option>\n                        <option value=\"check_circle\">Check Circle</option>\n                        <option value=\"emoji_events\">Trophy</option>\n                      </select>\n                    </div>\n\n                    <div class=\"col-12\">\n                      <label class=\"form-label text-secondary small fw-bold\">عنوان اصلی (Literary Title):</label>\n                      <input type=\"text\" id=\"ln_mainTitle\" class=\"form-control form-control-dark mb-3\" oninput=\"updateLNPreview()\">\n                    </div>\n\n                    <div class=\"col-12\">\n                      <label class=\"form-label text-secondary small fw-bold\">متن توضیحات اصلی:</label>\n                      <textarea id=\"ln_mainDescription\" rows=\"3\" class=\"form-control form-control-dark mb-3\" oninput=\"updateLNPreview()\"></textarea>\n                    </div>\n\n                    <div class=\"col-12\">\n                      <div class=\"p-3 rounded border border-info border-opacity-25 bg-info bg-opacity-10 mb-3\">\n                        <div class=\"form-check form-switch mb-3\">\n                          <input class=\"form-check-input ms-0 me-2\" type=\"checkbox\" id=\"ln_warningIsVisible\" checked onchange=\"updateLNPreview()\">\n                          <label class=\"form-check-label text-info fw-bold\" for=\"ln_warningIsVisible\">نمایش کادر هشدار اینترنت</label>\n                        </div>\n                        \n                        <div class=\"row g-3\">\n                          <div class=\"col-md-8\">\n                            <label class=\"form-label text-secondary small fw-bold\">عنوان کادر هشدار:</label>\n                            <input type=\"text\" id=\"ln_warningTitle\" class=\"form-control form-control-dark mb-2\" oninput=\"updateLNPreview()\">\n                          </div>\n                          <div class=\"col-md-4\">\n                            <label class=\"form-label text-secondary small fw-bold\">آیکون هشدار:</label>\n                            <select id=\"ln_warningIcon\" class=\"form-select form-select-dark mb-2\" onchange=\"updateLNPreview()\">\n                              <option value=\"signal_cellular_alt\">Signal (آنتن)</option>\n                              <option value=\"wifi_off\">Wifi Off</option>\n                              <option value=\"cell_tower\">Cell Tower</option>\n                            </select>\n                          </div>\n                          <div class=\"col-12\">\n                            <label class=\"form-label text-secondary small fw-bold\">توضیحات هشدار:</label>\n                            <textarea id=\"ln_warningDescription\" rows=\"2\" class=\"form-control form-control-dark\" oninput=\"updateLNPreview()\"></textarea>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n\n                    <div class=\"col-12 d-flex gap-2\">\n                      <button type=\"submit\" class=\"btn btn-gold flex-grow-1 py-2 fw-bold\">\n                        <i class=\"bi bi-save2-fill me-1\"></i> ذخیره و انتشار آنی در اپلیکیشن\n                      </button>\n                      <button type=\"button\" class=\"btn btn-outline-secondary\" onclick=\"resetLoginNotificationDefaults()\">\n                        <i class=\"bi bi-arrow-counterclockwise me-1\"></i> بازگشت به پیش‌فرض ایرانسل\n                      </button>\n                    </div>\n                  </div>\n                </form>\n              </div>\n            </div>\n\n            <!-- Preview Column -->\n            <div class=\"col-lg-5\">\n              <div class=\"card p-4 shadow h-100 bg-black bg-opacity-25\" style=\"border-style: dashed;\">\n                <h6 class=\"text-secondary fw-bold mb-4 text-center\"><i class=\"bi bi-eye-fill me-1\"></i> پیش‌نمایش زنده (Live Preview)</h6>\n                \n                <div class=\"d-flex justify-content-center align-items-center h-100\">\n                  <!-- App Screen Mockup -->\n                  <div style=\"width: 320px; background-color: #F1F5F9; border-radius: 30px; border: 8px solid #334155; padding: 20px; min-height: 500px; box-shadow: 0 20px 50px rgba(0,0,0,0.5);\">\n                    <!-- Header Mockup -->\n                    <div style=\"height: 120px; background: linear-gradient(to bottom, #0B192C, #1E3E62); border-radius: 0 0 20px 20px; margin: -20px -20px 20px -20px; display: flex; align-items: center; justify-content: center;\">\n                       <div style=\"width: 40px; height: 40px; background: #FFB703; border-radius: 50%; display: flex; align-items: center; justify-content: center;\">\n                         <i class=\"bi bi-trophy-fill\" style=\"color: #0B192C;\"></i>\n                       </div>\n                    </div>\n\n                    <!-- Dynamic Card Preview -->\n                    <div id=\"ln_preview_container\" style=\"display: none;\">\n                      <div style=\"background: linear-gradient(135deg, #0F2542, #16325B); border: 1.5px solid #FFB703; border-radius: 18px; padding: 15px; box-shadow: 0 8px 15px rgba(0,0,0,0.2); text-align: center;\">\n                        <!-- Badge -->\n                        <div style=\"display: inline-block; background: linear-gradient(to right, #FFB703, #FB8500); border-radius: 20px; padding: 4px 12px; margin-bottom: 10px;\">\n                          <div style=\"display: flex; align-items: center; gap: 5px; font-size: 9px; font-weight: 900; color: #0B192C;\">\n                            <i id=\"ln_preview_badgeIcon\" class=\"bi bi-patch-check-fill\"></i>\n                            <span id=\"ln_preview_badgeText\">سرویس اختصاصی</span>\n                          </div>\n                        </div>\n                        \n                        <!-- Title -->\n                        <h6 id=\"ln_preview_mainTitle\" style=\"color: #FFB703; font-weight: 900; font-size: 13px; line-height: 1.4; margin-bottom: 8px;\">عنوان اصلی</h6>\n                        \n                        <!-- Desc -->\n                        <p id=\"ln_preview_mainDescription\" style=\"color: rgba(255,255,255,0.9); font-size: 10px; line-height: 1.5; margin-bottom: 12px;\">توضیحات مربوط به سرویس ایرانسل</p>\n                        \n                        <!-- Warning -->\n                        <div id=\"ln_preview_warningBox\" style=\"background: rgba(10,25,47,0.8); border: 1px solid rgba(255,183,3,0.3); border-radius: 12px; padding: 10px; text-align: right; display: flex; gap: 10px; align-items: flex-start;\">\n                          <div style=\"width: 24px; height: 24px; background: rgba(255,183,3,0.15); border-radius: 50%; flex-shrink: 0; display: flex; align-items: center; justify-content: center;\">\n                            <i id=\"ln_preview_warningIcon\" class=\"bi bi-reception-4\" style=\"color: #FFB703; font-size: 12px;\"></i>\n                          </div>\n                          <div>\n                            <div id=\"ln_preview_warningTitle\" style=\"color: #FFB703; font-weight: 800; font-size: 11px; margin-bottom: 2px;\">شرط الزامی</div>\n                            <div id=\"ln_preview_warningDescription\" style=\"color: #CBD5E1; font-size: 9px; line-height: 1.4;\">توضیحات هشدار اینترنت</div>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                    \n                    <div id=\"ln_preview_hidden_msg\" style=\"text-align: center; color: #64748B; font-size: 11px; margin-top: 50px;\">\n                       <i class=\"bi bi-eye-slash-fill d-block fs-3 mb-2\"></i>\n                       کارت اطلاع‌رسانی مخفی شده است\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <section id=\"section-support\" class=\"admin-section\">\n          <!-- Stat Cards Row -->\n          <div class=\"row g-3 mb-4\">\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-info bg-opacity-10 text-info\">\n                  <i class=\"bi bi-chat-left-text-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">کل تیکت‌ها</div>\n                <h3 id=\"supportCountTotal\" class=\"gold-text mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-danger bg-opacity-10 text-danger\">\n                  <i class=\"bi bi-exclamation-circle-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">جدید / بی‌پاسخ</div>\n                <h3 id=\"supportCountNew\" class=\"text-danger mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-warning bg-opacity-10 text-warning\">\n                  <i class=\"bi bi-clock-history\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">در حال بررسی</div>\n                <h3 id=\"supportCountInProgress\" class=\"text-warning mb-0\">-</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-success bg-opacity-10 text-success\">\n                  <i class=\"bi bi-check-all\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">پاسخ داده شده</div>\n                <h3 id=\"supportCountAnswered\" class=\"text-success mb-0\">-</h3>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"card p-4 shadow\">\n            <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4 pb-3 border-bottom border-secondary\">\n              <div>\n                <h4 class=\"gold-text mb-1\"><i class=\"bi bi-headset text-warning me-2\"></i> مرکز پشتیبانی و تیکت‌ها</h4>\n                <p class=\"text-secondary small mb-0\">فهرست پیام‌های دریافتی از کاربران و پاسخگویی آنلاین</p>\n              </div>\n              <div class=\"d-flex gap-2 flex-wrap\">\n                <select id=\"supportStatusFilter\" class=\"form-select form-select-sm form-select-dark\" style=\"width: 140px;\" onchange=\"filterSupportTickets()\">\n                  <option value=\"ALL\">همه وضعیت‌ها</option>\n                  <option value=\"NEW\">جدید</option>\n                  <option value=\"IN_PROGRESS\">در حال بررسی</option>\n                  <option value=\"ANSWERED\">پاسخ داده شده</option>\n                  <option value=\"CLOSED\">بسته شده</option>\n                </select>\n                <select id=\"supportCategoryFilter\" class=\"form-select form-select-sm form-select-dark\" style=\"width: 140px;\" onchange=\"filterSupportTickets()\">\n                  <option value=\"ALL\">همه موضوعات</option>\n                  <option value=\"SCORES\">امتیازها</option>\n                  <option value=\"ADS\">تبلیغات</option>\n                  <option value=\"PRIZES\">جوایز</option>\n                  <option value=\"PURCHASE\">خرید</option>\n                  <option value=\"OTHER\">سایر</option>\n                </select>\n                <div style=\"width: 200px;\">\n                  <input type=\"text\" id=\"supportSearchInput\" class=\"form-control form-control-sm form-control-dark\" placeholder=\"جستجو کد یا شماره...\" oninput=\"filterSupportTickets()\">\n                </div>\n                <button class=\"btn btn-sm btn-outline-warning\" onclick=\"loadAdminSupportTickets()\">\n                  <i class=\"bi bi-arrow-clockwise\"></i>\n                </button>\n              </div>\n            </div>\n\n            <div class=\"mb-3 small text-secondary\" id=\"supportFilterSummary\">در حال دریافت آمار...</div>\n\n            <div class=\"table-responsive\">\n              <table class=\"table table-dark table-hover table-striped rounded align-middle\">\n                <thead>\n                  <tr class=\"text-secondary small\">\n                    <th style=\"width: 110px;\">کد پیگیری</th>\n                    <th>نام کاربر / موبایل</th>\n                    <th>دسته</th>\n                    <th>موضوع تیکت</th>\n                    <th>وضعیت</th>\n                    <th>آخرین پیام</th>\n                    <th>بروزرسانی</th>\n                    <th style=\"width: 100px;\">عملیات</th>\n                  </tr>\n                </thead>\n                <tbody id=\"supportTicketsTbody\">\n                  <tr><td colspan=\"8\" class=\"text-center py-4 text-secondary\">در حال بارگذاری تیکت‌های پشتیبانی...</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- SECTION 9: تنظیمات و دسترسی (Settings) -->\n        <!-- ============================================================== -->\n        <section id=\"section-settings\" class=\"admin-section\">\n          <div class=\"row g-4\">\n            <div class=\"col-lg-6\">\n              <div class=\"card p-4 shadow\">\n                <h4 class=\"gold-text mb-3\"><i class=\"bi bi-key-fill text-warning me-2\"></i> احراز هویت مدیریت (ADMIN_KEY)</h4>\n                <p class=\"text-secondary small mb-3\">\n                  برای امنیت پنل و جلوگیری از دسترسی غیرمجاز به اطلاعات کاربران، کلید امنیتی مدیریت در مرورگر شما ذخیره شده و با هر درخواست به سرور ارسال می‌شود.\n                </p>\n                <div class=\"mb-3\">\n                  <label class=\"form-label text-secondary small fw-bold\">کلید امنیتی فعلی:</label>\n                  <input type=\"password\" id=\"adminKeyInput\" class=\"form-control form-control-dark\" placeholder=\"کلید امنیتی ادمین...\">\n                </div>\n                <button class=\"btn btn-gold px-4\" onclick=\"saveAdminKey()\">\n                  <i class=\"bi bi-save me-1\"></i> تایید و ذخیره کلید\n                </button>\n              </div>\n            </div>\n\n            <div class=\"col-lg-6\">\n              <div class=\"card p-4 shadow\">\n                <h4 class=\"text-info mb-3\"><i class=\"bi bi-server me-2\"></i> مشخصات فنی سرور و پایگاه داده</h4>\n                <ul class=\"list-unstyled text-secondary small d-flex flex-column gap-2 mb-0\">\n                  <li><strong class=\"text-white\">میزبانی سرور:</strong> Render Cloud Service (Node.js)</li>\n                  <li><strong class=\"text-white\">پایگاه داده:</strong> Supabase Cloud PostgreSQL (Connection Pooler)</li>\n                  <li><strong class=\"text-white\">اعلان‌های پوش:</strong> OneSignal REST API v1</li>\n                  <li><strong class=\"text-white\">سیستم امنیت تبلیغات:</strong> توکن‌های یکبارمصرف و اعتبارسنجی تپسل پلاس</li>\n                </ul>\n              </div>\n            </div>\n          </div>\n        </section>\n\n        <!-- ============================================================== -->\n        <!-- SECTION 10: مدیریت بنرهای تبلیغاتی (Ad Banners Management)     -->\n        <!-- ============================================================== -->\n        <section id=\"section-ad_banners\" class=\"admin-section\">\n          <div class=\"row g-3 mb-4\">\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-warning bg-opacity-10 text-warning\">\n                  <i class=\"bi bi-images\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">کل بنرهای تبلیغاتی</div>\n                <h3 id=\"adBannersTotalCount\" class=\"gold-text mb-0\">۰</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-success bg-opacity-10 text-success\">\n                  <i class=\"bi bi-broadcast\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">تبلیغات فعال و در حال نمایش</div>\n                <h3 id=\"adBannersActiveCount\" class=\"text-success mb-0\">۰</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-info bg-opacity-10 text-info\">\n                  <i class=\"bi bi-eye-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">مجموع نمایش (Impressions)</div>\n                <h3 id=\"adBannersTotalImpressions\" class=\"text-info mb-0\">۰</h3>\n              </div>\n            </div>\n            <div class=\"col-sm-6 col-xl-3\">\n              <div class=\"stat-card\">\n                <div class=\"stat-card-icon bg-primary bg-opacity-10 text-primary\">\n                  <i class=\"bi bi-hand-index-thumb-fill\"></i>\n                </div>\n                <div class=\"text-secondary small fw-bold mb-1\">مجموع کلیک / نرخ CTR</div>\n                <h3 id=\"adBannersTotalClicksCtr\" class=\"text-white mb-0\">۰ (۰٪)</h3>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"card p-4 shadow\">\n            <div class=\"d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4 pb-3 border-bottom border-secondary\">\n              <div>\n                <h4 class=\"gold-text mb-1\"><i class=\"bi bi-badge-ad-fill text-warning me-2\"></i> مدیریت بنرهای تبلیغاتی تصویری و لینک‌دار</h4>\n                <p class=\"text-secondary small mb-0\">\n                  بنرهای فعال و معتبر به‌صورت اسلایدر و با ترتیب مشخص در صفحه اصلی اپلیکیشن نمایش داده می‌شوند. لینک مقصد هرگز در ظاهر عادی اپلیکیشن چاپ نمی‌شود.\n                </p>\n              </div>\n              <div class=\"d-flex gap-2 flex-wrap\">\n                <button class=\"btn btn-gold fw-bold px-3\" onclick=\"openAdBannerModal()\">\n                  <i class=\"bi bi-plus-circle-fill me-1\"></i> ایجاد تبلیغ جدید\n                </button>\n                <button class=\"btn btn-outline-warning btn-sm\" onclick=\"loadAdBanners()\">\n                  <i class=\"bi bi-arrow-clockwise\"></i> به‌روزرسانی\n                </button>\n              </div>\n            </div>\n\n            <div class=\"row g-2 mb-3 align-items-center\">\n              <div class=\"col-md-4\">\n                <input type=\"text\" id=\"adBannerSearchInput\" class=\"form-control form-control-sm form-control-dark\" placeholder=\"جستجو بر اساس نام داخلی تبلیغ یا آدرس مقصد...\" oninput=\"renderAdBannersTable()\">\n              </div>\n              <div class=\"col-md-3\">\n                <select id=\"adBannerStatusFilter\" class=\"form-select form-select-sm form-select-dark\" onchange=\"renderAdBannersTable()\">\n                  <option value=\"all\">همه وضعیت‌ها</option>\n                  <option value=\"active\">فعال (در حال نمایش)</option>\n                  <option value=\"inactive\">غیرفعال</option>\n                  <option value=\"scheduled\">زمان‌بندی‌شده (شروع در آینده)</option>\n                  <option value=\"expired\">منقضی‌شده</option>\n                </select>\n              </div>\n              <div class=\"col-md-3\">\n                <select id=\"adBannerPlacementFilter\" class=\"form-select form-select-sm form-select-dark\" onchange=\"renderAdBannersTable()\">\n                  <option value=\"all\">همه محل‌های نمایش</option>\n                  <option value=\"home\">صفحه اصلی</option>\n                  <option value=\"leaderboard\">جدول رتبه‌بندی</option>\n                  <option value=\"profile\">پروفایل کاربر</option>\n                  <option value=\"squares\">بخش ۱۰۰ مربع</option>\n                </select>\n              </div>\n              <div class=\"col-md-2 text-md-end small text-secondary\" id=\"adBannersFilterCount\">\n                در حال بارگذاری...\n              </div>\n            </div>\n\n            <div id=\"adBannerAlertBox\" class=\"alert d-none py-2 px-3 small mb-3\"></div>\n\n            <div class=\"table-responsive\">\n              <table class=\"table table-dark table-hover table-striped rounded align-middle\">\n                <thead>\n                  <tr class=\"text-secondary small\">\n                    <th style=\"width: 95px;\">ترتیب</th>\n                    <th style=\"width: 130px;\">تصویر بنر</th>\n                    <th>نام داخلی و لینک مقصد</th>\n                    <th>وضعیت</th>\n                    <th>بازه زمانی نمایش</th>\n                    <th>آمار نمایش / کلیک</th>\n                    <th style=\"width: 190px;\">عملیات</th>\n                  </tr>\n                </thead>\n                <tbody id=\"adBannersTbody\">\n                  <tr><td colspan=\"7\" class=\"text-center py-4 text-secondary\">در حال بارگذاری بنرهای تبلیغاتی...</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n        </section>\n\n      </main>\n    </div>\n  </div>\n\n  <!-- ============================================================== -->\n  <!-- MODALS (Support Conversation, Announcement, Start Competition, Archive) -->\n  <!-- ============================================================== -->\n\n  <!-- Modal: Support Ticket Conversation & Reply -->\n  <div class=\"modal fade modal-dark\" id=\"ticketConversationModal\" tabindex=\"-1\" aria-labelledby=\"ticketConvModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <div class=\"d-flex align-items-center gap-2\">\n            <i class=\"bi bi-chat-left-text-fill text-info fs-5\"></i>\n            <div>\n              <h5 class=\"modal-title text-white fw-bold\" id=\"ticketConvTitle\">گفت‌وگوی تیکت</h5>\n              <div class=\"small text-secondary\">\n                کد پیگیری: <span id=\"ticketConvCode\" class=\"text-warning fw-bold\">-</span> |\n                کاربر: <span id=\"ticketConvUser\" class=\"text-white\">-</span> (<span id=\"ticketConvPhone\" class=\"text-info\">-</span>)\n              </div>\n            </div>\n          </div>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <div class=\"modal-body p-3\">\n          <div class=\"d-flex justify-content-between align-items-center flex-wrap gap-2 p-2 rounded mb-3\" style=\"background: #0B192C; border: 1px solid var(--border-color);\">\n            <div>\n              <span class=\"badge bg-secondary me-1\" id=\"ticketConvCategory\">-</span>\n              <span class=\"badge bg-primary\" id=\"ticketConvStatusBadge\">-</span>\n              <span class=\"text-secondary small ms-2\">ثبت: <span id=\"ticketConvCreated\">-</span></span>\n            </div>\n            <div class=\"d-flex align-items-center gap-2\">\n              <label class=\"text-secondary small\">تغییر وضعیت:</label>\n              <select id=\"ticketConvStatusSelect\" class=\"form-select form-select-sm form-select-dark\" style=\"width: auto;\" onchange=\"updateTicketStatusFromSelect()\">\n                <option value=\"NEW\">جدید</option>\n                <option value=\"IN_PROGRESS\">در حال بررسی</option>\n                <option value=\"ANSWERED\">پاسخ داده شد</option>\n                <option value=\"CLOSED\">بسته شد</option>\n              </select>\n            </div>\n          </div>\n\n          <div id=\"ticketMessagesContainer\" class=\"p-3 rounded mb-3\" style=\"max-height: 380px; overflow-y: auto; background-color: #0B192C; border: 1px solid var(--border-color); display: flex; flex-direction: column; gap: 12px;\">\n            <div class=\"text-center text-secondary py-3\">در حال بارگذاری پیام‌ها...</div>\n          </div>\n\n          <div id=\"ticketReplyBox\">\n            <label class=\"form-label text-warning small fw-bold\"><i class=\"bi bi-reply-fill\"></i> ارسال پاسخ مدیریت به کاربر:</label>\n            <textarea id=\"adminReplyTextarea\" rows=\"3\" class=\"form-control form-control-dark mb-2\" placeholder=\"متن پاسخ مدیریت را اینجا بنویسید...\"></textarea>\n            <div class=\"d-flex justify-content-between align-items-center\">\n              <div class=\"form-check form-check-inline small\">\n                <input class=\"form-check-input\" type=\"checkbox\" id=\"replySetAnswered\" checked>\n                <label class=\"form-check-label text-secondary\" for=\"replySetAnswered\">تغییر خودکار وضعیت به «پاسخ داده شد»</label>\n              </div>\n              <button type=\"button\" class=\"btn btn-gold btn-sm px-4 fw-bold\" id=\"sendReplyBtn\" onclick=\"sendAdminReply()\">\n                <span id=\"sendReplySpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n                <i class=\"bi bi-send-fill me-1\"></i> ثبت و ارسال پاسخ\n              </button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Create / Edit Home Announcement -->\n  <div class=\"modal fade modal-dark\" id=\"announcementModal\" tabindex=\"-1\" aria-labelledby=\"announcementModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title text-info fw-bold\" id=\"announcementModalLabel\"><i class=\"bi bi-megaphone-fill me-2\"></i> مدیریت پیام و اطلاعیه صفحه اصلی</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <div class=\"modal-body\">\n          <input type=\"hidden\" id=\"editAnnId\" value=\"\">\n\n          <div class=\"row g-3\">\n            <div class=\"col-md-8\">\n              <label class=\"form-label text-secondary small fw-bold\">عنوان پیام:</label>\n              <input type=\"text\" id=\"annTitleInput\" class=\"form-control form-control-dark\" placeholder=\"مثلاً: آغاز مسابقه دوره دوم با جوایز ویژه!\" oninput=\"updateLivePreview()\">\n            </div>\n            <div class=\"col-md-4\">\n              <label class=\"form-label text-secondary small fw-bold\">نوع پیام:</label>\n              <select id=\"annTypeSelect\" class=\"form-select form-select-dark\" onchange=\"updateLivePreview()\">\n                <option value=\"ANNOUNCEMENT\">اطلاعیه عمومی</option>\n                <option value=\"COMPETITION_START\">شروع مسابقه</option>\n                <option value=\"COMPETITION_END\">اعلام زمان پایان</option>\n                <option value=\"WINNERS\">اعلام برندگان</option>\n                <option value=\"CUSTOM\">پیام ویژه</option>\n              </select>\n            </div>\n\n            <div class=\"col-12\">\n              <label class=\"form-label text-secondary small fw-bold\">متن کامل پیام صفحه اصلی:</label>\n              <textarea id=\"annContentInput\" rows=\"3\" class=\"form-control form-control-dark\" placeholder=\"متن توضیحات پیام را اینجا وارد کنید...\" oninput=\"updateLivePreview()\"></textarea>\n            </div>\n\n            <div class=\"col-md-7\">\n              <label class=\"form-label text-secondary small fw-bold\">تاریخ و ساعت پایان مسابقه (اختیاری):</label>\n              <input type=\"datetime-local\" id=\"annEndsAtInput\" class=\"form-control form-control-dark\" onchange=\"updateLivePreview()\">\n            </div>\n            <div class=\"col-md-5 d-flex align-items-end gap-1 flex-wrap\">\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" onclick=\"setQuickEndDate(3)\">+۳ روز</button>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" onclick=\"setQuickEndDate(7)\">+۷ روز</button>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" onclick=\"setQuickEndDate(14)\">+۱۴ روز</button>\n              <button type=\"button\" class=\"btn btn-sm btn-outline-danger\" onclick=\"clearEndDate()\">حذف مهلت</button>\n            </div>\n\n            <div class=\"col-12 mt-2\">\n              <div class=\"form-check form-switch\">\n                <input class=\"form-check-input\" type=\"checkbox\" id=\"annIsActiveSwitch\" checked onchange=\"updateLivePreview()\">\n                <label class=\"form-check-label text-white fw-bold\" for=\"annIsActiveSwitch\">انتشار و نمایش مستقیم در صفحه اصلی کاربران</label>\n              </div>\n            </div>\n\n            <!-- Live Preview in App Simulation -->\n            <div class=\"col-12 mt-3\">\n              <label class=\"form-label text-warning small fw-bold\"><i class=\"bi bi-phone\"></i> پیش‌نمایش زنده در صفحه اصلی اپلیکیشن:</label>\n              <div class=\"card p-3 shadow\" id=\"livePreviewContainer\" style=\"background: linear-gradient(135deg, #0B192C 0%, #1E3E62 100%); border: 1.5px solid #FFB703;\">\n                <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                  <div class=\"d-flex align-items-center gap-2\">\n                    <span id=\"previewBadgeType\" class=\"badge bg-warning text-dark fw-bold\">اطلاعیه</span>\n                    <strong id=\"previewTitle\" class=\"gold-text\">عنوان پیام</strong>\n                  </div>\n                  <span id=\"previewEndDateBadge\" class=\"badge bg-danger d-none\">مهلت</span>\n                </div>\n                <p id=\"previewContent\" class=\"mb-0 text-white small\" style=\"white-space: pre-line;\">متن پیام...</p>\n              </div>\n            </div>\n          </div>\n        </div>\n        <div class=\"modal-footer border-secondary\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n          <button type=\"button\" id=\"saveAnnBtn\" class=\"btn btn-gold px-4\" onclick=\"submitAnnouncementForm()\">\n            <span id=\"saveAnnSpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n            ذخیره و انتشار پیام\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Start New Competition with Integrated Announcement -->\n  <div class=\"modal fade modal-dark\" id=\"startCompModal\" tabindex=\"-1\" aria-labelledby=\"startCompModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text\" id=\"startCompModalLabel\"><i class=\"bi bi-exclamation-triangle-fill text-danger me-2\"></i> شروع مسابقه جدید، آرشیو امتیازها و انتشار پیام آغاز</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <div class=\"modal-body\">\n          <div class=\"alert alert-warning border-0 small mb-3\">\n            <strong>توجه بسیار مهم:</strong> با شروع مسابقه جدید، رتبه و امتیازهای تمام کاربران در مسابقه فعلی به‌صورت <strong>دائمی در جدول آرشیو PostgreSQL</strong> ذخیره می‌شوند و امتیاز کاربران در دوره جدید از <strong>صفر</strong> آغاز می‌گردد.\n            <hr class=\"my-2\">\n            <strong>نکته امنیتی:</strong> حساب‌های کاربری، شماره‌های موبایل و خریدهای پلن عضویت کاربران <strong>حفظ خواهند شد</strong>.\n          </div>\n\n          <div class=\"row g-3\">\n            <div class=\"col-md-6\">\n              <label class=\"form-label text-secondary small fw-bold\">عنوان دوره مسابقه جدید:</label>\n              <input type=\"text\" id=\"newCompTitleInput\" class=\"form-control form-control-dark\" placeholder=\"مثلاً: مسابقه دوره ۳ (جوایز ارزنده)\" oninput=\"updateCompModalPreview()\">\n            </div>\n            <div class=\"col-md-6\">\n              <label class=\"form-label text-secondary small fw-bold\">تاریخ و ساعت پایان مسابقه جدید:</label>\n              <input type=\"datetime-local\" id=\"newCompEndDateInput\" class=\"form-control form-control-dark\" onchange=\"updateCompModalPreview()\">\n            </div>\n\n            <div class=\"col-12\">\n              <label class=\"form-label text-secondary small fw-bold\">پیام آغاز مسابقه برای صفحه اصلی اپلیکیشن:</label>\n              <textarea id=\"newCompAnnContentInput\" rows=\"2\" class=\"form-control form-control-dark\" placeholder=\"متن پیام آغاز مسابقه جدید...\" oninput=\"updateCompModalPreview()\"></textarea>\n            </div>\n\n            <div class=\"col-12\">\n              <label class=\"form-label text-warning small fw-bold\"><i class=\"bi bi-phone\"></i> پیش‌نمایش اطلاعیه شروع دوره در اپلیکیشن:</label>\n              <div class=\"card p-3 shadow\" id=\"newCompPreviewContainer\" style=\"background: linear-gradient(135deg, #0B192C 0%, #1E3E62 100%); border: 1.5px solid #FFB703;\">\n                <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                  <span class=\"badge bg-success text-white fw-bold\">شروع مسابقه</span>\n                  <strong id=\"newCompPreviewTitle\" class=\"gold-text\">شروع مسابقه</strong>\n                </div>\n                <p id=\"newCompPreviewContent\" class=\"mb-0 text-white small\">دوره جدید مسابقه آغاز شد.</p>\n              </div>\n            </div>\n\n            <div class=\"col-12\">\n              <label class=\"form-label text-danger fw-bold\">جهت تایید قطعی، عبارت «شروع مسابقه جدید» را تایپ کنید:</label>\n              <input type=\"text\" id=\"confirmationPhraseInput\" class=\"form-control form-control-dark border-danger\" placeholder=\"شروع مسابقه جدید\" onkeyup=\"checkConfirmationPhrase()\">\n            </div>\n          </div>\n        </div>\n        <div class=\"modal-footer border-secondary\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n          <button type=\"button\" id=\"confirmStartCompBtn\" class=\"btn btn-danger fw-bold px-4\" disabled onclick=\"submitStartNewCompetition()\">\n            <span id=\"startCompSpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n            تایید و شروع مسابقه جدید\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: View Archived Leaderboard -->\n  <div class=\"modal fade modal-dark\" id=\"viewArchiveModal\" tabindex=\"-1\" aria-labelledby=\"viewArchiveModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text\" id=\"viewArchiveModalLabel\"><i class=\"bi bi-award-fill text-warning me-2\"></i> رتبه‌بندی نهایی مسابقه آرشیو شده</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <div class=\"modal-body\">\n          <div class=\"d-flex justify-content-between align-items-center mb-3\">\n            <h6 id=\"archiveModalCompTitle\" class=\"text-white mb-0\">-</h6>\n            <span id=\"archiveModalCompStats\" class=\"badge bg-secondary\">-</span>\n          </div>\n          <div class=\"table-responsive\" style=\"max-height: 400px; overflow-y: auto;\">\n            <table class=\"table table-dark table-hover table-striped rounded align-middle\">\n              <thead>\n                <tr class=\"text-secondary\">\n                  <th>رتبه نهایی</th>\n                  <th>نام و نام خانوادگی</th>\n                  <th>شماره موبایل</th>\n                  <th>امتیاز کسب‌شده</th>\n                </tr>\n              </thead>\n              <tbody id=\"archiveResultsTbody\">\n                <tr><td colspan=\"4\" class=\"text-center py-4 text-secondary\">در حال دریافت نتایج...</td></tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class=\"modal-footer border-secondary\">\n          <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">بستن</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Add/Edit Store Product -->\n  <div class=\"modal fade modal-dark\" id=\"storeProductModal\" tabindex=\"-1\" aria-labelledby=\"storeProductModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text fw-bold\" id=\"storeProductModalLabel\"><i class=\"bi bi-shop me-2\"></i> افزودن / ویرایش بسته فروشگاه</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\n        </div>\n        <div class=\"modal-body\">\n          <form id=\"storeProductForm\" onsubmit=\"saveStoreProduct(event)\">\n            <input type=\"hidden\" id=\"storeProdId\" value=\"\">\n            \n            <div class=\"row g-3\">\n              <div class=\"col-md-8\">\n                <label class=\"form-label text-secondary small fw-bold\">عنوان بسته (ثابت):</label>\n                <input type=\"text\" id=\"storeProdTitle\" class=\"form-control form-control-dark bg-secondary text-white\" readonly>\n                <div class=\"form-text text-warning small\">نام و مشخصات بسته ثابت است و قابل تغییر نیست.</div>\n              </div>\n              <div class=\"col-md-4\">\n                <label class=\"form-label text-secondary small fw-bold\">برچسب اختصاصی (Badge):</label>\n                <input type=\"text\" id=\"storeProdBadge\" class=\"form-control form-control-dark\" placeholder=\"مثلاً: پرطرفدار، ویژه\">\n              </div>\n\n              <div class=\"col-12\">\n                <label class=\"form-label text-secondary small fw-bold\">توضیحات و مزایای بسته:</label>\n                <textarea id=\"storeProdDesc\" rows=\"2\" class=\"form-control form-control-dark\" placeholder=\"توضیحات...\"></textarea>\n              </div>\n\n              <div class=\"col-md-4\">\n                <label class=\"form-label text-secondary small fw-bold\">نوع محصول (ثابت):</label>\n                <input type=\"text\" id=\"storeProdTypeDisplay\" class=\"form-control form-control-dark bg-secondary text-white\" readonly>\n                <input type=\"hidden\" id=\"storeProdType\" value=\"SQUARE_UNLOCK\">\n              </div>\n              <div class=\"col-md-4\">\n                <label class=\"form-label text-secondary small fw-bold\" id=\"storeUnitsLabel\">مقدار / تعداد مربع (ثابت):</label>\n                <input type=\"number\" id=\"storeProdUnits\" class=\"form-control form-control-dark bg-secondary text-white\" readonly>\n              </div>\n              <div class=\"col-md-4\">\n                <label class=\"form-label text-secondary small fw-bold text-warning\">قیمت جدید به تومان (قابل ویرایش):</label>\n                <input type=\"number\" id=\"storeProdPrice\" class=\"form-control form-control-dark border-warning text-warning fw-bold\" min=\"0\" step=\"1000\" placeholder=\"مثلاً: 99000\" required>\n              </div>\n\n              <div class=\"col-md-6\">\n                <label class=\"form-label text-secondary small fw-bold\">شناسه مایکت SKU (ثابت):</label>\n                <input type=\"text\" id=\"storeProdSku\" class=\"form-control form-control-dark font-monospace bg-secondary text-white\" readonly>\n              </div>\n              <div class=\"col-md-6\">\n                <label class=\"form-label text-secondary small fw-bold\">ترتیب نمایش:</label>\n                <input type=\"number\" id=\"storeProdSort\" class=\"form-control form-control-dark\" min=\"1\" value=\"1\">\n              </div>\n\n              <div class=\"col-12 mt-3\">\n                <div class=\"form-check form-switch mb-2\">\n                  <input class=\"form-check-input\" type=\"checkbox\" id=\"storeProdIsActive\" checked>\n                  <label class=\"form-check-label text-white fw-bold\" for=\"storeProdIsActive\">نمایش فعال در فروشگاه اپلیکیشن</label>\n                </div>\n                <div class=\"form-check form-switch\">\n                  <input class=\"form-check-input\" type=\"checkbox\" id=\"storeProdIsReadyInMyket\">\n                  <label class=\"form-check-label text-info fw-bold\" for=\"storeProdIsReadyInMyket\">محصول در کنسول مایکت تایید شده و آماده فروش است</label>\n                </div>\n              </div>\n            </div>\n\n            <div class=\"modal-footer border-secondary mt-4 pb-0 px-0\">\n              <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n              <button type=\"submit\" class=\"btn btn-warning fw-bold\"><i class=\"bi bi-save me-1\"></i> ذخیره تغییرات بسته</button>\n            </div>\n          </form>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Add/Edit Reward -->\n  <div class=\"modal fade modal-dark\" id=\"rewardModal\" tabindex=\"-1\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text\" id=\"rewardModalLabel\"><i class=\"bi bi-gift-fill me-2\"></i> افزودن / ویرایش جایزه</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <form onsubmit=\"saveReward(event)\">\n          <div class=\"modal-body\">\n            <input type=\"hidden\" id=\"rewModalId\" value=\"\">\n            <div class=\"row g-3\">\n              <div class=\"col-md-8\">\n                <label class=\"form-label text-secondary small fw-bold\">عنوان جایزه:</label>\n                <input type=\"text\" id=\"rewModalTitle\" class=\"form-control form-control-dark\" required placeholder=\"مثلاً: کارت شارژ ۱۰ هزار تومانی ایرانسل\">\n              </div>\n              <div class=\"col-md-4\">\n                <label class=\"form-label text-secondary small fw-bold\">دسته‌بندی:</label>\n                <select id=\"rewModalCategory\" class=\"form-select form-select-dark\">\n                  <option value=\"cat_recharge\">کارت شارژ</option>\n                  <option value=\"cat_internet\">بسته‌های اینترنت</option>\n                  <option value=\"cat_cash\">جوایز نقدی و هدیه</option>\n                  <option value=\"cat_digital\">گیفت کارت دیجیتال</option>\n                </select>\n              </div>\n              <div class=\"col-md-6\">\n                <label class=\"form-label text-secondary small fw-bold\">امتیاز موردنیاز برای تحویل:</label>\n                <input type=\"number\" id=\"rewModalCost\" class=\"form-control form-control-dark\" required min=\"0\" placeholder=\"100\">\n              </div>\n              <div class=\"col-md-6\">\n                <label class=\"form-label text-secondary small fw-bold\">موجودی انبار (تعداد موجود):</label>\n                <input type=\"number\" id=\"rewModalStock\" class=\"form-control form-control-dark\" required min=\"0\" placeholder=\"50\">\n              </div>\n              <div class=\"col-12\">\n                <label class=\"form-label text-secondary small fw-bold\">آدرس تصویر (Image URL):</label>\n                <input type=\"url\" id=\"rewModalImageUrl\" class=\"form-control form-control-dark\" placeholder=\"https://images.unsplash.com/...\">\n              </div>\n              <div class=\"col-12\">\n                <label class=\"form-label text-secondary small fw-bold\">توضیحات کامل جایزه:</label>\n                <textarea id=\"rewModalDesc\" rows=\"3\" class=\"form-control form-control-dark\" placeholder=\"نحوه تحویل، شرایط و توضیحات...\"></textarea>\n              </div>\n              <div class=\"col-md-6\">\n                <div class=\"form-check form-switch mt-2\">\n                  <input class=\"form-check-input\" type=\"checkbox\" id=\"rewModalIsFeatured\" checked>\n                  <label class=\"form-check-label text-white fw-bold\" for=\"rewModalIsFeatured\">جایزه ویژه (نمایش در هدر ویترین)</label>\n                </div>\n              </div>\n              <div class=\"col-md-6\">\n                <div class=\"form-check form-switch mt-2\">\n                  <input class=\"form-check-input\" type=\"checkbox\" id=\"rewModalIsActive\" checked>\n                  <label class=\"form-check-label text-white fw-bold\" for=\"rewModalIsActive\">نمایش فعال در اپلیکیشن</label>\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"modal-footer border-secondary\">\n            <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n            <button type=\"submit\" class=\"btn btn-gold fw-bold px-4\">ذخیره جایزه</button>\n          </div>\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Edit Claim Status -->\n  <div class=\"modal fade modal-dark\" id=\"claimModal\" tabindex=\"-1\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text\"><i class=\"bi bi-pencil-square me-2\"></i> تغییر وضعیت درخواست دریافت جایزه</h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <form onsubmit=\"saveClaimStatus(event)\">\n          <div class=\"modal-body\">\n            <input type=\"hidden\" id=\"claimModalId\" value=\"\">\n            <div class=\"mb-3\">\n              <label class=\"form-label text-secondary small fw-bold\">وضعیت جدید درخواست:</label>\n              <select id=\"claimModalStatus\" class=\"form-select form-select-dark\" required>\n                <option value=\"PENDING\">در حال بررسی (PENDING)</option>\n                <option value=\"APPROVED\">تایید شده - در صف ارسال (APPROVED)</option>\n                <option value=\"PROCESSING\">در حال پردازش / سفارش خرید (PROCESSING)</option>\n                <option value=\"SHIPPED\">ارسال شده (SHIPPED)</option>\n                <option value=\"COMPLETED\">تکمیل و تحویل داده شد (COMPLETED)</option>\n                <option value=\"REJECTED\">رد شد (REJECTED)</option>\n              </select>\n            </div>\n            <div class=\"mb-3\">\n              <label class=\"form-label text-secondary small fw-bold\">کد رهگیری پستی / کدرهگیری تراکنش:</label>\n              <input type=\"text\" id=\"claimModalTracking\" class=\"form-control form-control-dark\" placeholder=\"مثلاً: 1234567890123456\">\n            </div>\n            <div class=\"mb-3\">\n              <label class=\"form-label text-secondary small fw-bold\">یادداشت و توضیحات مدیر برای کاربر:</label>\n              <textarea id=\"claimModalNotes\" rows=\"3\" class=\"form-control form-control-dark\" placeholder=\"توضیحات تحویل یا علت عدم تایید...\"></textarea>\n            </div>\n          </div>\n          <div class=\"modal-footer border-secondary\">\n            <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n            <button type=\"submit\" class=\"btn btn-gold fw-bold px-4\">اعمال تغییرات</button>\n          </div>\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Admin Key Authentication Dialog -->\n  <div class=\"modal fade modal-dark\" id=\"adminAuthModal\" tabindex=\"-1\" aria-labelledby=\"adminAuthModalLabel\" aria-hidden=\"true\" data-bs-backdrop=\"static\">\n    <div class=\"modal-dialog modal-dialog-centered\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 2px solid #F59E0B; color: #fff; box-shadow: 0 10px 35px rgba(0,0,0,0.7); border-radius: 12px;\">\n        <div class=\"modal-header border-secondary pb-3\">\n          <h5 class=\"modal-title gold-text fw-bold\" id=\"adminAuthModalLabel\">\n            <i class=\"bi bi-shield-lock-fill text-warning me-2\"></i> ورود به پنل مدیریت\n          </h5>\n          <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <div class=\"modal-body p-4\">\n          <div class=\"text-center mb-4\">\n            <div class=\"display-6 text-warning mb-2\"><i class=\"bi bi-key-fill\"></i></div>\n            <h6 class=\"fw-bold text-white mb-2\">کلید امنیتی مدیریت (ADMIN_KEY)</h6>\n            <p class=\"text-secondary small mb-0\">\n              برای دسترسی به داشبورد، مدیریت کاربران، جوایز و تنظیمات، لطفاً کلید امنیتی مدیریت که در متغیرهای محیطی cPanel تنظیم کرده‌اید را وارد فرمایید:\n            </p>\n          </div>\n          \n          <div id=\"modalAuthAlert\" class=\"alert alert-danger d-none py-2 px-3 small mb-3\"></div>\n\n          <div class=\"mb-3\">\n            <label class=\"form-label text-secondary small fw-bold\">کلید امنیتی ادمین:</label>\n            <div class=\"input-group\">\n              <input type=\"password\" id=\"modalAdminKeyInput\" class=\"form-control form-control-dark\" placeholder=\"کلید امنیتی را وارد کنید...\" style=\"direction: ltr; font-family: monospace;\" autofocus>\n              <button class=\"btn btn-outline-secondary\" type=\"button\" onclick=\"toggleModalKeyVisibility()\" title=\"نمایش / پنهان‌سازی کلید\">\n                <i class=\"bi bi-eye\" id=\"toggleKeyIcon\"></i>\n              </button>\n            </div>\n            <div class=\"form-text text-secondary small mt-1\">\n              این کلید به‌صورت محلی در حافظه مرورگر ذخیره خواهد شد.\n            </div>\n          </div>\n        </div>\n        <div class=\"modal-footer border-secondary justify-content-between pt-3\">\n          <button type=\"button\" class=\"btn btn-outline-secondary btn-sm\" data-bs-dismiss=\"modal\">انصراف</button>\n          <button type=\"button\" id=\"modalSubmitKeyBtn\" class=\"btn btn-gold px-4 fw-bold\" onclick=\"submitModalAdminKey()\">\n            <span id=\"modalAuthSpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n            <i class=\"bi bi-box-arrow-in-right me-1\"></i> ورود و تایید کلید\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Modal: Create / Edit Promotional Ad Banner -->\n  <div class=\"modal fade modal-dark\" id=\"adBannerModal\" tabindex=\"-1\" aria-labelledby=\"adBannerModalLabel\" aria-hidden=\"true\">\n    <div class=\"modal-dialog modal-dialog-centered modal-dialog-scrollable modal-xl\">\n      <div class=\"modal-content\" style=\"background-color: #12253B; border: 1px solid var(--border-color); color: #fff;\">\n        <div class=\"modal-header border-secondary\">\n          <h5 class=\"modal-title gold-text fw-bold\" id=\"adBannerModalLabel\">\n            <i class=\"bi bi-badge-ad-fill text-warning me-2\"></i> ایجاد / ویرایش بنر تبلیغاتی\n          </h5>\n          <button type=\"button\" id=\"adBannerCloseXBtn\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"بستن\"></button>\n        </div>\n        <form id=\"adBannerForm\" onsubmit=\"submitAdBannerForm(event)\">\n          <div class=\"modal-body\">\n            <input type=\"hidden\" id=\"adBannerEditId\" value=\"\">\n            <div id=\"adBannerModalAlert\" class=\"alert alert-danger d-none py-2 px-3 small mb-3\"></div>\n\n            <div class=\"row g-4\">\n              <!-- Form Inputs Column -->\n              <div class=\"col-lg-7\">\n                <div class=\"row g-3\">\n                  <!-- Field 1: Internal Title -->\n                  <div class=\"col-md-8\">\n                    <label class=\"form-label text-secondary small fw-bold\">۱. نام داخلی تبلیغ (فقط برای شناسایی مدیر):</label>\n                    <input type=\"text\" id=\"adBannerTitleInput\" class=\"form-control form-control-dark\" maxlength=\"120\" required placeholder=\"مثلاً: کمپین بهاره دیجی‌کالا ۱۴۰۵\" oninput=\"updateAdBannerPreview()\">\n                  </div>\n\n                  <!-- Field 7: Display Order -->\n                  <div class=\"col-md-4\">\n                    <label class=\"form-label text-secondary small fw-bold\">۷. ترتیب نمایش:</label>\n                    <input type=\"number\" id=\"adBannerOrderInput\" class=\"form-control form-control-dark\" min=\"0\" value=\"1\">\n                  </div>\n\n                  <!-- Field 2: Image Upload -->\n                  <div class=\"col-12\">\n                    <label class=\"form-label text-secondary small fw-bold\">۲. انتخاب و بارگذاری تصویر بنر (JPG، PNG، WebP — حداکثر ۵ مگابایت):</label>\n                    <div class=\"p-3 rounded\" style=\"background-color: #0B192C; border: 1px dashed rgba(255, 183, 3, 0.45);\">\n                      <div class=\"d-flex flex-wrap align-items-center gap-2 mb-2\">\n                        <input type=\"file\" id=\"adBannerImageFileInput\" class=\"form-control form-control-sm form-control-dark\" accept=\"image/jpeg,image/png,image/webp\" onchange=\"handleAdBannerFileSelected(event)\" style=\"max-width: 340px;\">\n                        <span id=\"adBannerUploadStatus\" class=\"small text-secondary\">تصویری انتخاب نشده است</span>\n                      </div>\n                      <input type=\"hidden\" id=\"adBannerImageUrlInput\" value=\"\">\n                      <div class=\"small text-secondary\">\n                        پیشنهاد ابعاد استاندارد: نسبت افقی ۱۶:۹ یا ۲:۱ (مثلاً ۱۲۰۰×۶۰۰ پیکسل) برای نمایش بدون بریدگی در صفحه اصلی.\n                      </div>\n                    </div>\n                  </div>\n\n                  <!-- Field 3: Target URL -->\n                  <div class=\"col-12\">\n                    <label class=\"form-label text-secondary small fw-bold\">۳. آدرس مقصد (URL) با http:// یا https://:</label>\n                    <input type=\"url\" id=\"adBannerTargetUrlInput\" class=\"form-control form-control-dark text-start\" style=\"direction: ltr;\" required placeholder=\"https://example.com/campaign\" oninput=\"updateAdBannerPreview()\">\n                    <div class=\"form-text text-secondary small\">این لینک هنگام لمس بنر باز می‌شود و روی تصویر تبلیغ نمایش داده نخواهد شد.</div>\n                  </div>\n\n                  <!-- Field 4: Display Status -->\n                  <div class=\"col-md-6\">\n                    <label class=\"form-label text-secondary small fw-bold\">۴. وضعیت نمایش:</label>\n                    <select id=\"adBannerStatusSelect\" class=\"form-select form-select-dark\" onchange=\"updateAdBannerPreview()\">\n                      <option value=\"true\">فعال (نمایش در برنامه در بازه معتبر)</option>\n                      <option value=\"false\">غیرفعال (عدم نمایش)</option>\n                    </select>\n                  </div>\n\n                  <!-- Field 8: Link Open Mode -->\n                  <div class=\"col-md-6\">\n                    <label class=\"form-label text-secondary small fw-bold\">۸. نوع باز شدن لینک:</label>\n                    <select id=\"adBannerLinkModeSelect\" class=\"form-select form-select-dark\" onchange=\"updateAdBannerPreview()\">\n                      <option value=\"external\">باز شدن در مرورگر خارجی (پیشنهادی)</option>\n                      <option value=\"internal\">باز شدن در مرورگر داخلی برنامه (WebView امن)</option>\n                    </select>\n                  </div>\n\n                  <!-- Field 5: Start Date -->\n                  <div class=\"col-md-6\">\n                    <label class=\"form-label text-secondary small fw-bold\">۵. تاریخ و ساعت شروع نمایش (اختیاری):</label>\n                    <div class=\"input-group input-group-sm\">\n                      <input type=\"datetime-local\" id=\"adBannerStartAtInput\" class=\"form-control form-control-dark\" onchange=\"updateAdBannerPreview()\">\n                      <button type=\"button\" class=\"btn btn-outline-secondary\" onclick=\"document.getElementById('adBannerStartAtInput').value=''; updateAdBannerPreview();\" title=\"پاک کردن تاریخ شروع\">پاک</button>\n                    </div>\n                  </div>\n\n                  <!-- Field 6: End Date -->\n                  <div class=\"col-md-6\">\n                    <label class=\"form-label text-secondary small fw-bold\">۶. تاریخ و ساعت پایان نمایش (اختیاری):</label>\n                    <div class=\"input-group input-group-sm\">\n                      <input type=\"datetime-local\" id=\"adBannerEndAtInput\" class=\"form-control form-control-dark\" onchange=\"updateAdBannerPreview()\">\n                      <button type=\"button\" class=\"btn btn-outline-secondary\" onclick=\"document.getElementById('adBannerEndAtInput').value=''; updateAdBannerPreview();\" title=\"پاک کردن تاریخ پایان\">پاک</button>\n                    </div>\n                    <div class=\"d-flex gap-1 mt-1 flex-wrap\">\n                      <button type=\"button\" class=\"btn btn-outline-secondary btn-sm py-0 px-2\" style=\"font-size: 11px;\" onclick=\"setAdBannerQuickEndDays(3)\">+۳ روز</button>\n                      <button type=\"button\" class=\"btn btn-outline-secondary btn-sm py-0 px-2\" style=\"font-size: 11px;\" onclick=\"setAdBannerQuickEndDays(7)\">+۷ روز</button>\n                      <button type=\"button\" class=\"btn btn-outline-secondary btn-sm py-0 px-2\" style=\"font-size: 11px;\" onclick=\"setAdBannerQuickEndDays(30)\">+۳۰ روز</button>\n                    </div>\n                  </div>\n\n                  <!-- Field 9: Display Placements -->\n                  <div class=\"col-12\">\n                    <div class=\"p-3 rounded\" style=\"background-color: #0B192C; border: 1px solid rgba(255, 183, 3, 0.35);\">\n                      <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                        <label class=\"form-label text-warning small fw-bold mb-0\">۹. محل‌های نمایش بنر در اپلیکیشن:</label>\n                        <div class=\"form-check form-switch small\">\n                          <input class=\"form-check-input\" type=\"checkbox\" id=\"adBannerSelectAllPlacements\" onchange=\"toggleAllAdBannerPlacements(this)\">\n                          <label class=\"form-check-label text-secondary\" for=\"adBannerSelectAllPlacements\">انتخاب همه بخش‌ها</label>\n                        </div>\n                      </div>\n                      <div class=\"row g-2\">\n                        <div class=\"col-sm-6 col-md-3\">\n                          <div class=\"form-check\">\n                            <input class=\"form-check-input ad-banner-placement-chk\" type=\"checkbox\" value=\"home\" id=\"placementHome\" checked>\n                            <label class=\"form-check-label text-white small\" for=\"placementHome\">صفحه اصلی</label>\n                          </div>\n                        </div>\n                        <div class=\"col-sm-6 col-md-3\">\n                          <div class=\"form-check\">\n                            <input class=\"form-check-input ad-banner-placement-chk\" type=\"checkbox\" value=\"leaderboard\" id=\"placementLeaderboard\">\n                            <label class=\"form-check-label text-white small\" for=\"placementLeaderboard\">جدول رتبه‌بندی</label>\n                          </div>\n                        </div>\n                        <div class=\"col-sm-6 col-md-3\">\n                          <div class=\"form-check\">\n                            <input class=\"form-check-input ad-banner-placement-chk\" type=\"checkbox\" value=\"profile\" id=\"placementProfile\">\n                            <label class=\"form-check-label text-white small\" for=\"placementProfile\">پروفایل کاربر</label>\n                          </div>\n                        </div>\n                        <div class=\"col-sm-6 col-md-3\">\n                          <div class=\"form-check\">\n                            <input class=\"form-check-input ad-banner-placement-chk\" type=\"checkbox\" value=\"squares\" id=\"placementSquares\">\n                            <label class=\"form-check-label text-white small\" for=\"placementSquares\">بخش ۱۰۰ مربع</label>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n\n              <!-- Field 9: Live Preview Column -->\n              <div class=\"col-lg-5\">\n                <div class=\"p-3 rounded h-100 d-flex flex-column justify-content-between\" style=\"background-color: #0B192C; border: 1px solid rgba(255, 183, 3, 0.35);\">\n                  <div>\n                    <label class=\"form-label text-warning small fw-bold mb-2\">\n                      <i class=\"bi bi-phone me-1\"></i> ۹. پیش‌نمایش زنده تصویر بنر و لینک قبل از انتشار:\n                    </label>\n                    <div class=\"small text-secondary mb-2\">نمای واقعی داخل اپلیکیشن (بدون نمایش آدرس لینک روی تصویر):</div>\n\n                    <div id=\"adBannerPreviewCard\" style=\"background: #121212; border: 1px solid rgba(212, 175, 55, 0.38); border-radius: 16px; overflow: hidden; aspect-ratio: 16 / 8; display: flex; align-items: center; justify-content: center; position: relative;\">\n                      <img id=\"adBannerPreviewImg\" src=\"\" alt=\"پیش‌نمایش تبلیغ\" style=\"width: 100%; height: 100%; object-fit: cover; display: none;\">\n                      <div id=\"adBannerPreviewPlaceholder\" class=\"text-center text-secondary p-3\">\n                        <i class=\"bi bi-image fs-1 d-block mb-2 text-warning opacity-50\"></i>\n                        <div class=\"small\">پس از انتخاب تصویر، پیش‌نمایش بنر اینجا نمایش داده می‌شود.</div>\n                      </div>\n                    </div>\n                  </div>\n\n                  <div class=\"mt-3 p-2 rounded\" style=\"background-color: #12253B; border: 1px solid var(--border-color);\">\n                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                      <span class=\"small text-secondary\">وضعیت پیش‌بینی‌شده:</span>\n                      <span id=\"adBannerPreviewStatusBadge\" class=\"badge bg-success\">فعال</span>\n                    </div>\n                    <div class=\"d-flex justify-content-between align-items-center mb-2\">\n                      <span class=\"small text-secondary\">نحوه باز شدن لینک:</span>\n                      <span id=\"adBannerPreviewModeBadge\" class=\"badge bg-info text-dark\">مرورگر خارجی</span>\n                    </div>\n                    <div class=\"small text-secondary mb-1\">بررسی لینک مقصد (فقط در پنل مدیر):</div>\n                    <div class=\"d-flex align-items-center gap-2\">\n                      <code id=\"adBannerPreviewUrlText\" class=\"text-warning small text-truncate flex-grow-1\" style=\"direction: ltr;\">-</code>\n                      <a id=\"adBannerPreviewTestLink\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn btn-sm btn-outline-warning disabled\" style=\"font-size: 11px;\">\n                        <i class=\"bi bi-box-arrow-up-right\"></i> تست لینک\n                      </a>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"modal-footer border-secondary\">\n            <button type=\"button\" id=\"adBannerCancelBtn\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">انصراف</button>\n            <button type=\"submit\" id=\"saveAdBannerBtn\" class=\"btn btn-gold fw-bold px-4\">\n              <span id=\"saveAdBannerSpinner\" class=\"spinner-border spinner-border-sm d-none me-1\" role=\"status\"></span>\n              <i class=\"bi bi-check2-circle me-1\"></i> ذخیره بنر تبلیغاتی\n            </button>\n          </div>\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <!-- Scripts -->\n  <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\"></script>\n  <script>\n    let cachedUsers = [];\n    let filteredUsersList = [];\n    const selectedUserIds = new Set();\n    let usersCurrentPage = 1;\n    let usersPageSize = 25;\n    let cachedAnnouncements = [];\n    let cachedTickets = [];\n    let currentOpenTicket = null;\n    let currentActiveAnn = null;\n    let currentActiveComp = null;\n    let bootstrapStartModal = null;\n    let bootstrapArchiveModal = null;\n    let bootstrapAnnModal = null;\n    let bootstrapTicketModal = null;\n    let bootstrapStoreModal = null;\n    let cachedStoreProducts = [];\n    let cachedStorePurchases = [];\n\n    // Navigation section titles mapping\n    const SECTION_TITLES = {\n      'dashboard': { title: 'داشبورد اصلی', icon: 'bi-speedometer2' },\n      'users': { title: 'مدیریت کاربران', icon: 'bi-people-fill' },\n      'rewards_management': { title: 'جوایز و بنر هدیه', icon: 'bi-gift-fill' },\n      'store': { title: 'فروشگاه و تراکنش‌ها', icon: 'bi-shop' },\n      'support': { title: 'پشتیبانی و تیکت‌ها', icon: 'bi-headset' },\n      'settings': { title: 'تنظیمات پنل', icon: 'bi-gear-fill' },\n      'login_notification': { title: 'مدیریت پیام ورود', icon: 'bi-megaphone-fill' },\n      'ad_banners': { title: 'مدیریت بنرهای تبلیغاتی', icon: 'bi-badge-ad-fill' }\n    };\n\n    function navigateTo(sectionId) {\n      if (!SECTION_TITLES[sectionId]) sectionId = 'dashboard';\n\n      // Update Section Visibility\n      document.querySelectorAll('.admin-section').forEach(sec => sec.classList.remove('active'));\n      const targetSec = document.getElementById(`section-${sectionId}`);\n      if (targetSec) targetSec.classList.add('active');\n\n      // Update Sidebar Links\n      document.querySelectorAll('.sidebar-link').forEach(link => {\n        const linkSec = link.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];\n        if (linkSec === sectionId) {\n          link.classList.add('active');\n        } else {\n          link.classList.remove('active');\n        }\n      });\n\n      // Update Topbar Title\n      const titleInfo = SECTION_TITLES[sectionId];\n      const titleEl = document.getElementById('currentSectionTitle');\n      if (titleEl && titleInfo) {\n        titleEl.innerHTML = `<i class=\"bi ${titleInfo.icon}\"></i> ${titleInfo.title}`;\n      }\n\n      // Update URL Hash\n      if (window.location.hash !== `#${sectionId}`) {\n        window.history.replaceState(null, '', `#${sectionId}`);\n      }\n\n      // Trigger Section Specific Data Loading\n      if (sectionId === 'store') {\n        loadStoreProducts();\n        loadStorePurchases();\n      } else if (sectionId === 'rewards') {\n        loadRewardsData();\n        loadRewardAppearance();\n      } else if (sectionId === 'rewards_appearance') {\n        loadRewardAppearance();\n      } else if (sectionId === 'reward_claims') {\n        loadRewardClaims();\n      } else if (sectionId === 'support') {\n        loadAdminSupportTickets();\n      } else if (sectionId === 'login_notification') {\n        loadLoginNotification();\n      } else if (sectionId === 'ad_banners') {\n        loadAdBanners();\n      }\n\n      // Close mobile sidebar if open\n      closeSidebar();\n\n      // Scroll top\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    }\n\n    function toggleSidebar() {\n      const sidebar = document.getElementById('adminSidebar');\n      const backdrop = document.getElementById('sidebarBackdrop');\n      if (sidebar && backdrop) {\n        sidebar.classList.toggle('show');\n        backdrop.classList.toggle('show');\n      }\n    }\n\n    function closeSidebar() {\n      const sidebar = document.getElementById('adminSidebar');\n      const backdrop = document.getElementById('sidebarBackdrop');\n      if (sidebar && backdrop) {\n        sidebar.classList.remove('show');\n        backdrop.classList.remove('show');\n      }\n    }\n\n    document.addEventListener('DOMContentLoaded', () => {\n      // Modals Initialization (guarded in case CDN scripts are delayed or unavailable)\n      if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {\n        const sModalEl = document.getElementById('startCompModal');\n        if (sModalEl) bootstrapStartModal = new bootstrap.Modal(sModalEl);\n\n        const aModalEl = document.getElementById('viewArchiveModal');\n        if (aModalEl) bootstrapArchiveModal = new bootstrap.Modal(aModalEl);\n\n        const annModalEl = document.getElementById('announcementModal');\n        if (annModalEl) bootstrapAnnModal = new bootstrap.Modal(annModalEl);\n\n        const tModalEl = document.getElementById('ticketConversationModal');\n        if (tModalEl) bootstrapTicketModal = new bootstrap.Modal(tModalEl);\n      }\n\n      // Handle Initial Navigation from Hash\n      const initialHash = window.location.hash.replace('#', '');\n      if (initialHash && SECTION_TITLES[initialHash]) {\n        navigateTo(initialHash);\n      } else {\n        navigateTo('dashboard');\n      }\n\n      // Check OneSignal Status\n      checkOneSignalStatus();\n    });\n\n    function getAdminKey() {\n      return localStorage.getItem('reqabat_admin_key') || \"09876poiuyAA\";\n    }\n\n    function saveAdminKey() {\n      const input = document.getElementById('adminKeyInput').value.trim();\n      if (input) {\n        localStorage.setItem('reqabat_admin_key', input);\n        alert('کلید مدیریت با موفقیت در مرورگر شما ذخیره شد.');\n        loadDashboard();\n      }\n    }\n\n    function logoutAdmin() {\n      if (!confirm('آیا برای خروج امن از پنل اطمینان دارید؟')) return;\n      localStorage.removeItem('reqabat_admin_key');\n      window.location.reload();\n    }\n\n    // Initialize key field\n    const adminKeyField = document.getElementById('adminKeyInput');\n    if (adminKeyField) adminKeyField.value = getAdminKey();\n\n    function openAdminAuthModal() {\n      const modalEl = document.getElementById('adminAuthModal');\n      if (!modalEl) return;\n      const input = document.getElementById('modalAdminKeyInput');\n      if (input) {\n        input.value = getAdminKey();\n      }\n      const alertEl = document.getElementById('modalAuthAlert');\n      if (alertEl) alertEl.classList.add('d-none');\n      \n      if (!window.bootstrapAdminAuthModal) {\n        window.bootstrapAdminAuthModal = new bootstrap.Modal(modalEl);\n      }\n      window.bootstrapAdminAuthModal.show();\n      setTimeout(() => { if (input) input.focus(); }, 400);\n    }\n\n    function toggleModalKeyVisibility() {\n      const input = document.getElementById('modalAdminKeyInput');\n      const icon = document.getElementById('toggleKeyIcon');\n      if (!input || !icon) return;\n      if (input.type === 'password') {\n        input.type = 'text';\n        icon.className = 'bi bi-eye-slash';\n      } else {\n        input.type = 'password';\n        icon.className = 'bi bi-eye';\n      }\n    }\n\n    async function submitModalAdminKey() {\n      const input = document.getElementById('modalAdminKeyInput');\n      const key = (input ? input.value : '').trim();\n      const alertEl = document.getElementById('modalAuthAlert');\n      const spinner = document.getElementById('modalAuthSpinner');\n      const submitBtn = document.getElementById('modalSubmitKeyBtn');\n\n      if (!key) {\n        if (alertEl) {\n          alertEl.innerText = 'لطفاً کلید امنیتی مدیریت را وارد کنید.';\n          alertEl.className = 'alert alert-warning py-2 px-3 small mb-3';\n          alertEl.classList.remove('d-none');\n        }\n        return;\n      }\n\n      if (spinner) spinner.classList.remove('d-none');\n      if (submitBtn) submitBtn.setAttribute('disabled', 'true');\n      if (alertEl) alertEl.classList.add('d-none');\n\n      try {\n        const res = await fetch('/api/admin/auth/verify', {\n          headers: { 'x-admin-key': key }\n        });\n\n        if (res.status === 401) {\n          if (alertEl) {\n            alertEl.innerText = '❌ کلید وارد شده نامعتبر است. لطفاً مقدار ADMIN_KEY در متغیرهای محیطی cPanel هاست را بررسی نمایید.';\n            alertEl.className = 'alert alert-danger py-2 px-3 small mb-3';\n            alertEl.classList.remove('d-none');\n          }\n          return;\n        }\n\n        if (!res.ok) {\n          const data = await res.json().catch(() => ({}));\n          throw new Error(data.error || 'خطا در اعتبارسنجی کلید (کد ' + res.status + ')');\n        }\n\n        // Key verified! Save key to localStorage\n        localStorage.setItem('reqabat_admin_key', key);\n        const kField = document.getElementById('adminKeyInput');\n        if (kField) kField.value = key;\n\n        if (alertEl) {\n          alertEl.innerText = '✓ کلید با موفقیت تایید شد. در حال بارگذاری اطلاعات پنل...';\n          alertEl.className = 'alert alert-success py-2 px-3 small mb-3';\n          alertEl.classList.remove('d-none');\n        }\n\n        setTimeout(() => {\n          if (window.bootstrapAdminAuthModal) {\n            window.bootstrapAdminAuthModal.hide();\n          }\n          loadDashboard();\n        }, 500);\n\n      } catch (err) {\n        if (alertEl) {\n          alertEl.innerText = 'خطای ارتباط: ' + err.message;\n          alertEl.className = 'alert alert-danger py-2 px-3 small mb-3';\n          alertEl.classList.remove('d-none');\n        }\n      } finally {\n        if (spinner) spinner.classList.add('d-none');\n        if (submitBtn) submitBtn.removeAttribute('disabled');\n      }\n    }\n\n    // Support Enter key in modal key input\n    document.addEventListener('DOMContentLoaded', () => {\n      const modalInput = document.getElementById('modalAdminKeyInput');\n      if (modalInput) {\n        modalInput.addEventListener('keyup', (e) => {\n          if (e.key === 'Enter') submitModalAdminKey();\n        });\n      }\n    });\n\n    function showAlert(msg) {\n      const el = document.getElementById('alertBox');\n      if (el) {\n        el.innerText = msg;\n        el.className = 'alert alert-danger shadow-sm mb-4';\n        el.classList.remove('d-none');\n      }\n    }\n\n    function showAlertHtml(html) {\n      const el = document.getElementById('alertBox');\n      if (el) {\n        el.innerHTML = html;\n        el.className = 'alert alert-danger shadow-sm mb-4';\n        el.classList.remove('d-none');\n      }\n    }\n\n    function hideAlert() {\n      const el = document.getElementById('alertBox');\n      if (el) el.classList.add('d-none');\n    }\n\n    function setElText(id, text) {\n      const el = document.getElementById(id);\n      if (el) el.innerText = text;\n    }\n\n    function setElHtml(id, html) {\n      const el = document.getElementById(id);\n      if (el) el.innerHTML = html;\n    }\n\n    function setElClass(id, className) {\n      const el = document.getElementById(id);\n      if (el) el.className = className;\n    }\n\n    function checkConfirmationPhrase() {\n      const phrase = document.getElementById('confirmationPhraseInput').value.trim();\n      const btn = document.getElementById('confirmStartCompBtn');\n      if (phrase === 'شروع مسابقه جدید') {\n        btn.removeAttribute('disabled');\n      } else {\n        btn.setAttribute('disabled', 'true');\n      }\n    }\n\n    function openStartCompModal() {\n      document.getElementById('confirmationPhraseInput').value = '';\n      document.getElementById('confirmStartCompBtn').setAttribute('disabled', 'true');\n      const nextNum = currentActiveComp ? (currentActiveComp.competitionNumber + 1) : 2;\n      document.getElementById('newCompTitleInput').value = `مسابقه دوره ${nextNum} (جوایز ارزنده)`;\n      \n      const d = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);\n      document.getElementById('newCompEndDateInput').value = d.toISOString().slice(0, 16);\n      document.getElementById('newCompAnnContentInput').value = `دوره ${nextNum} مسابقه «رقابت کن، جایزه ببر» آغاز شد! با مشاهده تبلیغات و تکمیل ۱۰۰ مربع روزانه امتیاز کسب کنید و برنده جوایز ویژه شوید.`;\n      \n      updateCompModalPreview();\n      if (bootstrapStartModal) bootstrapStartModal.show();\n    }\n\n    function updateCompModalPreview() {\n      const title = document.getElementById('newCompTitleInput').value.trim() || 'شروع مسابقه جدید';\n      const content = document.getElementById('newCompAnnContentInput').value.trim() || 'دوره جدید مسابقه آغاز شد.';\n      setElText('newCompPreviewTitle', title);\n      setElText('newCompPreviewContent', content);\n    }\n\n    function setQuickEndDate(days) {\n      const d = new Date(Date.now() + days * 24 * 60 * 60 * 1000);\n      document.getElementById('annEndsAtInput').value = d.toISOString().slice(0, 16);\n      updateLivePreview();\n    }\n\n    function clearEndDate() {\n      document.getElementById('annEndsAtInput').value = '';\n      updateLivePreview();\n    }\n\n    function openAnnouncementModal(annId = null) {\n      document.getElementById('editAnnId').value = '';\n      if (!annId) {\n        document.getElementById('announcementModalLabel').innerHTML = '<i class=\"bi bi-plus-circle-fill text-info me-2\"></i> ایجاد پیام جدید برای صفحه اصلی';\n        document.getElementById('annTitleInput').value = '';\n        document.getElementById('annContentInput').value = '';\n        document.getElementById('annTypeSelect').value = 'ANNOUNCEMENT';\n        document.getElementById('annEndsAtInput').value = '';\n        document.getElementById('annIsActiveSwitch').checked = true;\n      } else {\n        const ann = cachedAnnouncements.find(a => a.id === annId);\n        if (ann) {\n          document.getElementById('announcementModalLabel').innerHTML = '<i class=\"bi bi-pencil-square text-warning me-2\"></i> ویرایش پیام صفحه اصلی';\n          document.getElementById('editAnnId').value = ann.id;\n          document.getElementById('annTitleInput').value = ann.title;\n          document.getElementById('annContentInput').value = ann.content;\n          document.getElementById('annTypeSelect').value = ann.type || 'ANNOUNCEMENT';\n          document.getElementById('annEndsAtInput').value = ann.endsAt ? new Date(ann.endsAt).toISOString().slice(0, 16) : '';\n          document.getElementById('annIsActiveSwitch').checked = ann.isActive;\n        }\n      }\n      updateLivePreview();\n      if (bootstrapAnnModal) bootstrapAnnModal.show();\n    }\n\n    function editCurrentActiveAnn() {\n      if (currentActiveAnn) {\n        openAnnouncementModal(currentActiveAnn.id);\n      } else {\n        openAnnouncementModal();\n      }\n    }\n\n    function updateLivePreview() {\n      const title = document.getElementById('annTitleInput').value.trim() || 'عنوان پیام';\n      const content = document.getElementById('annContentInput').value.trim() || 'متن کامل پیام در این قسمت قرار می‌گیرد...';\n      const type = document.getElementById('annTypeSelect').value;\n      const endsAt = document.getElementById('annEndsAtInput').value;\n      const isActive = document.getElementById('annIsActiveSwitch').checked;\n\n      setElText('previewTitle', title);\n      setElText('previewContent', content);\n\n      const badgeType = document.getElementById('previewBadgeType');\n      const typeLabels = {\n        'ANNOUNCEMENT': { text: 'اطلاعیه', cls: 'bg-primary' },\n        'COMPETITION_START': { text: 'شروع مسابقه', cls: 'bg-success' },\n        'COMPETITION_END': { text: 'پایان مسابقه', cls: 'bg-danger' },\n        'WINNERS': { text: 'اعلام برندگان', cls: 'bg-warning text-dark' },\n        'CUSTOM': { text: 'پیام ویژه', cls: 'bg-info text-dark' }\n      };\n      const info = typeLabels[type] || { text: 'اطلاعیه', cls: 'bg-primary' };\n      if (badgeType) {\n        badgeType.className = `badge ${info.cls} fw-bold`;\n        badgeType.innerText = info.text;\n      }\n\n      const endBadge = document.getElementById('previewEndDateBadge');\n      if (endBadge) {\n        if (endsAt) {\n          const diffMs = new Date(endsAt).getTime() - Date.now();\n          if (diffMs > 0) {\n            const days = Math.floor(diffMs / (24 * 3600 * 1000));\n            const hours = Math.floor((diffMs % (24 * 3600 * 1000)) / (3600 * 1000));\n            endBadge.innerText = days > 0 ? `مهلت: ${days} روز و ${hours} ساعت باقیمانده` : `مهلت: ${hours} ساعت باقیمانده`;\n            endBadge.classList.remove('d-none');\n          } else {\n            endBadge.innerText = 'زمان پایان سپری شده';\n            endBadge.classList.remove('d-none');\n          }\n        } else {\n          endBadge.classList.add('d-none');\n        }\n      }\n\n      const container = document.getElementById('livePreviewContainer');\n      if (container) {\n        if (!isActive) {\n          container.style.opacity = '0.45';\n          container.style.filter = 'grayscale(60%)';\n        } else {\n          container.style.opacity = '1';\n          container.style.filter = 'none';\n        }\n      }\n    }\n\n    async function submitAnnouncementForm() {\n      const title = document.getElementById('annTitleInput').value.trim();\n      const content = document.getElementById('annContentInput').value.trim();\n      if (!title || !content) {\n        alert('لطفاً عنوان و متن پیام را وارد کنید.');\n        return;\n      }\n\n      const id = document.getElementById('editAnnId').value.trim() || undefined;\n      const type = document.getElementById('annTypeSelect').value;\n      const endsAtRaw = document.getElementById('annEndsAtInput').value;\n      const endsAt = endsAtRaw ? new Date(endsAtRaw).getTime() : null;\n      const isActive = document.getElementById('annIsActiveSwitch').checked;\n      const key = getAdminKey();\n\n      const btn = document.getElementById('saveAnnBtn');\n      const spinner = document.getElementById('saveAnnSpinner');\n      btn.setAttribute('disabled', 'true');\n      if (spinner) spinner.classList.remove('d-none');\n\n      try {\n        const res = await fetch('/api/admin/announcements', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ id, title, content, type, isActive, endsAt })\n        });\n\n        const data = await res.json();\n        if (data.success) {\n          if (bootstrapAnnModal) bootstrapAnnModal.hide();\n          loadDashboard();\n        } else {\n          alert('خطا در ذخیره پیام: ' + (data.error || 'عملیات ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط با سرور: ' + err.message);\n      } finally {\n        if (spinner) spinner.classList.add('d-none');\n        btn.removeAttribute('disabled');\n      }\n    }\n\n    async function toggleCurrentActiveAnn() {\n      if (!currentActiveAnn) return;\n      await toggleAnnouncement(currentActiveAnn.id);\n    }\n\n    async function toggleAnnouncement(annId) {\n      const key = getAdminKey();\n      try {\n        const res = await fetch(`/api/admin/announcements/${annId}/toggle`, {\n          method: 'PATCH',\n          headers: { 'x-admin-key': key }\n        });\n        const data = await res.json();\n        if (data.success) {\n          loadDashboard();\n        } else {\n          alert('خطا: ' + (data.error || 'عملیات ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      }\n    }\n\n    async function loadDashboard() {\n      const spinner = document.getElementById('refreshSpinner');\n      const authBadge = document.getElementById('authStatusBadge');\n      if (spinner) spinner.classList.remove('d-none');\n      hideAlert();\n\n      const key = getAdminKey();\n\n      try {\n        const res = await fetch('/api/admin/overview', {\n          headers: { 'x-admin-key': key }\n        });\n\n        if (res.status === 401) {\n          if (authBadge) {\n            authBadge.className = 'badge bg-danger';\n            authBadge.innerText = 'کلید نامعتبر';\n            authBadge.style.cursor = 'pointer';\n            authBadge.onclick = openAdminAuthModal;\n          }\n          showAlertHtml(`\n            <div class=\"d-flex align-items-center justify-content-between flex-wrap gap-3 py-1\">\n              <div class=\"d-flex align-items-center gap-2\">\n                <i class=\"bi bi-shield-lock-fill fs-5 text-warning\"></i>\n                <span><strong>خطای دسترسی مدیریت:</strong> کلید امنیتی (ADMIN_KEY) وارد نشده یا نامعتبر است.</span>\n              </div>\n              <button class=\"btn btn-warning btn-sm fw-bold px-3 py-1 shadow-sm\" onclick=\"openAdminAuthModal()\">\n                <i class=\"bi bi-key-fill me-1\"></i> ورود / وارد کردن کلید مدیریت\n              </button>\n            </div>\n          `);\n          setElHtml('usersTbody', '<tr><td colspan=\"7\" class=\"text-center text-danger py-4\">دسترسی نیازمند کلید معتبر مدیریت است.<br><button class=\"btn btn-outline-warning btn-sm mt-2\" onclick=\"openAdminAuthModal()\"><i class=\"bi bi-key me-1\"></i> وارد کردن کلید مدیریت</button></td></tr>');\n          setElHtml('sessionsTbody', '<tr><td colspan=\"6\" class=\"text-center text-danger py-4\">دسترسی مسدود است.</td></tr>');\n          \n          if (!key && !window.adminAuthModalOpenedOnce) {\n            window.adminAuthModalOpenedOnce = true;\n            openAdminAuthModal();\n          }\n          return;\n        }\n\n        if (!res.ok) {\n          throw new Error('خطا در ارتباط با سرور (کد ' + res.status + ')');\n        }\n\n        const data = await res.json();\n        if (authBadge) {\n          authBadge.className = 'badge bg-success';\n          authBadge.innerText = 'متصل و معتبر';\n        }\n\n        // Stats\n        setElText('totalUsers', (data.totalUsers || 0) + ' نفر');\n        setElText('totalScores', (data.totalScoresSum || 0) + ' امتیاز');\n\n        // Fetch additional stats in background\n        await Promise.allSettled([loadStorePurchases(), loadRewardClaims()]);\n        \n        const successCount = cachedStorePurchases.filter(p => p.status === 'SUCCESS').length;\n        setElText('totalTransactions', successCount + ' موفق');\n        \n        const pendingCount = cachedClaims.filter(c => c.status === 'PENDING').length;\n        setElText('totalClaims', pendingCount + ' جدید');\n\n        // Active Competition\n        if (data.activeCompetition) {\n          currentActiveComp = data.activeCompetition;\n          const compNumText = 'دوره ' + data.activeCompetition.competitionNumber;\n          setElText('activeCompNumber', compNumText);\n          setElText('activeCompTitle', data.activeCompetition.title);\n          setElText('dashCompNumber', compNumText);\n          setElText('dashCompTitle', data.activeCompetition.title);\n\n          const startDate = new Date(data.activeCompetition.startedAt);\n          setElText('activeCompStartedAt', startDate.toLocaleDateString('fa-IR', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }));\n          \n          if (data.activeCompetition.endedAt) {\n            const endDate = new Date(data.activeCompetition.endedAt);\n            const endText = endDate.toLocaleDateString('fa-IR', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' });\n            setElText('activeCompEndedAt', endText);\n            setElText('dashCompEndedAt', endText);\n          } else {\n            setElText('activeCompEndedAt', 'نامحدود / تعیین نشده');\n            setElText('dashCompEndedAt', 'نامحدود');\n          }\n        }\n\n        // Active Announcement\n        currentActiveAnn = data.activeAnnouncement;\n        renderActiveAnnouncement(currentActiveAnn);\n\n        // All Announcements\n        cachedAnnouncements = data.announcements || [];\n        renderAnnouncements(cachedAnnouncements);\n\n        // Past Competitions\n        const pastComps = data.pastCompetitions || [];\n        setElText('archivedCompsCount', pastComps.length + ' دوره');\n        renderArchivedCompetitions(pastComps);\n\n        // Logs\n        renderLogs(data.competitionLogs || []);\n\n        // Users & Sessions\n        const serverNow = Number(data.serverNow) || Date.now();\n        const NEW_USER_WINDOW_MS = 24 * 60 * 60 * 1000;\n        cachedUsers = (data.users || []).map((u, idx) => {\n          const regMs = u.registeredAt != null\n            ? Number(u.registeredAt)\n            : (u.registeredAtIso ? new Date(u.registeredAtIso).getTime() : NaN);\n          const validRegMs = Number.isFinite(regMs) ? regMs : null;\n          const isNew = typeof u.isNew === 'boolean'\n            ? u.isNew\n            : (validRegMs !== null && (serverNow - validRegMs) >= 0 && (serverNow - validRegMs) <= NEW_USER_WINDOW_MS);\n          return {\n            ...u,\n            registeredAt: validRegMs,\n            isNew,\n            _rank: idx + 1\n          };\n        });\n        updateNewUsersSummary(cachedUsers);\n        pruneSelectedUsers(cachedUsers);\n        filterUsers(false);\n        renderSessions(data.recentSessions || []);\n\n        // Load Support Tickets\n        loadAdminSupportTickets();\n\n      } catch (err) {\n        if (authBadge) {\n          authBadge.className = 'badge bg-warning text-dark';\n          authBadge.innerText = 'خطای ارتباط';\n        }\n        showAlert(err.message || 'خطا در برقراری ارتباط با سرور');\n      } finally {\n        if (spinner) spinner.classList.add('d-none');\n      }\n    }\n\n    function renderActiveAnnouncement(ann) {\n      const toggleBtn = document.getElementById('toggleActiveAnnBtn');\n      const typeBadge = document.getElementById('activeAnnTypeBadge');\n\n      if (!ann) {\n        setElClass('activeAnnStatusBadge', 'badge bg-secondary');\n        setElHtml('activeAnnStatusBadge', '<i class=\"bi bi-dash-circle\"></i> بدون پیام فعال');\n        if (typeBadge) typeBadge.className = 'badge bg-dark d-none';\n        setElText('activeAnnTitle', 'در حال حاضر هیچ پیامی در بالای صفحه اصلی فعال نیست.');\n        setElText('activeAnnContent', 'برای نمایش اطلاعیه یا پیام جدید به کاربران اپلیکیشن، روی دکمه «ایجاد پیام جدید» کلیک کنید.');\n        setElText('activeAnnStartsAt', '-');\n        setElText('activeAnnEndsAt', '-');\n\n        // Dashboard Summary Card\n        setElText('dashAnnType', 'غیرفعال');\n        setElText('dashAnnStatus', 'بدون پیام');\n        setElText('dashAnnTitle', 'پیام فعالی وجود ندارد');\n        setElText('dashAnnContent', 'برای ایجاد اطلاعیه جدید به بخش اعلان‌ها بروید.');\n\n        if (toggleBtn) toggleBtn.classList.add('d-none');\n        return;\n      }\n\n      if (toggleBtn) toggleBtn.classList.remove('d-none');\n      setElClass('activeAnnStatusBadge', ann.isActive ? 'badge bg-success' : 'badge bg-danger');\n      setElHtml('activeAnnStatusBadge', ann.isActive ? '<i class=\"bi bi-check-circle-fill\"></i> در حال نمایش در صفحه اصلی' : '<i class=\"bi bi-eye-slash-fill\"></i> غیرفعال شده');\n\n      const typeLabels = {\n        'ANNOUNCEMENT': 'اطلاعیه',\n        'COMPETITION_START': 'شروع مسابقه',\n        'COMPETITION_END': 'پایان مسابقه',\n        'WINNERS': 'اعلام برندگان',\n        'CUSTOM': 'پیام ویژه'\n      };\n      const labelText = typeLabels[ann.type] || 'اطلاعیه';\n      if (typeBadge) {\n        typeBadge.classList.remove('d-none');\n        typeBadge.innerText = labelText;\n      }\n\n      setElText('activeAnnTitle', ann.title);\n      setElText('activeAnnContent', ann.content);\n      setElText('activeAnnStartsAt', new Date(ann.updatedAt || ann.startsAt).toLocaleDateString('fa-IR', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }));\n      \n      if (ann.endsAt) {\n        const endDate = new Date(ann.endsAt);\n        setElText('activeAnnEndsAt', endDate.toLocaleDateString('fa-IR', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' }));\n      } else {\n        setElText('activeAnnEndsAt', 'تعیین نشده');\n      }\n\n      // Dashboard Summary\n      setElText('dashAnnType', labelText);\n      setElText('dashAnnStatus', ann.isActive ? 'در حال نمایش' : 'غیرفعال');\n      setElClass('dashAnnStatus', ann.isActive ? 'badge bg-success' : 'badge bg-secondary');\n      setElText('dashAnnTitle', ann.title);\n      setElText('dashAnnContent', ann.content);\n\n      if (toggleBtn) {\n        toggleBtn.innerHTML = ann.isActive ? '<i class=\"bi bi-eye-slash\"></i> غیرفعال‌سازی' : '<i class=\"bi bi-eye\"></i> فعال‌سازی';\n        toggleBtn.className = ann.isActive ? 'btn btn-sm btn-outline-danger' : 'btn btn-sm btn-outline-success';\n      }\n    }\n\n    function renderAnnouncements(list) {\n      const tbody = document.getElementById('announcementsTbody');\n      if (!tbody) return;\n\n      if (!list || list.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-3 text-secondary\"><i class=\"bi bi-info-circle\"></i> هیچ پیامی ثبت نشده است.</td></tr>';\n        return;\n      }\n\n      const typeLabels = {\n        'ANNOUNCEMENT': 'اطلاعیه',\n        'COMPETITION_START': 'شروع مسابقه',\n        'COMPETITION_END': 'پایان مسابقه',\n        'WINNERS': 'اعلام برندگان',\n        'CUSTOM': 'پیام ویژه'\n      };\n\n      tbody.innerHTML = list.map(a => {\n        const endDateStr = a.endsAt ? new Date(a.endsAt).toLocaleDateString('fa-IR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '-';\n        const updatedStr = new Date(a.updatedAt).toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });\n        const statusBadge = a.isActive ? '<span class=\"badge bg-success\">فعال</span>' : '<span class=\"badge bg-secondary\">غیرفعال</span>';\n        const toggleBtnText = a.isActive ? '<i class=\"bi bi-pause-fill\"></i>' : '<i class=\"bi bi-play-fill\"></i>';\n\n        return `\n          <tr>\n            <td class=\"fw-bold\">${a.title}</td>\n            <td><small class=\"badge bg-dark border border-secondary\">${typeLabels[a.type] || a.type}</small></td>\n            <td>${statusBadge}</td>\n            <td><small class=\"text-warning\">${endDateStr}</small></td>\n            <td><small class=\"text-secondary\">${updatedStr}</small></td>\n            <td>\n              <div class=\"d-flex gap-1\">\n                <button class=\"btn btn-sm btn-outline-warning\" title=\"ویرایش پیام\" onclick=\"openAnnouncementModal('${a.id}')\">\n                  <i class=\"bi bi-pencil\"></i>\n                </button>\n                <button class=\"btn btn-sm btn-outline-info\" title=\"تغییر وضعیت فعال/غیرفعال\" onclick=\"toggleAnnouncement('${a.id}')\">\n                  ${toggleBtnText}\n                </button>\n              </div>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function renderArchivedCompetitions(comps) {\n      const tbody = document.getElementById('archivedCompsTbody');\n      if (!tbody) return;\n\n      if (!comps || comps.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-4 text-secondary\"><i class=\"bi bi-info-circle\"></i> هنوز هیچ مسابقه‌ای به پایان نرسیده و آرشیو نشده است.</td></tr>';\n        return;\n      }\n\n      tbody.innerHTML = comps.map(c => {\n        const endDate = c.endedAt ? new Date(c.endedAt).toLocaleDateString('fa-IR', { year: 'numeric', month: 'short', day: 'numeric' }) : '-';\n        return `\n          <tr>\n            <td><span class=\"badge bg-secondary\">دوره ${c.competitionNumber}</span></td>\n            <td class=\"fw-bold\">${c.title}</td>\n            <td>${c.totalParticipants} نفر</td>\n            <td><span class=\"badge badge-gold\">${c.totalScore} امتیاز</span></td>\n            <td><small class=\"text-secondary\">${endDate}</small></td>\n            <td>\n              <button class=\"btn btn-sm btn-outline-warning\" onclick=\"viewArchivedLeaderboard('${c.id}')\">\n                <i class=\"bi bi-eye-fill me-1\"></i> کارنامه نهایی\n              </button>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function renderLogs(logs) {\n      const tbody = document.getElementById('logsTbody');\n      if (!tbody) return;\n\n      if (!logs || logs.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"3\" class=\"text-center py-4 text-secondary\"><i class=\"bi bi-info-circle\"></i> لاگی ثبت نشده است.</td></tr>';\n        return;\n      }\n\n      tbody.innerHTML = logs.map(l => {\n        const dt = new Date(l.createdAt).toLocaleDateString('fa-IR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });\n        return `\n          <tr>\n            <td><small class=\"text-secondary\">${dt}</small></td>\n            <td><span class=\"badge bg-info text-dark\">${l.action}</span></td>\n            <td><small>${l.details || (l.prevTitle + ' -> ' + l.newTitle)}</small></td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    async function viewArchivedLeaderboard(compId) {\n      const resultsTbody = document.getElementById('archiveResultsTbody');\n      if (resultsTbody) resultsTbody.innerHTML = '<tr><td colspan=\"4\" class=\"text-center py-4 text-secondary\">در حال دریافت کارنامه نهایی از دیتابیس...</td></tr>';\n      if (bootstrapArchiveModal) bootstrapArchiveModal.show();\n\n      try {\n        const res = await fetch(`/api/competitions/${compId}/results`);\n        const data = await res.json();\n        if (data.success) {\n          setElText('archiveModalCompTitle', data.competition.title);\n          setElText('archiveModalCompStats', `شرکت‌کنندگان: ${data.competition.totalParticipants} نفر | مجموع امتیاز: ${data.competition.totalScore}`);\n          \n          if (!data.results || data.results.length === 0) {\n            if (resultsTbody) resultsTbody.innerHTML = '<tr><td colspan=\"4\" class=\"text-center py-4 text-secondary\">هیچ رتبه‌ای برای این مسابقه ذخیره نشده است.</td></tr>';\n          } else {\n            if (resultsTbody) {\n              resultsTbody.innerHTML = data.results.map(r => `\n                <tr>\n                  <td><span class=\"badge ${r.rank <= 3 ? 'bg-warning text-dark fw-bold' : 'bg-secondary'}\">#${r.rank}</span></td>\n                  <td class=\"fw-bold\">${r.displayName}</td>\n                  <td dir=\"ltr\" class=\"text-secondary\">${r.phoneNumber}</td>\n                  <td><span class=\"badge badge-gold\">${r.finalScore} امتیاز</span></td>\n                </tr>\n              `).join('');\n            }\n          }\n        } else {\n          if (resultsTbody) resultsTbody.innerHTML = `<tr><td colspan=\"4\" class=\"text-center text-danger py-4\">${data.error || 'خطا در دریافت'}</td></tr>`;\n        }\n      } catch (err) {\n        if (resultsTbody) resultsTbody.innerHTML = `<tr><td colspan=\"4\" class=\"text-center text-danger py-4\">خطای ارتباط: ${err.message}</td></tr>`;\n      }\n    }\n\n    async function submitStartNewCompetition() {\n      const phrase = document.getElementById('confirmationPhraseInput').value.trim();\n      if (phrase !== 'شروع مسابقه جدید') {\n        alert('لطفاً عبارت «شروع مسابقه جدید» را دقیقاً وارد کنید.');\n        return;\n      }\n\n      const newTitle = document.getElementById('newCompTitleInput').value.trim();\n      const endDateRaw = document.getElementById('newCompEndDateInput').value;\n      const endDate = endDateRaw ? new Date(endDateRaw).toISOString() : null;\n      const annContent = document.getElementById('newCompAnnContentInput').value.trim();\n\n      const key = getAdminKey();\n      const btn = document.getElementById('confirmStartCompBtn');\n      const spinner = document.getElementById('startCompSpinner');\n\n      btn.setAttribute('disabled', 'true');\n      if (spinner) spinner.classList.remove('d-none');\n\n      try {\n        const res = await fetch('/api/admin/competition/start-new', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({\n            confirmationPhrase: phrase,\n            newTitle,\n            endDate,\n            announcementTitle: newTitle ? `آغاز ${newTitle}` : undefined,\n            announcementContent: annContent || undefined\n          })\n        });\n\n        const data = await res.json();\n        if (data.success) {\n          alert('عملیات با موفقیت انجام شد!\\n' + data.message);\n          if (bootstrapStartModal) bootstrapStartModal.hide();\n          loadDashboard();\n        } else {\n          alert('خطا در شروع مسابقه جدید: ' + (data.error || 'عملیات ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط با سرور: ' + err.message);\n      } finally {\n        if (spinner) spinner.classList.add('d-none');\n        btn.removeAttribute('disabled');\n      }\n    }\n\n    function toPersianDigits(val) {\n      const map = ['۰', '۱', '۲', '۳', '۴', '۵', '۶', '۷', '۸', '۹'];\n      return String(val == null ? '' : val).replace(/\\d/g, d => map[Number(d)]);\n    }\n\n    function gregorianToJalaliParts(gy, gm, gd) {\n      const gdm = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];\n      const gy2 = gm > 2 ? gy + 1 : gy;\n      let days =\n        355666 +\n        365 * gy +\n        Math.floor((gy2 + 3) / 4) -\n        Math.floor((gy2 + 99) / 100) +\n        Math.floor((gy2 + 399) / 400) +\n        gd +\n        gdm[gm - 1];\n\n      let jy = -1595 + 33 * Math.floor(days / 12053);\n      days %= 12053;\n      jy += 4 * Math.floor(days / 1461);\n      days %= 1461;\n      if (days > 365) {\n        jy += Math.floor((days - 1) / 365);\n        days = (days - 1) % 365;\n      }\n\n      let jm;\n      let jd;\n      if (days < 186) {\n        jm = 1 + Math.floor(days / 31);\n        jd = 1 + (days % 31);\n      } else {\n        jm = 7 + Math.floor((days - 186) / 30);\n        jd = 1 + ((days - 186) % 30);\n      }\n\n      return {\n        year: String(jy),\n        month: String(jm).padStart(2, '0'),\n        day: String(jd).padStart(2, '0')\n      };\n    }\n\n    function formatIranJalaliDateTime(timestamp) {\n      if (timestamp === null || timestamp === undefined || timestamp === '') return null;\n      const date = new Date(typeof timestamp === 'number' ? timestamp : String(timestamp));\n      if (Number.isNaN(date.getTime())) return null;\n\n      const parts = new Intl.DateTimeFormat('en-US', {\n        timeZone: 'Asia/Tehran',\n        year: 'numeric',\n        month: '2-digit',\n        day: '2-digit',\n        hour: '2-digit',\n        minute: '2-digit',\n        second: '2-digit',\n        hourCycle: 'h23'\n      }).formatToParts(date);\n\n      const map = {};\n      for (const p of parts) {\n        if (p.type !== 'literal') map[p.type] = p.value;\n      }\n\n      const jalali = gregorianToJalaliParts(\n        Number(map.year),\n        Number(map.month),\n        Number(map.day)\n      );\n\n      const dateFa = toPersianDigits(`${jalali.year}/${jalali.month}/${jalali.day}`);\n      const timeFa = toPersianDigits(`${map.hour}:${map.minute}:${map.second}`);\n      return { dateFa, timeFa };\n    }\n\n    function updateNewUsersSummary(users) {\n      const badge = document.getElementById('newUsersCountBadge');\n      if (!badge) return;\n      const newCount = (users || []).filter(u => u && u.isNew).length;\n      badge.innerHTML = `<i class=\"bi bi-person-plus-fill\"></i><span>کاربران جدید (۲۴ ساعت اخیر): ${toPersianDigits(newCount)} نفر</span>`;\n    }\n\n    function isUserSelectable(user) {\n      return Boolean(user && user.id != null && String(user.id).trim() !== '');\n    }\n\n    function getSelectableUsers(list) {\n      return (list || []).filter(isUserSelectable);\n    }\n\n    function pruneSelectedUsers(allUsers) {\n      if (!Array.isArray(allUsers)) return;\n      const validIds = new Set(getSelectableUsers(allUsers).map(u => String(u.id).trim()));\n      for (const id of Array.from(selectedUserIds)) {\n        if (!validIds.has(id)) {\n          selectedUserIds.delete(id);\n        }\n      }\n    }\n\n    function showUsersSelectionNotice(html, variant = 'info') {\n      const notice = document.getElementById('usersSelectionNotice');\n      if (!notice) return;\n      const clsMap = {\n        success: 'alert alert-success py-2 px-3 small mb-3 d-flex flex-wrap align-items-center justify-content-between gap-2',\n        warning: 'alert alert-warning py-2 px-3 small mb-3 d-flex flex-wrap align-items-center justify-content-between gap-2',\n        danger: 'alert alert-danger py-2 px-3 small mb-3 d-flex flex-wrap align-items-center justify-content-between gap-2',\n        info: 'alert alert-info py-2 px-3 small mb-3 d-flex flex-wrap align-items-center justify-content-between gap-2'\n      };\n      notice.className = clsMap[variant] || clsMap.info;\n      notice.innerHTML = html;\n      notice.classList.remove('d-none');\n    }\n\n    function hideUsersSelectionNotice() {\n      const notice = document.getElementById('usersSelectionNotice');\n      if (!notice) return;\n      notice.classList.add('d-none');\n      notice.innerHTML = '';\n    }\n\n    function getUsersTotalPages() {\n      return Math.max(1, Math.ceil((filteredUsersList.length || 0) / Math.max(1, usersPageSize)));\n    }\n\n    function getCurrentUsersPageSlice() {\n      const totalPages = getUsersTotalPages();\n      if (usersCurrentPage > totalPages) usersCurrentPage = totalPages;\n      if (usersCurrentPage < 1) usersCurrentPage = 1;\n      const start = (usersCurrentPage - 1) * usersPageSize;\n      return filteredUsersList.slice(start, start + usersPageSize);\n    }\n\n    function updateSelectionUI() {\n      const count = selectedUserIds.size;\n      const badge = document.getElementById('selectedUsersCountBadge');\n      if (badge) {\n        badge.className = count > 0 ? 'selected-count-badge has-selection' : 'selected-count-badge';\n        badge.innerHTML = `<i class=\"bi bi-check2-square\"></i><span>انتخاب‌شده: ${toPersianDigits(count)} نفر</span>`;\n      }\n\n      const clearBtn = document.getElementById('clearUserSelectionBtn');\n      if (clearBtn) {\n        if (count > 0) {\n          clearBtn.classList.remove('d-none');\n          clearBtn.disabled = false;\n        } else {\n          clearBtn.classList.add('d-none');\n        }\n      }\n\n      const selectableFiltered = getSelectableUsers(filteredUsersList);\n      const selectedFilteredCount = selectableFiltered.filter(u => selectedUserIds.has(String(u.id).trim())).length;\n\n      const scopeHint = document.getElementById('selectAllScopeHint');\n      if (scopeHint) {\n        scopeHint.innerText = `(${toPersianDigits(selectableFiltered.length)} کاربر در فهرست)`;\n      }\n\n      const selectAllCheckbox = document.getElementById('selectAllUsersCheckbox');\n      if (selectAllCheckbox) {\n        if (selectableFiltered.length === 0) {\n          selectAllCheckbox.checked = false;\n          selectAllCheckbox.indeterminate = false;\n          selectAllCheckbox.disabled = true;\n        } else {\n          selectAllCheckbox.disabled = false;\n          selectAllCheckbox.checked = selectedFilteredCount === selectableFiltered.length;\n          selectAllCheckbox.indeterminate = selectedFilteredCount > 0 && selectedFilteredCount < selectableFiltered.length;\n        }\n      }\n\n      const pageSelectable = getSelectableUsers(getCurrentUsersPageSlice());\n      const pageSelectedCount = pageSelectable.filter(u => selectedUserIds.has(String(u.id).trim())).length;\n      const pageCheckbox = document.getElementById('usersPageSelectAll');\n      if (pageCheckbox) {\n        if (pageSelectable.length === 0) {\n          pageCheckbox.checked = false;\n          pageCheckbox.indeterminate = false;\n          pageCheckbox.disabled = true;\n        } else {\n          pageCheckbox.disabled = false;\n          pageCheckbox.checked = pageSelectedCount === pageSelectable.length;\n          pageCheckbox.indeterminate = pageSelectedCount > 0 && pageSelectedCount < pageSelectable.length;\n        }\n      }\n    }\n\n    function toggleUserSelection(checkboxEl) {\n      if (!checkboxEl) return;\n      const userId = String(checkboxEl.getAttribute('data-user-id') || '').trim();\n      if (!userId) return;\n\n      if (checkboxEl.checked) {\n        selectedUserIds.add(userId);\n      } else {\n        selectedUserIds.delete(userId);\n      }\n\n      const row = checkboxEl.closest('tr');\n      if (row) {\n        row.classList.toggle('user-row-selected', checkboxEl.checked);\n      }\n      if (selectedUserIds.size > 0) {\n        hideUsersSelectionNotice();\n      }\n      updateSelectionUI();\n    }\n\n    function toggleSelectAllFilteredUsers(checked) {\n      const selectableFiltered = getSelectableUsers(filteredUsersList);\n      for (const u of selectableFiltered) {\n        const uid = String(u.id).trim();\n        if (checked) {\n          selectedUserIds.add(uid);\n        } else {\n          selectedUserIds.delete(uid);\n        }\n      }\n      if (selectedUserIds.size > 0 || !checked) {\n        hideUsersSelectionNotice();\n      }\n      renderUsersPage();\n    }\n\n    function toggleCurrentPageUsersSelection(checked) {\n      const pageSelectable = getSelectableUsers(getCurrentUsersPageSlice());\n      for (const u of pageSelectable) {\n        const uid = String(u.id).trim();\n        if (checked) {\n          selectedUserIds.add(uid);\n        } else {\n          selectedUserIds.delete(uid);\n        }\n      }\n      if (selectedUserIds.size > 0 || !checked) {\n        hideUsersSelectionNotice();\n      }\n      renderUsersPage();\n    }\n\n    function clearUserSelection() {\n      selectedUserIds.clear();\n      hideUsersSelectionNotice();\n      renderUsersPage();\n    }\n\n    function goToUsersPage(page) {\n      const totalPages = getUsersTotalPages();\n      const target = Math.min(totalPages, Math.max(1, Number(page) || 1));\n      usersCurrentPage = target;\n      renderUsersPage();\n    }\n\n    function changeUsersPageSize(newSize) {\n      const parsed = parseInt(newSize, 10);\n      if (!Number.isFinite(parsed) || parsed < 1) return;\n      usersPageSize = parsed;\n      usersCurrentPage = 1;\n      renderUsersPage();\n    }\n\n    function renderUsersPagination() {\n      const infoEl = document.getElementById('usersPaginationInfo');\n      const btnsEl = document.getElementById('usersPaginationButtons');\n      const totalItems = filteredUsersList.length;\n      const totalPages = getUsersTotalPages();\n\n      if (infoEl) {\n        if (totalItems === 0) {\n          infoEl.innerText = 'نمایش ۰ کاربر';\n        } else {\n          const startIdx = (usersCurrentPage - 1) * usersPageSize + 1;\n          const endIdx = Math.min(totalItems, usersCurrentPage * usersPageSize);\n          infoEl.innerText = `نمایش ${toPersianDigits(startIdx)} تا ${toPersianDigits(endIdx)} از ${toPersianDigits(totalItems)} کاربر (صفحه ${toPersianDigits(usersCurrentPage)} از ${toPersianDigits(totalPages)})`;\n        }\n      }\n\n      if (!btnsEl) return;\n      if (totalItems === 0 || totalPages <= 1) {\n        btnsEl.innerHTML = '';\n        return;\n      }\n\n      const buttons = [];\n      buttons.push(`<button type=\"button\" class=\"users-page-btn\" ${usersCurrentPage <= 1 ? 'disabled' : ''} onclick=\"goToUsersPage(${usersCurrentPage - 1})\">قبلی</button>`);\n\n      const maxVisible = 5;\n      let startPage = Math.max(1, usersCurrentPage - Math.floor(maxVisible / 2));\n      let endPage = Math.min(totalPages, startPage + maxVisible - 1);\n      if (endPage - startPage + 1 < maxVisible) {\n        startPage = Math.max(1, endPage - maxVisible + 1);\n      }\n\n      if (startPage > 1) {\n        buttons.push(`<button type=\"button\" class=\"users-page-btn\" onclick=\"goToUsersPage(1)\">${toPersianDigits(1)}</button>`);\n        if (startPage > 2) buttons.push('<span class=\"text-secondary px-1\">...</span>');\n      }\n\n      for (let p = startPage; p <= endPage; p++) {\n        buttons.push(`<button type=\"button\" class=\"users-page-btn ${p === usersCurrentPage ? 'active' : ''}\" onclick=\"goToUsersPage(${p})\">${toPersianDigits(p)}</button>`);\n      }\n\n      if (endPage < totalPages) {\n        if (endPage < totalPages - 1) buttons.push('<span class=\"text-secondary px-1\">...</span>');\n        buttons.push(`<button type=\"button\" class=\"users-page-btn\" onclick=\"goToUsersPage(${totalPages})\">${toPersianDigits(totalPages)}</button>`);\n      }\n\n      buttons.push(`<button type=\"button\" class=\"users-page-btn\" ${usersCurrentPage >= totalPages ? 'disabled' : ''} onclick=\"goToUsersPage(${usersCurrentPage + 1})\">بعدی</button>`);\n      btnsEl.innerHTML = buttons.join('');\n    }\n\n    function renderUsersPage() {\n      const pageUsers = getCurrentUsersPageSlice();\n      renderUsers(pageUsers);\n      renderUsersPagination();\n      updateSelectionUI();\n    }\n\n    function renderUsers(users) {\n      const tbody = document.getElementById('usersTbody');\n      if (!tbody) return;\n\n      if (!users || users.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"7\" class=\"text-center py-4 text-secondary\"><i class=\"bi bi-info-circle\"></i> هیچ کاربری با شرایط انتخاب‌شده یافت نشد.</td></tr>';\n        return;\n      }\n\n      tbody.innerHTML = users.map((u, index) => {\n        const displayRank = u._rank || (index + 1);\n        const fullName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || 'کاربر بدون نام';\n        const selectable = isUserSelectable(u);\n        const uidStr = selectable ? String(u.id).trim() : '';\n        const isChecked = selectable && selectedUserIds.has(uidStr);\n        const newBadgeHtml = u.isNew\n          ? '<span class=\"badge-new-user ms-2\" title=\"ثبت‌نام‌شده در ۲۴ ساعت اخیر\"><i class=\"bi bi-stars\"></i> جدید</span>'\n          : '';\n        const formattedReg = formatIranJalaliDateTime(u.registeredAt != null ? u.registeredAt : u.registeredAtIso);\n        const regHtml = formattedReg\n          ? `<div class=\"reg-datetime-box\">\n               <span class=\"reg-date-line\"><i class=\"bi bi-calendar3 text-warning\"></i><span dir=\"ltr\">${formattedReg.dateFa}</span></span>\n               <span class=\"reg-time-line\"><i class=\"bi bi-clock\"></i><span dir=\"ltr\">${formattedReg.timeFa}</span></span>\n             </div>`\n          : '<span class=\"text-secondary small\">ثبت‌نام نامشخص</span>';\n\n        const rowClasses = [\n          u.isNew ? 'user-row-new' : '',\n          isChecked ? 'user-row-selected' : ''\n        ].filter(Boolean).join(' ');\n\n        return `\n        <tr class=\"${rowClasses}\">\n          <td class=\"text-center\">\n            <input\n              type=\"checkbox\"\n              class=\"form-check-input user-select-checkbox user-row-checkbox m-0\"\n              data-user-id=\"${escapeHtml(uidStr)}\"\n              ${selectable ? '' : 'disabled'}\n              ${isChecked ? 'checked' : ''}\n              aria-label=\"انتخاب ${escapeHtml(fullName)}\"\n              onchange=\"toggleUserSelection(this)\">\n          </td>\n          <td><span class=\"${displayRank <= 3 ? 'badge bg-warning text-dark fw-bold' : 'text-secondary'}\">${toPersianDigits(displayRank)}</span></td>\n          <td class=\"fw-bold\">\n            <div class=\"d-flex flex-wrap align-items-center gap-1\">\n              <span>${escapeHtml(fullName)}</span>\n              ${newBadgeHtml}\n            </div>\n          </td>\n          <td dir=\"ltr\" class=\"text-end\">${escapeHtml(u.phoneNumber || '-')}</td>\n          <td>${regHtml}</td>\n          <td><span class=\"badge badge-gold\">${toPersianDigits(u.score || 0)} امتیاز</span></td>\n          <td>\n            <button class=\"btn btn-sm btn-outline-info\" title=\"بازنشانی دوره ۲۴ ساعته کاربر\" onclick=\"resetUserCycle('${escapeHtml(u.id)}')\">\n              <i class=\"bi bi-arrow-repeat\"></i> ریست دوره\n            </button>\n          </td>\n        </tr>\n      `;\n      }).join('');\n    }\n\n    function renderSessions(sessions) {\n      const tbody = document.getElementById('sessionsTbody');\n      if (!tbody) return;\n\n      if (!sessions || sessions.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"6\" class=\"text-center py-4 text-secondary\"><i class=\"bi bi-info-circle\"></i> هنوز هیچ تبلیغی در این دوره تکمیل و ثبت نشده است.</td></tr>';\n        return;\n      }\n\n      tbody.innerHTML = sessions.map(s => `\n        <tr>\n          <td><code class=\"text-info\">${s.sessionId}</code></td>\n          <td><span class=\"badge bg-warning text-dark\">مربع ${s.squareNumber}</span></td>\n          <td><small class=\"text-secondary\">${s.userId.substring(0, 8)}...</small></td>\n          <td>${s.adDurationSeconds} ثانیه</td>\n          <td><span class=\"badge bg-success\"><i class=\"bi bi-check-circle\"></i> تایید سرور</span></td>\n          <td><small class=\"text-secondary\" title=\"${s.token || ''}\">${(s.token || '').substring(0, 10)}...</small></td>\n        </tr>\n      `).join('');\n    }\n\n    function filterUsers(resetPage = true) {\n      const q = (document.getElementById('userSearchInput')?.value || '').trim().toLowerCase();\n      const filterMode = document.getElementById('userFilterMode')?.value || 'all';\n      const sortMode = document.getElementById('userSortMode')?.value || 'score';\n\n      let list = [...cachedUsers];\n\n      if (filterMode === 'new') {\n        list = list.filter(u => Boolean(u.isNew));\n      }\n\n      if (q) {\n        list = list.filter(u =>\n          (u.firstName && u.firstName.toLowerCase().includes(q)) ||\n          (u.lastName && u.lastName.toLowerCase().includes(q)) ||\n          (u.phoneNumber && String(u.phoneNumber).toLowerCase().includes(q))\n        );\n      }\n\n      if (sortMode === 'newest') {\n        list.sort((a, b) => (Number(b.registeredAt) || 0) - (Number(a.registeredAt) || 0));\n      } else {\n        list.sort((a, b) => (a._rank || 0) - (b._rank || 0));\n      }\n\n      filteredUsersList = list;\n      if (resetPage) {\n        usersCurrentPage = 1;\n      }\n      renderUsersPage();\n    }\n\n    function triggerBlobDownload(blob, filename) {\n      const objectUrl = URL.createObjectURL(blob);\n      try {\n        const link = document.createElement('a');\n        link.href = objectUrl;\n        link.download = filename;\n        link.style.display = 'none';\n        document.body.appendChild(link);\n        link.click();\n        document.body.removeChild(link);\n      } finally {\n        setTimeout(() => URL.revokeObjectURL(objectUrl), 1500);\n      }\n    }\n\n    function parseFilenameFromDisposition(disposition, fallbackName) {\n      if (!disposition) return fallbackName;\n      const utf8Match = disposition.match(/filename\\*=UTF-8''([^;]+)/i);\n      const asciiMatch = disposition.match(/filename=\"?([^\";]+)\"?/i);\n      if (utf8Match && utf8Match[1]) {\n        return decodeURIComponent(utf8Match[1]);\n      }\n      if (asciiMatch && asciiMatch[1]) {\n        return asciiMatch[1];\n      }\n      return fallbackName;\n    }\n\n    async function exportSelectedUsersExcel() {\n      const ids = Array.from(selectedUserIds);\n      if (ids.length === 0) {\n        const msg = 'هیچ کاربری انتخاب نشده است. لطفاً ابتدا حداقل یک کاربر را انتخاب کنید.';\n        showUsersSelectionNotice(\n          `<span><i class=\"bi bi-exclamation-triangle-fill me-1\"></i> ${msg}</span>`,\n          'warning'\n        );\n        showNotification(msg, 'warning');\n        return;\n      }\n\n      const key = getAdminKey();\n      if (!key) {\n        showAlert('برای دریافت خروجی اکسل، ابتدا کلید امنیتی مدیریت را وارد نمایید.');\n        openAdminAuthModal();\n        return;\n      }\n\n      const btn = document.getElementById('exportSelectedUsersExcelBtn');\n      const spinner = document.getElementById('exportSelectedUsersExcelSpinner');\n      const icon = document.getElementById('exportSelectedUsersExcelIcon');\n      const label = document.getElementById('exportSelectedUsersExcelLabel');\n\n      if (btn) btn.disabled = true;\n      if (spinner) spinner.classList.remove('d-none');\n      if (icon) icon.classList.add('d-none');\n      if (label) label.innerText = 'در حال تولید فایل...';\n\n      try {\n        const res = await fetch('/api/admin/users/export-selected-excel', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ userIds: ids })\n        });\n\n        if (res.status === 401) {\n          let errMsg = 'دسترسی غیرمجاز. کلید امنیتی مدیریت نامعتبر است.';\n          try {\n            const errJson = await res.json();\n            if (errJson && errJson.error) errMsg = errJson.error;\n          } catch (_) {}\n          showAlert(errMsg);\n          openAdminAuthModal();\n          return;\n        }\n\n        if (!res.ok) {\n          let errMsg = 'خطا در دریافت خروجی اکسل انتخاب‌شده‌ها (کد ' + res.status + ')';\n          try {\n            const errJson = await res.json();\n            if (errJson && errJson.error) errMsg = errJson.error;\n          } catch (_) {}\n          throw new Error(errMsg);\n        }\n\n        const blob = await res.blob();\n        if (!blob || blob.size === 0) {\n          throw new Error('فایل اکسل دریافت‌شده خالی است.');\n        }\n\n        const filename = parseFilenameFromDisposition(\n          res.headers.get('Content-Disposition') || '',\n          'selected-users-export.xlsx'\n        );\n        triggerBlobDownload(blob, filename);\n\n        showUsersSelectionNotice(\n          `<span><i class=\"bi bi-check-circle-fill me-1\"></i> فایل اکسل برای <strong>${toPersianDigits(ids.length)} کاربر</strong> با موفقیت دانلود شد.</span>\n           <button type=\"button\" class=\"btn btn-sm btn-outline-light\" onclick=\"clearUserSelection()\">\n             <i class=\"bi bi-x-circle me-1\"></i> پاک‌کردن انتخاب‌ها\n           </button>`,\n          'success'\n        );\n        showNotification(`فایل اکسل ${toPersianDigits(ids.length)} کاربر انتخاب‌شده با موفقیت دانلود شد.`, 'success');\n      } catch (err) {\n        console.error('Selected Excel export error:', err);\n        showUsersSelectionNotice(\n          `<span><i class=\"bi bi-x-octagon-fill me-1\"></i> ${escapeHtml(err.message || 'خطا در دانلود خروجی اکسل.')}</span>`,\n          'danger'\n        );\n        showNotification(err.message || 'خطا در دانلود خروجی اکسل.', 'error');\n      } finally {\n        if (btn) btn.disabled = false;\n        if (spinner) spinner.classList.add('d-none');\n        if (icon) icon.classList.remove('d-none');\n        if (label) label.innerText = 'دانلود اکسل انتخاب‌شده‌ها';\n      }\n    }\n\n    async function exportUsersExcel() {\n      const btn = document.getElementById('exportUsersExcelBtn');\n      const spinner = document.getElementById('exportUsersExcelSpinner');\n      const icon = document.getElementById('exportUsersExcelIcon');\n      const label = document.getElementById('exportUsersExcelLabel');\n      const key = getAdminKey();\n\n      if (!key) {\n        showAlert('برای دریافت خروجی اکسل، ابتدا کلید امنیتی مدیریت را وارد نمایید.');\n        openAdminAuthModal();\n        return;\n      }\n\n      if (btn) btn.disabled = true;\n      if (spinner) spinner.classList.remove('d-none');\n      if (icon) icon.classList.add('d-none');\n      if (label) label.innerText = 'در حال آماده‌سازی...';\n\n      try {\n        const res = await fetch('/api/admin/users/export-excel', {\n          method: 'GET',\n          headers: {\n            'x-admin-key': key\n          }\n        });\n\n        if (res.status === 401) {\n          let errMsg = 'دسترسی غیرمجاز. کلید امنیتی مدیریت نامعتبر است.';\n          try {\n            const errJson = await res.json();\n            if (errJson && errJson.error) errMsg = errJson.error;\n          } catch (_) {}\n          showAlert(errMsg);\n          openAdminAuthModal();\n          return;\n        }\n\n        if (!res.ok) {\n          let errMsg = 'خطا در دریافت فایل خروجی اکسل (کد ' + res.status + ')';\n          try {\n            const errJson = await res.json();\n            if (errJson && errJson.error) errMsg = errJson.error;\n          } catch (_) {}\n          throw new Error(errMsg);\n        }\n\n        const blob = await res.blob();\n        if (!blob || blob.size === 0) {\n          throw new Error('فایل اکسل دریافت‌شده خالی است.');\n        }\n\n        const filename = parseFilenameFromDisposition(\n          res.headers.get('Content-Disposition') || '',\n          'users-export.xlsx'\n        );\n        triggerBlobDownload(blob, filename);\n\n        showNotification('فایل اکسل کاربران با موفقیت دانلود شد.', 'success');\n      } catch (err) {\n        console.error('Excel export error:', err);\n        showNotification(err.message || 'خطا در دانلود خروجی اکسل.', 'error');\n      } finally {\n        if (btn) btn.disabled = false;\n        if (spinner) spinner.classList.add('d-none');\n        if (icon) icon.classList.remove('d-none');\n        if (label) label.innerText = 'دانلود خروجی اکسل';\n      }\n    }\n\n    async function resetUserCycle(userId) {\n      if (!confirm('آیا از بازنشانی چرخه ۲۴ ساعته کاربر ' + userId + ' اطمینان دارید؟')) return;\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/admin/cycle/reset', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ userId })\n        });\n        const data = await res.json();\n        if (data.success) {\n          alert('چرخه ۲۴ ساعته کاربر با موفقیت بازنشانی شد.');\n          loadDashboard();\n        } else {\n          alert('خطا: ' + (data.error || 'عملیات ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      }\n    }\n\n    // ====================================================================\n    // Support Tickets Management\n    // ====================================================================\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#039;');\n    }\n\n    const SUPPORT_CATEGORY_MAP = {\n      'SCORES': { label: 'امتیازها', icon: 'bi-star-fill text-warning' },\n      'ADS': { label: 'تبلیغات', icon: 'bi-play-circle-fill text-info' },\n      'PRIZES': { label: 'جوایز', icon: 'bi-gift-fill text-primary' },\n      'MEMBERSHIP': { label: 'عضویت', icon: 'bi-award-fill text-warning' },\n      'PURCHASE': { label: 'خرید', icon: 'bi-cart-check-fill text-success' },\n      'LOGIN': { label: 'مشکل ورود', icon: 'bi-key-fill text-danger' },\n      'OTHER': { label: 'سایر موارد', icon: 'bi-question-circle text-secondary' }\n    };\n\n    const SUPPORT_STATUS_MAP = {\n      'NEW': { label: 'جدید / بی‌پاسخ', cls: 'badge bg-danger' },\n      'IN_PROGRESS': { label: 'در حال بررسی', cls: 'badge bg-warning text-dark' },\n      'ANSWERED': { label: 'پاسخ داده شد', cls: 'badge bg-success' },\n      'CLOSED': { label: 'بسته شده', cls: 'badge bg-secondary' }\n    };\n\n    async function loadAdminSupportTickets() {\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/admin/support/tickets', {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) return;\n        const data = await res.json();\n        if (data.success) {\n          cachedTickets = data.tickets || [];\n\n          // Update Counters\n          if (data.stats) {\n            setElText('supportCountTotal', data.stats.total || 0);\n            setElText('supportCountNew', data.stats.newCount || 0);\n            setElText('supportCountInProgress', data.stats.inProgressCount || 0);\n            setElText('supportCountAnswered', data.stats.answeredCount || 0);\n\n            // Sidebar notification badge\n            const sideBadge = document.getElementById('sidebarSupportBadge');\n            if (sideBadge) {\n              if (data.stats.newCount > 0) {\n                sideBadge.innerText = data.stats.newCount;\n                sideBadge.style.display = 'inline-block';\n              } else {\n                sideBadge.style.display = 'none';\n              }\n            }\n          }\n\n          filterSupportTickets();\n        }\n      } catch (err) {\n        console.warn('[Support Tickets Fetch Error]', err.message);\n      }\n    }\n\n    function filterSupportTickets() {\n      const search = (document.getElementById('supportSearchInput')?.value || '').trim().toLowerCase();\n      const statusFilter = document.getElementById('supportStatusFilter')?.value || 'ALL';\n      const categoryFilter = document.getElementById('supportCategoryFilter')?.value || 'ALL';\n\n      let filtered = cachedTickets.slice();\n\n      if (statusFilter !== 'ALL') {\n        filtered = filtered.filter(t => t.status === statusFilter);\n      }\n\n      if (categoryFilter !== 'ALL') {\n        filtered = filtered.filter(t => t.category === categoryFilter);\n      }\n\n      if (search) {\n        filtered = filtered.filter(t => \n          (t.trackingCode && t.trackingCode.toLowerCase().includes(search)) ||\n          (t.phoneNumber && t.phoneNumber.includes(search)) ||\n          (t.userName && t.userName.toLowerCase().includes(search)) ||\n          (t.subject && t.subject.toLowerCase().includes(search)) ||\n          (t.lastMessage && t.lastMessage.toLowerCase().includes(search))\n        );\n      }\n\n      setElText('supportFilterSummary', `${filtered.length} تیکت از ${cachedTickets.length}`);\n      renderSupportTickets(filtered);\n    }\n\n    function renderSupportTickets(tickets) {\n      const tbody = document.getElementById('supportTicketsTbody');\n      if (!tbody) return;\n\n      if (!tickets || tickets.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"8\" class=\"text-center py-4 text-secondary\">هیچ تیکت پشتیبانی متناسب با فیلتر یافت نشد.</td></tr>';\n        return;\n      }\n\n      tbody.innerHTML = tickets.map(t => {\n        const cat = SUPPORT_CATEGORY_MAP[t.category] || SUPPORT_CATEGORY_MAP['OTHER'];\n        const stat = SUPPORT_STATUS_MAP[t.status] || SUPPORT_STATUS_MAP['NEW'];\n        const updateDate = new Date(t.updatedAtMs).toLocaleDateString('fa-IR', {\n          month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit'\n        });\n\n        const snippet = t.lastMessage ? (t.lastMessage.length > 40 ? t.lastMessage.substring(0, 40) + '...' : t.lastMessage) : '-';\n        const senderBadge = t.lastSenderType === 'ADMIN' \n          ? '<span class=\"badge bg-info text-dark\" style=\"font-size:0.65rem;\">مدیر</span> ' \n          : '<span class=\"badge bg-secondary\" style=\"font-size:0.65rem;\">کاربر</span> ';\n\n        return `\n          <tr>\n            <td><strong class=\"text-warning\">${escapeHtml(t.trackingCode)}</strong></td>\n            <td>\n              <div class=\"fw-bold text-white\">${escapeHtml(t.userName)}</div>\n              <small class=\"text-secondary\" style=\"direction:ltr; display:inline-block;\">${escapeHtml(t.phoneNumber)}</small>\n            </td>\n            <td>\n              <span class=\"small text-nowrap\"><i class=\"bi ${cat.icon} me-1\"></i> ${cat.label}</span>\n            </td>\n            <td>\n              <div class=\"text-white text-truncate\" style=\"max-width: 180px;\">${escapeHtml(t.subject)}</div>\n            </td>\n            <td><span class=\"${stat.cls}\">${stat.label}</span></td>\n            <td>\n              <small class=\"text-light\" style=\"max-width: 220px; display:inline-block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\">\n                ${senderBadge}${escapeHtml(snippet)}\n              </small>\n            </td>\n            <td><small class=\"text-secondary\">${updateDate}</small></td>\n            <td>\n              <button class=\"btn btn-sm btn-outline-info\" onclick=\"openSupportTicketModal('${t.id}')\">\n                <i class=\"bi bi-chat-dots me-1\"></i> پاسخ\n              </button>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    async function openSupportTicketModal(ticketId) {\n      currentOpenTicket = null;\n      const key = getAdminKey();\n\n      setElText('ticketConvTitle', 'در حال بارگذاری...');\n      setElText('ticketConvCode', '...');\n      setElText('ticketConvUser', '...');\n      setElText('ticketConvPhone', '...');\n      setElHtml('ticketMessagesContainer', '<div class=\"text-center text-secondary py-4\"><span class=\"spinner-border spinner-border-sm me-2\"></span>در حال دریافت پیام‌ها...</div>');\n      \n      const replyArea = document.getElementById('adminReplyTextarea');\n      if (replyArea) replyArea.value = '';\n\n      if (bootstrapTicketModal) bootstrapTicketModal.show();\n\n      try {\n        const res = await fetch(`/api/admin/support/tickets/${ticketId}`, {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) throw new Error('خطا در دریافت تیکت');\n        const data = await res.json();\n        if (data.success && data.ticket) {\n          currentOpenTicket = data.ticket;\n          renderTicketConversation(data.ticket, data.messages || []);\n        }\n      } catch (err) {\n        setElHtml('ticketMessagesContainer', `<div class=\"alert alert-danger mb-0\">${escapeHtml(err.message)}</div>`);\n      }\n    }\n\n    function renderTicketConversation(ticket, messages) {\n      setElText('ticketConvTitle', ticket.subject);\n      setElText('ticketConvCode', ticket.trackingCode);\n      setElText('ticketConvUser', ticket.userName);\n      setElText('ticketConvPhone', ticket.phoneNumber);\n\n      const cat = SUPPORT_CATEGORY_MAP[ticket.category] || SUPPORT_CATEGORY_MAP['OTHER'];\n      const stat = SUPPORT_STATUS_MAP[ticket.status] || SUPPORT_STATUS_MAP['NEW'];\n      setElText('ticketConvCategory', cat.label);\n      setElClass('ticketConvStatusBadge', stat.cls);\n      setElText('ticketConvStatusBadge', stat.label);\n\n      const createdDate = new Date(ticket.createdAtMs).toLocaleDateString('fa-IR', {\n        year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit'\n      });\n      setElText('ticketConvCreated', createdDate);\n\n      const select = document.getElementById('ticketConvStatusSelect');\n      if (select) select.value = ticket.status;\n\n      const container = document.getElementById('ticketMessagesContainer');\n      if (!container) return;\n\n      if (!messages || messages.length === 0) {\n        container.innerHTML = '<div class=\"text-center text-secondary py-3\">هیچ پیامی ثبت نشده است.</div>';\n        return;\n      }\n\n      container.innerHTML = messages.map(m => {\n        const isUser = m.senderType === 'USER';\n        const timeStr = new Date(m.createdAtMs).toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit' });\n        const dateStr = new Date(m.createdAtMs).toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' });\n\n        if (isUser) {\n          return `\n            <div class=\"d-flex flex-column align-items-start\" style=\"max-width: 85%; align-self: flex-start;\">\n              <div class=\"d-flex align-items-center gap-1 mb-1\">\n                <span class=\"badge bg-secondary\" style=\"font-size: 0.7rem;\"><i class=\"bi bi-person-fill\"></i> ${escapeHtml(m.senderName || 'کاربر')}</span>\n                <span class=\"text-secondary small\" style=\"font-size: 0.72rem;\">${dateStr} ${timeStr}</span>\n              </div>\n              <div class=\"p-3 rounded-3 text-white\" style=\"background-color: #1E3E62; border: 1px solid #2E5077; white-space: pre-line; word-break: break-word;\">\n                ${escapeHtml(m.messageText)}\n              </div>\n            </div>\n          `;\n        } else {\n          return `\n            <div class=\"d-flex flex-column align-items-end\" style=\"max-width: 85%; align-self: flex-end;\">\n              <div class=\"d-flex align-items-center gap-1 mb-1\">\n                <span class=\"text-secondary small\" style=\"font-size: 0.72rem;\">${dateStr} ${timeStr}</span>\n                <span class=\"badge bg-warning text-dark fw-bold\" style=\"font-size: 0.7rem;\"><i class=\"bi bi-shield-check\"></i> پاسخ پشتیبانی مدیریت</span>\n              </div>\n              <div class=\"p-3 rounded-3 text-dark fw-medium\" style=\"background-color: #FFB703; border: 1px solid #FB8500; white-space: pre-line; word-break: break-word;\">\n                ${escapeHtml(m.messageText)}\n              </div>\n            </div>\n          `;\n        }\n      }).join('');\n\n      container.scrollTop = container.scrollHeight;\n    }\n\n    async function sendAdminReply() {\n      if (!currentOpenTicket) return;\n      const textarea = document.getElementById('adminReplyTextarea');\n      const text = textarea ? textarea.value.trim() : '';\n      if (!text) {\n        alert('لطفاً متن پاسخ را وارد نمایید.');\n        return;\n      }\n\n      const shouldSetAnswered = document.getElementById('replySetAnswered')?.checked;\n      const newStatus = shouldSetAnswered ? 'ANSWERED' : currentOpenTicket.status;\n\n      const btn = document.getElementById('sendReplyBtn');\n      const spinner = document.getElementById('sendReplySpinner');\n      if (btn) btn.setAttribute('disabled', 'true');\n      if (spinner) spinner.classList.remove('d-none');\n\n      const key = getAdminKey();\n      try {\n        const res = await fetch(`/api/admin/support/tickets/${currentOpenTicket.id}/messages`, {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ message: text, newStatus })\n        });\n\n        const data = await res.json();\n        if (data.success) {\n          if (textarea) textarea.value = '';\n          await openSupportTicketModal(currentOpenTicket.id);\n          loadAdminSupportTickets();\n        } else {\n          alert('خطا: ' + (data.error || 'ارسال پاسخ ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      } finally {\n        if (btn) btn.removeAttribute('disabled');\n        if (spinner) spinner.classList.add('d-none');\n      }\n    }\n\n    async function updateTicketStatusFromSelect() {\n      if (!currentOpenTicket) return;\n      const select = document.getElementById('ticketConvStatusSelect');\n      const status = select ? select.value : null;\n      if (!status) return;\n      const key = getAdminKey();\n\n      try {\n        const res = await fetch(`/api/admin/support/tickets/${currentOpenTicket.id}/status`, {\n          method: 'PATCH',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ status })\n        });\n        const data = await res.json();\n        if (data.success) {\n          currentOpenTicket.status = status;\n          const stat = SUPPORT_STATUS_MAP[status] || SUPPORT_STATUS_MAP['NEW'];\n          setElClass('ticketConvStatusBadge', stat.cls);\n          setElText('ticketConvStatusBadge', stat.label);\n          loadAdminSupportTickets();\n        } else {\n          alert('خطا: ' + (data.error || 'تغییر وضعیت ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      }\n    }\n\n    // ====================================================================\n    // OneSignal & Push Notification\n    // ====================================================================\n    async function checkOneSignalStatus() {\n      const key = getAdminKey();\n      const badge = document.getElementById('onesignalBadge');\n      try {\n        const res = await fetch('/api/admin/onesignal/status', {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) return;\n        const data = await res.json();\n        if (badge) {\n          if (data.configured) {\n            badge.className = 'badge bg-success';\n            badge.innerHTML = '<i class=\"bi bi-check-circle-fill me-1\"></i> پیکربندی‌شده و متصل';\n          } else {\n            badge.className = 'badge bg-warning text-dark';\n            badge.innerHTML = '<i class=\"bi bi-exclamation-triangle-fill me-1\"></i> کلیدها در Render تنظیم نشده‌اند';\n          }\n        }\n      } catch (e) {\n        if (badge) {\n          badge.className = 'badge bg-secondary';\n          badge.innerText = 'عدم دسترسی به وضعیت';\n        }\n      }\n    }\n\n    async function sendPushNotification() {\n      const title = (document.getElementById('pushTitle')?.value || '').trim();\n      const message = (document.getElementById('pushMessage')?.value || '').trim();\n      const audience = document.getElementById('pushAudience')?.value || 'ALL';\n\n      if (!title || !message) {\n        alert('لطفاً عنوان و متن اعلان پوش را وارد کنید.');\n        return;\n      }\n\n      const btn = document.getElementById('sendPushBtn');\n      const spinner = document.getElementById('pushSpinner');\n      if (btn) btn.setAttribute('disabled', 'true');\n      if (spinner) spinner.classList.remove('d-none');\n\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/admin/push-notification', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({ title, message, audience })\n        });\n        const data = await res.json();\n        if (data.success) {\n          alert('اعلان پوش با موفقیت به سرویس OneSignal ارسال گردید.');\n          document.getElementById('pushTitle').value = '';\n          document.getElementById('pushMessage').value = '';\n        } else {\n          alert('خطا در ارسال اعلان: ' + (data.error || 'پاسخ ناموفق'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط با سرور: ' + err.message);\n      } finally {\n        if (btn) btn.removeAttribute('disabled');\n        if (spinner) spinner.classList.add('d-none');\n      }\n    }\n\n    // ==============================================================\n    // Store Management Functions\n    // ==============================================================\n    function toggleStoreUnitsLabel() {\n      const type = document.getElementById('storeProdType')?.value;\n      const label = document.getElementById('storeUnitsLabel');\n      const unitsInput = document.getElementById('storeProdUnits');\n      if (type === 'ACCOUNT_UPGRADE') {\n        if (label) label.innerText = 'سطح ارتقا (۱ = VIP کامل):';\n        if (unitsInput) unitsInput.value = 1;\n      } else {\n        if (label) label.innerText = 'تعداد مربع‌های اعطایی:';\n        if (unitsInput && unitsInput.value == 1) unitsInput.value = 10;\n      }\n    }\n\n    async function loadStoreProducts() {\n      const tbody = document.getElementById('storeProductsTbody');\n      const key = getAdminKey();\n\n      try {\n        const res = await fetch('/api/admin/store/products', {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) throw new Error('خطا در دریافت بسته‌ها (کد ' + res.status + ')');\n        const data = await res.json();\n        cachedStoreProducts = data.products || [];\n\n        // Update counts\n        const countEl = document.getElementById('storePackagesCount');\n        if (countEl) countEl.innerText = `${cachedStoreProducts.length} بسته`;\n        const sidebarBadge = document.getElementById('sidebarStoreBadge');\n        if (sidebarBadge) sidebarBadge.innerText = `${cachedStoreProducts.length} بسته`;\n\n        if (!tbody) return;\n        if (cachedStoreProducts.length === 0) {\n          tbody.innerHTML = '<tr><td colspan=\"8\" class=\"text-center text-secondary py-4\">هیچ بسته‌ای در فروشگاه تعریف نشده است.</td></tr>';\n          return;\n        }\n\n        tbody.innerHTML = cachedStoreProducts.map(p => {\n          const typeLabel = p.product_type === 'ACCOUNT_UPGRADE' \n            ? '<span class=\"badge bg-warning text-dark\"><i class=\"bi bi-star-fill me-1\"></i> ارتقای سطح حساب</span>' \n            : '<span class=\"badge bg-primary\"><i class=\"bi bi-grid-fill me-1\"></i> بازگشایی مربع</span>';\n          \n          let unitsLabel = '';\n          if (p.id === 'pkg_upgrade_silver') {\n            unitsLabel = '<span class=\"badge bg-info text-dark\">ضریب ۳ برابری (۳X)</span>';\n          } else if (p.id === 'pkg_upgrade_gold') {\n            unitsLabel = '<span class=\"badge bg-warning text-dark\">ضریب ۶ برابری (۶X)</span>';\n          } else {\n            unitsLabel = `<strong class=\"text-warning\">${Number(p.units_granted).toLocaleString('fa-IR')}</strong> مربع`;\n          }\n\n          const priceFormatted = Number(p.price_toman).toLocaleString('fa-IR') + ' تومان';\n\n          const myketStatus = p.is_ready_in_myket\n            ? '<span class=\"badge bg-success\"><i class=\"bi bi-check-circle me-1\"></i> فعال در مایکت</span>'\n            : '<span class=\"badge bg-secondary\"><i class=\"bi bi-clock me-1\"></i> در حال آماده‌سازی</span>';\n\n          const activeBadge = p.is_active\n            ? '<span class=\"badge bg-success-subtle text-success border border-success\">نمایش فعال</span>'\n            : '<span class=\"badge bg-danger-subtle text-danger border border-danger\">مخفی / غیرفعال</span>';\n\n          const badgeDisplay = p.badge ? `<span class=\"badge bg-dark border border-warning text-warning ms-1\">${escapeHtml(p.badge)}</span>` : '';\n\n          return `\n            <tr>\n              <td>\n                <div class=\"fw-bold text-white\">${escapeHtml(p.title)} ${badgeDisplay}</div>\n                <div class=\"text-secondary small text-truncate\" style=\"max-width: 250px;\">${escapeHtml(p.description)}</div>\n              </td>\n              <td>${typeLabel}</td>\n              <td>${unitsLabel}</td>\n              <td class=\"fw-bold text-info\">${priceFormatted}</td>\n              <td><code class=\"text-warning\" style=\"font-size: 11px;\">${escapeHtml(p.myket_sku)}</code></td>\n              <td>${myketStatus}</td>\n              <td>${activeBadge}</td>\n              <td>\n                <button class=\"btn btn-warning btn-sm\" onclick=\"openEditProductModal('${p.id}')\" title=\"ویرایش قیمت\"><i class=\"bi bi-pencil-fill me-1\"></i> ویرایش قیمت</button>\n              </td>\n            </tr>\n          `;\n        }).join('');\n      } catch (err) {\n        if (tbody) tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center text-danger py-4\">خطا: ${escapeHtml(err.message)}</td></tr>`;\n      }\n    }\n\n    async function loadStorePurchases() {\n      const tbody = document.getElementById('storePurchasesTbody');\n      const key = getAdminKey();\n\n      try {\n        const res = await fetch('/api/admin/store/purchases', {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) throw new Error('خطا در دریافت سوابق تراکنش‌ها');\n        const data = await res.json();\n        cachedStorePurchases = data.purchases || [];\n\n        // Update metric summaries\n        const purchasesCountEl = document.getElementById('storeTotalPurchases');\n        if (purchasesCountEl) purchasesCountEl.innerText = `${cachedStorePurchases.length} تراکنش`;\n\n        let totalRev = 0;\n        cachedStorePurchases.forEach(item => {\n          if (item.status === 'SUCCESS') totalRev += Number(item.amount || 0);\n        });\n        const revEl = document.getElementById('storeTotalRevenue');\n        if (revEl) revEl.innerText = `${totalRev.toLocaleString('fa-IR')} تومان`;\n\n        if (!tbody) return;\n        if (cachedStorePurchases.length === 0) {\n          tbody.innerHTML = '<tr><td colspan=\"7\" class=\"text-center text-secondary py-4\">تاکنون تراکنشی ثبت نشده است.</td></tr>';\n          return;\n        }\n\n        tbody.innerHTML = cachedStorePurchases.map(row => {\n          const userMasked = (row.first_name || '') + ' ' + (row.last_name || '') + (row.phone_number ? ` (${row.phone_number})` : '');\n          const statusBadge = row.status === 'SUCCESS' \n            ? '<span class=\"badge bg-success\"><i class=\"bi bi-check-lg me-1\"></i> تایید شده</span>'\n            : `<span class=\"badge bg-danger\"><i class=\"bi bi-x-circle me-1\"></i> ${escapeHtml(row.status)}</span>`;\n\n          const tokenDisplay = row.purchase_token \n            ? `<code class=\"text-secondary\" style=\"font-size: 11px;\">${escapeHtml(row.purchase_token.substring(0, 16))}...</code>`\n            : '<span class=\"text-muted small\">ندارد</span>';\n\n          const dateStr = row.created_at ? new Date(row.created_at).toLocaleString('fa-IR') : '—';\n\n          return `\n            <tr>\n              <td><span class=\"font-monospace small text-info\">${escapeHtml(row.purchase_id)}</span></td>\n              <td><span class=\"small text-white\">${escapeHtml(userMasked || row.user_id)}</span></td>\n              <td><strong>${escapeHtml(row.product_title || row.product_id)}</strong></td>\n              <td class=\"text-warning fw-bold\">${Number(row.amount).toLocaleString('fa-IR')} تومان</td>\n              <td>${tokenDisplay}</td>\n              <td>${statusBadge}</td>\n              <td class=\"small text-secondary\">${dateStr}</td>\n            </tr>\n          `;\n        }).join('');\n      } catch (err) {\n        if (tbody) tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center text-danger py-4\">خطا: ${escapeHtml(err.message)}</td></tr>`;\n      }\n    }\n\n    function openAddProductModal() {\n      alert('امکان افزودن بسته جدید وجود ندارد. فروشگاه شامل ۴ بسته ثابت (۲ بسته بازگشایی مربع و ۲ بسته ارتقای نقره‌ای و طلایی) است و فقط ویرایش قیمت مجاز است.');\n    }\n\n    function openEditProductModal(id) {\n      const prod = cachedStoreProducts.find(p => p.id === id);\n      if (!prod) return;\n\n      document.getElementById('storeProdId').value = prod.id;\n      document.getElementById('storeProdTitle').value = prod.title || '';\n      document.getElementById('storeProdDesc').value = prod.description || '';\n      document.getElementById('storeProdType').value = prod.product_type || 'SQUARE_UNLOCK';\n      document.getElementById('storeProdTypeDisplay').value = (prod.product_type === 'ACCOUNT_UPGRADE' ? 'ارتقای حساب کاربری (VIP)' : 'بازگشایی مربع مسابقه');\n      document.getElementById('storeProdUnits').value = prod.units_granted || 10;\n      document.getElementById('storeProdPrice').value = prod.price_toman || 0;\n      document.getElementById('storeProdSku').value = prod.myket_sku || '';\n      document.getElementById('storeProdBadge').value = prod.badge || '';\n      document.getElementById('storeProdSort').value = prod.sort_order || 1;\n      document.getElementById('storeProdIsActive').checked = Boolean(prod.is_active);\n      document.getElementById('storeProdIsReadyInMyket').checked = Boolean(prod.is_ready_in_myket);\n\n      document.getElementById('storeProductModalLabel').innerHTML = '<i class=\"bi bi-pencil-square me-2\"></i> ویرایش قیمت بسته فروشگاه';\n      if (!bootstrapStoreModal) {\n        bootstrapStoreModal = new bootstrap.Modal(document.getElementById('storeProductModal'));\n      }\n      bootstrapStoreModal.show();\n    }\n\n    async function saveStoreProduct(event) {\n      event.preventDefault();\n      const id = document.getElementById('storeProdId').value.trim();\n      const title = document.getElementById('storeProdTitle').value.trim();\n      const description = document.getElementById('storeProdDesc').value.trim();\n      const product_type = document.getElementById('storeProdType').value;\n      const units_granted = Number(document.getElementById('storeProdUnits').value);\n      const price_toman = Number(document.getElementById('storeProdPrice').value);\n      const myket_sku = document.getElementById('storeProdSku').value.trim();\n      const badge = document.getElementById('storeProdBadge').value.trim();\n      const sort_order = Number(document.getElementById('storeProdSort').value);\n      const is_active = document.getElementById('storeProdIsActive').checked;\n      const is_ready_in_myket = document.getElementById('storeProdIsReadyInMyket').checked;\n\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/admin/store/products', {\n          method: 'POST',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': key\n          },\n          body: JSON.stringify({\n            id: id || undefined,\n            title,\n            description,\n            product_type,\n            units_granted,\n            price_toman,\n            myket_sku,\n            badge,\n            sort_order,\n            is_active,\n            is_ready_in_myket\n          })\n        });\n\n        const data = await res.json();\n        if (data.success) {\n          if (bootstrapStoreModal) bootstrapStoreModal.hide();\n          loadStoreProducts();\n        } else {\n          alert('خطا در ذخیره بسته: ' + (data.error || 'پاسخ ناموفق'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط با سرور: ' + err.message);\n      }\n    }\n\n    async function deleteStoreProduct(id) {\n      if (!confirm('آیا از حذف این بسته از فروشگاه اطمینان دارید؟')) return;\n      const key = getAdminKey();\n\n      try {\n        const res = await fetch(`/api/admin/store/products/${id}`, {\n          method: 'DELETE',\n          headers: { 'x-admin-key': key }\n        });\n        const data = await res.json();\n        if (data.success) {\n          loadStoreProducts();\n        } else {\n          alert('خطا در حذف بسته: ' + (data.error || 'پاسخ ناموفق'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط با سرور: ' + err.message);\n      }\n    }\n\n    // ==============================================================\n    // Rewards & Claims JS Functions\n    // ==============================================================\n    let cachedRewards = [];\n    let cachedCategories = [];\n    let cachedClaims = [];\n    let bootstrapRewardModal = null;\n    let bootstrapClaimModal = null;\n\n    async function loadRewardsData() {\n      const tbody = document.getElementById('rewardsTbody');\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/rewards/admin/rewards', { headers: { 'x-admin-key': key } });\n        if (!res.ok) throw new Error('خطا در دریافت لیست جوایز');\n        const data = await res.json();\n        cachedRewards = data.rewards || [];\n\n        if (!tbody) return;\n        if (cachedRewards.length === 0) {\n          tbody.innerHTML = '<tr><td colspan=\"7\" class=\"text-center text-secondary py-4\">هیچ جایزه‌ای ثبت نشده است.</td></tr>';\n          return;\n        }\n\n        tbody.innerHTML = cachedRewards.map(r => {\n          const imgHtml = r.image_url \n            ? `<img src=\"${escapeHtml(r.image_url)}\" style=\"width:40px;height:40px;object-fit:cover;\" class=\"rounded me-2\">`\n            : `<div class=\"rounded me-2 d-inline-flex align-items-center justify-content-center bg-secondary\" style=\"width:40px;height:40px;\"><i class=\"bi bi-gift text-white\"></i></div>`;\n          const featuredBadge = r.is_featured ? '<span class=\"badge bg-warning text-dark\">ویژه</span>' : '<span class=\"text-muted small\">—</span>';\n          const activeBadge = r.is_active ? '<span class=\"badge bg-success\">فعال</span>' : '<span class=\"badge bg-danger\">غیرفعال</span>';\n          const costText = Number(r.cost_points).toLocaleString('fa-IR') + ' امتیاز';\n\n          return `\n            <tr>\n              <td>\n                <div class=\"d-flex align-items-center\">\n                  ${imgHtml}\n                  <div>\n                    <strong class=\"text-white\">${escapeHtml(r.title)}</strong>\n                    <div class=\"text-secondary small\">${escapeHtml(r.description || '')}</div>\n                  </div>\n                </div>\n              </td>\n              <td><span class=\"badge bg-dark border border-secondary\">${escapeHtml(r.category_name || r.category_id || 'عمومی')}</span></td>\n              <td class=\"fw-bold text-warning\">${costText}</td>\n              <td class=\"fw-bold text-info\">${Number(r.stock_quantity).toLocaleString('fa-IR')} عدد</td>\n              <td>${featuredBadge}</td>\n              <td>${activeBadge}</td>\n              <td>\n                <div class=\"btn-group btn-group-sm\">\n                  <button class=\"btn btn-outline-warning\" onclick=\"openEditRewardModal('${r.id}')\"><i class=\"bi bi-pencil-fill\"></i></button>\n                  <button class=\"btn btn-outline-danger\" onclick=\"deleteReward('${r.id}')\"><i class=\"bi bi-trash-fill\"></i></button>\n                </div>\n              </td>\n            </tr>\n          `;\n        }).join('');\n      } catch (err) {\n        if (tbody) tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center text-danger py-4\">خطا: ${escapeHtml(err.message)}</td></tr>`;\n      }\n    }\n\n    function openAddRewardModal() {\n      document.getElementById('rewModalId').value = '';\n      document.getElementById('rewModalTitle').value = '';\n      document.getElementById('rewModalCost').value = 100;\n      document.getElementById('rewModalStock').value = 50;\n      document.getElementById('rewModalImageUrl').value = '';\n      document.getElementById('rewModalDesc').value = '';\n      document.getElementById('rewModalIsFeatured').checked = true;\n      document.getElementById('rewModalIsActive').checked = true;\n\n      document.getElementById('rewardModalLabel').innerHTML = '<i class=\"bi bi-plus-circle-fill me-2\"></i> تعریف جایزه جدید';\n      if (!bootstrapRewardModal) bootstrapRewardModal = new bootstrap.Modal(document.getElementById('rewardModal'));\n      bootstrapRewardModal.show();\n    }\n\n    function openEditRewardModal(id) {\n      const r = cachedRewards.find(item => item.id === id);\n      if (!r) return;\n\n      document.getElementById('rewModalId').value = r.id;\n      document.getElementById('rewModalTitle').value = r.title || '';\n      document.getElementById('rewModalCategory').value = r.category_id || 'cat_recharge';\n      document.getElementById('rewModalCost').value = r.cost_points || 0;\n      document.getElementById('rewModalStock').value = r.stock_quantity || 0;\n      document.getElementById('rewModalImageUrl').value = r.image_url || '';\n      document.getElementById('rewModalDesc').value = r.description || '';\n      document.getElementById('rewModalIsFeatured').checked = Boolean(r.is_featured);\n      document.getElementById('rewModalIsActive').checked = Boolean(r.is_active);\n\n      document.getElementById('rewardModalLabel').innerHTML = '<i class=\"bi bi-pencil-square me-2\"></i> ویرایش اطلاعات جایزه';\n      if (!bootstrapRewardModal) bootstrapRewardModal = new bootstrap.Modal(document.getElementById('rewardModal'));\n      bootstrapRewardModal.show();\n    }\n\n    async function saveReward(event) {\n      event.preventDefault();\n      const id = document.getElementById('rewModalId').value;\n      const title = document.getElementById('rewModalTitle').value.trim();\n      const category_id = document.getElementById('rewModalCategory').value;\n      const cost_points = Number(document.getElementById('rewModalCost').value);\n      const stock_quantity = Number(document.getElementById('rewModalStock').value);\n      const image_url = document.getElementById('rewModalImageUrl').value.trim();\n      const description = document.getElementById('rewModalDesc').value.trim();\n      const is_featured = document.getElementById('rewModalIsFeatured').checked;\n      const is_active = document.getElementById('rewModalIsActive').checked;\n\n      const key = getAdminKey();\n      const url = id ? `/api/rewards/admin/rewards/${id}` : '/api/rewards/admin/rewards';\n      const method = id ? 'PUT' : 'POST';\n\n      try {\n        const res = await fetch(url, {\n          method,\n          headers: { 'Content-Type': 'application/json', 'x-admin-key': key },\n          body: JSON.stringify({ title, category_id, cost_points, stock_quantity, image_url, description, is_featured, is_active })\n        });\n        const data = await res.json();\n        if (data.success) {\n          if (bootstrapRewardModal) bootstrapRewardModal.hide();\n          loadRewardsData();\n        } else {\n          alert('خطا: ' + (data.message || 'ثبت جایزه ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      }\n    }\n\n    async function deleteReward(id) {\n      if (!confirm('آیا از حذف این جایزه اطمینان دارید؟')) return;\n      const key = getAdminKey();\n      try {\n        const res = await fetch(`/api/rewards/admin/rewards/${id}`, { method: 'DELETE', headers: { 'x-admin-key': key } });\n        const data = await res.json();\n        if (data.success) {\n          loadRewardsData();\n        } else {\n          alert('خطا: ' + data.message);\n        }\n      } catch (err) {\n        alert('خطا: ' + err.message);\n      }\n    }\n\n    function updateBannerImagePreview(url) {\n      const previewContainer = document.getElementById('rewAppPreviewContainer');\n      const previewImg = document.getElementById('rewAppPreviewImg');\n      const promptDiv = document.getElementById('rewAppUploadPrompt');\n      const urlInput = document.getElementById('rewAppBannerUrl');\n\n      if (url && url.trim() !== '') {\n        if (urlInput) urlInput.value = url;\n        if (previewImg) previewImg.src = url;\n        if (previewContainer) previewContainer.classList.remove('d-none');\n        if (promptDiv) promptDiv.classList.add('d-none');\n      } else {\n        if (urlInput) urlInput.value = '';\n        if (previewImg) previewImg.src = '';\n        if (previewContainer) previewContainer.classList.add('d-none');\n        if (promptDiv) promptDiv.classList.remove('d-none');\n      }\n    }\n\n    function removeBannerImage() {\n      const fileInput = document.getElementById('rewAppImageFile');\n      if (fileInput) fileInput.value = '';\n      updateBannerImagePreview('');\n    }\n\n    async function handleBannerImageSelect(event) {\n      const file = event.target.files[0];\n      if (!file) return;\n\n      // Validate Type & Size\n      const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];\n      if (!allowedTypes.includes(file.type)) {\n        alert('خطا: فقط فرمت‌های JPG، PNG و WebP مجاز هستند.');\n        event.target.value = '';\n        return;\n      }\n      if (file.size > 5 * 1024 * 1024) {\n        alert('خطا: حجم فایل نباید بیشتر از ۵ مگابایت باشد.');\n        event.target.value = '';\n        return;\n      }\n\n      // Show local preview immediately\n      const reader = new FileReader();\n      reader.onload = function(e) {\n        updateBannerImagePreview(e.target.result);\n      };\n      reader.readAsDataURL(file);\n\n      // Upload progress simulation & actual upload\n      const progressWrapper = document.getElementById('rewAppUploadProgressWrapper');\n      const progressBar = document.getElementById('rewAppUploadProgressBar');\n      const percentText = document.getElementById('rewAppUploadPercent');\n      const statusText = document.getElementById('rewAppUploadStatusText');\n\n      if (progressWrapper) progressWrapper.classList.remove('d-none');\n      if (progressBar) progressBar.style.width = '20%';\n      if (percentText) percentText.innerText = '۲۰٪';\n      if (statusText) statusText.innerText = 'در حال آماده‌سازی فایل در Supabase Storage...';\n\n      const formData = new FormData();\n      formData.append('banner', file);\n\n      const key = getAdminKey();\n      try {\n        if (progressBar) progressBar.style.width = '60%';\n        if (percentText) percentText.innerText = '۶۰٪';\n        if (statusText) statusText.innerText = 'در حال آپلود در bucket نام‌گذاری شده gift-banners...';\n\n        const res = await fetch('/api/rewards/admin/upload-banner', {\n          method: 'POST',\n          headers: { 'x-admin-key': key },\n          body: formData\n        });\n        const data = await res.json();\n\n        if (progressBar) progressBar.style.width = '100%';\n        if (percentText) percentText.innerText = '۱۰۰٪';\n        if (statusText) statusText.innerText = 'آپلود موفقیت‌آمیز در Supabase Storage!';\n\n        setTimeout(() => {\n          if (progressWrapper) progressWrapper.classList.add('d-none');\n        }, 1500);\n\n        if (data.success && data.url) {\n          updateBannerImagePreview(data.url);\n          // Auto save appearance immediately to make the uploaded banner active\n          try {\n            const hero_title = document.getElementById('rewAppHeroTitle')?.value.trim() || 'اینترنت ۲۰ گیگ برنده شو!';\n            const primary_color = document.getElementById('rewAppColor')?.value || '#10B981';\n            const hero_subtitle = document.getElementById('rewAppHeroSubtitle')?.value.trim() || 'هدیه ویژه دوره جاری مسابقه رقابت کن، جایزه ببر';\n            const terms_text = document.getElementById('rewAppTermsText')?.value.trim() || '';\n            const is_active = document.getElementById('rewAppIsActive')?.checked ?? true;\n\n            await fetch('/api/rewards/admin/appearance', {\n              method: 'POST',\n              headers: { 'Content-Type': 'application/json', 'x-admin-key': key },\n              body: JSON.stringify({\n                hero_title,\n                primary_color,\n                hero_subtitle,\n                hero_banner_url: data.url,\n                terms_text,\n                is_active,\n                active_sections: { isActive: is_active }\n              })\n            });\n            alert('تصویر بنر با موفقیت در سرور بارگذاری شد و به‌عنوان بنر فعال جایگزین گردید.');\n          } catch (saveErr) {\n            console.warn('Auto-save appearance notice:', saveErr);\n          }\n        } else {\n          alert('خطا در آپلود: ' + (data.message || 'خطای سرور'));\n        }\n      } catch (err) {\n        if (progressWrapper) progressWrapper.classList.add('d-none');\n        alert('خطای شبکه در بارگذاری تصویر: آرامش خود را حفظ کرده و دوباره تلاش کنید.');\n      }\n    }\n\n    async function loadRewardAppearance() {\n      try {\n        const res = await fetch('/api/rewards/appearance');\n        const data = await res.json();\n        if (data.success && data.appearance) {\n          const app = data.appearance;\n          if (document.getElementById('rewAppHeroTitle')) document.getElementById('rewAppHeroTitle').value = app.hero_title || '';\n          if (document.getElementById('rewAppColor')) document.getElementById('rewAppColor').value = app.primary_color || '#10B981';\n          if (document.getElementById('rewAppHeroSubtitle')) document.getElementById('rewAppHeroSubtitle').value = app.hero_subtitle || '';\n          updateBannerImagePreview(app.hero_banner_url || '');\n          if (document.getElementById('rewAppTermsText')) document.getElementById('rewAppTermsText').value = app.terms_text || '';\n          const isActive = (app.is_active !== false && app.active_sections?.isActive !== false);\n          if (document.getElementById('rewAppIsActive')) document.getElementById('rewAppIsActive').checked = isActive;\n        }\n      } catch (err) {\n        console.error('Error loading appearance:', err);\n      }\n    }\n\n    async function saveRewardAppearance(event) {\n      event.preventDefault();\n      const hero_title = document.getElementById('rewAppHeroTitle')?.value.trim() || '';\n      const primary_color = document.getElementById('rewAppColor')?.value || '#10B981';\n      const hero_subtitle = document.getElementById('rewAppHeroSubtitle')?.value.trim() || '';\n      const hero_banner_url = document.getElementById('rewAppBannerUrl')?.value.trim() || '';\n      const terms_text = document.getElementById('rewAppTermsText')?.value.trim() || '';\n      const is_active = document.getElementById('rewAppIsActive')?.checked ?? true;\n\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/rewards/admin/appearance', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'x-admin-key': key },\n          body: JSON.stringify({\n            hero_title,\n            primary_color,\n            hero_subtitle,\n            hero_banner_url,\n            terms_text,\n            is_active,\n            active_sections: { isActive: is_active }\n          })\n        });\n        const data = await res.json();\n        if (data.success) {\n          alert('اطلاعات بنر هدیه با موفقیت در دیتابیس ذخیره گردید.');\n        } else {\n          alert('خطا: ' + (data.message || 'ثبت نا موفق بود'));\n        }\n      } catch (err) {\n        alert('خطا: ' + err.message);\n      }\n    }\n\n    async function loadRewardClaims() {\n      const tbody = document.getElementById('rewardClaimsTbody');\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/rewards/admin/claims', { headers: { 'x-admin-key': key } });\n        if (!res.ok) throw new Error('خطا در دریافت لیست درخواست‌ها');\n        const data = await res.json();\n        cachedClaims = data.claims || [];\n\n        // Sidebar claims count badge\n        const pendingCount = cachedClaims.filter(c => c.status === 'PENDING').length;\n        const badge = document.getElementById('sidebarClaimsBadge');\n        if (badge) badge.innerText = pendingCount.toString();\n\n        if (!tbody) return;\n        if (cachedClaims.length === 0) {\n          tbody.innerHTML = '<tr><td colspan=\"8\" class=\"text-center text-secondary py-4\">هیچ درخواستی ثبت نشده است.</td></tr>';\n          return;\n        }\n\n        const STATUS_MAP = {\n          'PENDING': { label: 'در حال بررسی', cls: 'bg-warning text-dark' },\n          'APPROVED': { label: 'تایید شده', cls: 'bg-info text-dark' },\n          'PROCESSING': { label: 'در حال ارسال', cls: 'bg-primary' },\n          'SHIPPED': { label: 'ارسال شد', cls: 'bg-success' },\n          'COMPLETED': { label: 'تکمیل شده', cls: 'bg-success' },\n          'REJECTED': { label: 'رد شد', cls: 'bg-danger' }\n        };\n\n        tbody.innerHTML = cachedClaims.map(c => {\n          const st = STATUS_MAP[c.status] || { label: c.status, cls: 'bg-secondary' };\n          const dateStr = c.created_at ? new Date(c.created_at).toLocaleString('fa-IR') : '—';\n          const userText = (c.first_name || '') + ' ' + (c.last_name || '') + (c.phone || c.phone_number ? ` (${c.phone || c.phone_number})` : '');\n\n          return `\n            <tr>\n              <td><code class=\"text-warning fw-bold\">${escapeHtml(c.tracking_code)}</code></td>\n              <td><span class=\"small text-white\">${escapeHtml(userText || c.user_id)}</span></td>\n              <td><strong>${escapeHtml(c.reward_title || c.reward_id)}</strong></td>\n              <td class=\"text-info fw-bold\">${Number(c.cost_points || c.reward_cost || 0).toLocaleString('fa-IR')} امتیاز</td>\n              <td>\n                <div class=\"small fw-bold text-white\">${escapeHtml(c.recipient_name || '—')}</div>\n                <div class=\"small text-secondary text-truncate\" style=\"max-width: 200px;\">${escapeHtml(c.shipping_address || 'تحویل دیجیتال')}</div>\n              </td>\n              <td><span class=\"badge ${st.cls}\">${st.label}</span></td>\n              <td class=\"small text-secondary\">${dateStr}</td>\n              <td>\n                <button class=\"btn btn-outline-warning btn-sm\" onclick=\"openEditClaimModal('${c.id}')\"><i class=\"bi bi-pencil-fill\"></i> مدیریت</button>\n              </td>\n            </tr>\n          `;\n        }).join('');\n      } catch (err) {\n        if (tbody) tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center text-danger py-4\">خطا: ${escapeHtml(err.message)}</td></tr>`;\n      }\n    }\n\n    function openEditClaimModal(id) {\n      const c = cachedClaims.find(item => item.id === id);\n      if (!c) return;\n\n      document.getElementById('claimModalId').value = c.id;\n      document.getElementById('claimModalStatus').value = c.status || 'PENDING';\n      document.getElementById('claimModalTracking').value = c.tracking_number || '';\n      document.getElementById('claimModalNotes').value = c.admin_notes || '';\n\n      if (!bootstrapClaimModal) bootstrapClaimModal = new bootstrap.Modal(document.getElementById('claimModal'));\n      bootstrapClaimModal.show();\n    }\n\n    async function saveClaimStatus(event) {\n      event.preventDefault();\n      const id = document.getElementById('claimModalId').value;\n      const status = document.getElementById('claimModalStatus').value;\n      const tracking_number = document.getElementById('claimModalTracking').value.trim();\n      const admin_notes = document.getElementById('claimModalNotes').value.trim();\n\n      const key = getAdminKey();\n      try {\n        const res = await fetch(`/api/rewards/admin/claims/${id}`, {\n          method: 'PATCH',\n          headers: { 'Content-Type': 'application/json', 'x-admin-key': key },\n          body: JSON.stringify({ status, tracking_number, admin_notes })\n        });\n        const data = await res.json();\n        if (data.success) {\n          if (bootstrapClaimModal) bootstrapClaimModal.hide();\n          loadRewardClaims();\n        } else {\n          alert('خطا: ' + (data.message || 'اعمال تغییرات ناموفق بود'));\n        }\n      } catch (err) {\n        alert('خطای ارتباط: ' + err.message);\n      }\n    }\n\n    // ====================================================================\n    // LOGIN NOTIFICATION MANAGEMENT\n    // ====================================================================\n    async function loadLoginNotification() {\n      const key = getAdminKey();\n      try {\n        const res = await fetch('/api/admin/login-notification', {\n          headers: { 'x-admin-key': key }\n        });\n        if (!res.ok) return;\n        const data = await res.json();\n        const s = data.settings || data.data;\n        if (data.success && s) {\n          document.getElementById('ln_isVisible').checked = (s.is_visible !== false);\n          document.getElementById('ln_badgeText').value = s.badge_text || '';\n          document.getElementById('ln_badgeIcon').value = s.badge_icon || 'verified';\n          document.getElementById('ln_mainTitle').value = s.main_title || '';\n          document.getElementById('ln_mainDescription').value = s.main_description || '';\n          document.getElementById('ln_warningIsVisible').checked = (s.warning_is_visible !== false);\n          document.getElementById('ln_warningTitle').value = s.warning_title || '';\n          document.getElementById('ln_warningDescription').value = s.warning_description || '';\n          document.getElementById('ln_warningIcon').value = s.warning_icon || 'signal_cellular_alt';\n          \n          updateLNPreview();\n        }\n      } catch (err) {\n        console.error('[Login Notification Load Error]', err);\n      }\n    }\n\n    function updateLNPreview() {\n      const isVisible = document.getElementById('ln_isVisible').checked;\n      const warningIsVisible = document.getElementById('ln_warningIsVisible').checked;\n      \n      const container = document.getElementById('ln_preview_container');\n      const hiddenMsg = document.getElementById('ln_preview_hidden_msg');\n      \n      if (!isVisible) {\n        container.style.display = 'none';\n        hiddenMsg.style.display = 'block';\n        return;\n      }\n      \n      container.style.display = 'block';\n      hiddenMsg.style.display = 'none';\n      \n      setElText('ln_preview_badgeText', document.getElementById('ln_badgeText').value);\n      setElText('ln_preview_mainTitle', document.getElementById('ln_mainTitle').value);\n      setElText('ln_preview_mainDescription', document.getElementById('ln_mainDescription').value);\n      setElText('ln_preview_warningTitle', document.getElementById('ln_warningTitle').value);\n      setElText('ln_preview_warningDescription', document.getElementById('ln_warningDescription').value);\n      \n      // Update Icons\n      const badgeIcon = document.getElementById('ln_badgeIcon').value;\n      const warningIcon = document.getElementById('ln_warningIcon').value;\n      \n      const biMap = {\n        'verified': 'bi-patch-check-fill',\n        'stars': 'bi-stars',\n        'check_circle': 'bi-check-circle-fill',\n        'emoji_events': 'bi-trophy-fill'\n      };\n      const wiMap = {\n        'signal_cellular_alt': 'bi-reception-4',\n        'wifi_off': 'bi-wifi-off',\n        'cell_tower': 'bi-broadcast-pin'\n      };\n      \n      const badgeIconEl = document.getElementById('ln_preview_badgeIcon');\n      if (badgeIconEl) badgeIconEl.className = `bi ${biMap[badgeIcon] || 'bi-patch-check-fill'}`;\n      \n      const warningIconEl = document.getElementById('ln_preview_warningIcon');\n      if (warningIconEl) warningIconEl.className = `bi ${wiMap[warningIcon] || 'bi-reception-4'}`;\n      \n      // Warning visibility\n      document.getElementById('ln_preview_warningBox').style.display = warningIsVisible ? 'flex' : 'none';\n    }\n\n    async function saveLoginNotification(e) {\n      if (e) e.preventDefault();\n      const key = getAdminKey();\n      \n      const payload = {\n        is_visible: document.getElementById('ln_isVisible').checked,\n        badge_text: document.getElementById('ln_badgeText').value,\n        badge_icon: document.getElementById('ln_badgeIcon').value,\n        main_title: document.getElementById('ln_mainTitle').value,\n        main_description: document.getElementById('ln_mainDescription').value,\n        warning_is_visible: document.getElementById('ln_warningIsVisible').checked,\n        warning_title: document.getElementById('ln_warningTitle').value,\n        warning_description: document.getElementById('ln_warningDescription').value,\n        warning_icon: document.getElementById('ln_warningIcon').value\n      };\n      \n      try {\n        const res = await fetch('/api/admin/login-notification', {\n          method: 'POST',\n          headers: { 'x-admin-key': key, 'Content-Type': 'application/json' },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (data.success) {\n          showNotification('تنظیمات صفحه ورود با موفقیت ذخیره و منتشر شد.', 'success');\n        } else {\n          showNotification('خطا در ذخیره‌سازی: ' + (data.message || 'نامشخص'), 'error');\n        }\n      } catch (err) {\n        showNotification('خطای ارتباط با سرور: ' + err.message, 'error');\n      }\n    }\n\n    function resetLoginNotificationDefaults() {\n      if (!confirm('آیا مایل به بازگرداندن تنظیمات به حالت پیش‌فرض (ایرانسل) هستید؟')) return;\n      \n      document.getElementById('ln_isVisible').checked = true;\n      document.getElementById('ln_badgeText').value = 'سرویس اختصاصی مشترکین ایرانسل';\n      document.getElementById('ln_badgeIcon').value = 'verified';\n      document.getElementById('ln_mainTitle').value = 'سامانه منحصرأ ویژه مشترکان ارجمند ایرانسل';\n      document.getElementById('ln_mainDescription').value = 'با کمال احترام و افتخار، این سامانه منحصراً جهت حضور، رقابت و بهره‌مندی مشترکین گرامی و همراهان وفادار اپراتور ایرانسل طراحی گردیده است.';\n      document.getElementById('ln_warningIsVisible').checked = true;\n      document.getElementById('ln_warningTitle').value = 'شرط الزامی: ورود با «اینترنت دیتای ایرانسل»';\n      document.getElementById('ln_warningDescription').value = 'لطفاً پیش از ورود، وای‌فای و فیلترشکن را خاموش نموده و از طریق اینترنت همراه سیم‌کارت ایرانسل متصل گردید.';\n      document.getElementById('ln_warningIcon').value = 'signal_cellular_alt';\n      \n      updateLNPreview();\n    }\n\n    function showNotification(msg, type = 'success') {\n      // Basic fallback if global alert not ready\n      const alertBox = document.getElementById('alertBox');\n      if (alertBox) {\n        const bsType = type === 'success' ? 'success' : (type === 'warning' ? 'warning' : 'danger');\n        alertBox.innerText = msg;\n        alertBox.className = `alert alert-${bsType} shadow-sm mb-4`;\n        alertBox.classList.remove('d-none');\n        setTimeout(() => alertBox.classList.add('d-none'), 5000);\n      } else {\n        alert(msg);\n      }\n    }\n\n    // ====================================================================\n    // PROMOTIONAL AD BANNERS MANAGEMENT\n    // ====================================================================\n    let cachedAdBanners = [];\n    let bootstrapAdBannerModal = null;\n    let isUploadingAdBannerImage = false;\n    let adBannerModalLifecycleBound = false;\n    let adBannerFallbackBackdrop = null;\n\n    function showAdBannerSectionAlert(msg, type = 'success') {\n      const box = document.getElementById('adBannerAlertBox');\n      if (!box) return;\n      const cls = type === 'success' ? 'alert-success' : (type === 'warning' ? 'alert-warning' : 'alert-danger');\n      box.className = `alert ${cls} py-2 px-3 small mb-3`;\n      box.textContent = msg;\n      box.classList.remove('d-none');\n      clearTimeout(box._hideTimer);\n      box._hideTimer = setTimeout(() => box.classList.add('d-none'), 6000);\n    }\n\n    async function parseJsonResponseSafely(res) {\n      const text = await res.text();\n      if (!text) return {};\n      try {\n        return JSON.parse(text);\n      } catch (_e) {\n        return { success: false, message: `پاسخ نامعتبر از سرور دریافت شد (کد ${res.status})` };\n      }\n    }\n\n    function isValidHttpUrlFrontend(rawUrl) {\n      if (!rawUrl || typeof rawUrl !== 'string') return false;\n      const trimmed = rawUrl.trim();\n      if (!trimmed || /\\s/.test(trimmed)) return false;\n      try {\n        const parsed = new URL(trimmed);\n        return (parsed.protocol === 'http:' || parsed.protocol === 'https:') && Boolean(parsed.hostname && parsed.hostname.length >= 2);\n      } catch (_e) {\n        return false;\n      }\n    }\n\n    function isSafeBannerImageUrl(rawUrl) {\n      if (!rawUrl || typeof rawUrl !== 'string') return false;\n      const trimmed = rawUrl.trim();\n      if (!trimmed || /\\s/.test(trimmed)) return false;\n      if (trimmed.startsWith('/uploads/')) return true;\n      return isValidHttpUrlFrontend(trimmed);\n    }\n\n    function toDatetimeLocalValue(isoOrDate) {\n      if (!isoOrDate) return '';\n      const d = new Date(isoOrDate);\n      if (Number.isNaN(d.getTime())) return '';\n      const pad = (n) => String(n).padStart(2, '0');\n      return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;\n    }\n\n    function formatPersianDateTime(isoOrDate) {\n      if (!isoOrDate) return 'نامحدود';\n      const d = new Date(isoOrDate);\n      if (Number.isNaN(d.getTime())) return '-';\n      try {\n        return d.toLocaleString('fa-IR', {\n          year: 'numeric', month: '2-digit', day: '2-digit',\n          hour: '2-digit', minute: '2-digit'\n        });\n      } catch (_e) {\n        return d.toISOString();\n      }\n    }\n\n    function cleanupStaleAdBannerModalState() {\n      isUploadingAdBannerImage = false;\n      if (adBannerFallbackBackdrop && adBannerFallbackBackdrop.parentNode) {\n        adBannerFallbackBackdrop.parentNode.removeChild(adBannerFallbackBackdrop);\n        adBannerFallbackBackdrop = null;\n      }\n      const anyOpenModal = document.querySelector('.modal.show');\n      if (!anyOpenModal) {\n        document.querySelectorAll('.modal-backdrop').forEach((el) => el.remove());\n        document.body.classList.remove('modal-open');\n        document.body.style.removeProperty('overflow');\n        document.body.style.removeProperty('padding-right');\n      }\n    }\n\n    function hideAdBannerModalSafely() {\n      const modalEl = document.getElementById('adBannerModal');\n      if (modalEl && typeof bootstrap !== 'undefined' && bootstrap.Modal) {\n        const instance = bootstrap.Modal.getInstance(modalEl) || bootstrapAdBannerModal;\n        if (instance) {\n          instance.hide();\n          return;\n        }\n      }\n      if (modalEl) {\n        modalEl.classList.remove('show');\n        modalEl.style.display = 'none';\n        modalEl.setAttribute('aria-hidden', 'true');\n        modalEl.removeAttribute('aria-modal');\n        modalEl.removeAttribute('role');\n      }\n      cleanupStaleAdBannerModalState();\n    }\n\n    function bindAdBannerModalLifecycle(modalEl) {\n      if (!modalEl || adBannerModalLifecycleBound) return;\n      adBannerModalLifecycleBound = true;\n\n      modalEl.addEventListener('hidden.bs.modal', () => {\n        cleanupStaleAdBannerModalState();\n      });\n\n      // Fallback dismiss behavior only if Bootstrap JS is unavailable\n      modalEl.querySelectorAll('[data-bs-dismiss=\"modal\"]').forEach((btn) => {\n        btn.addEventListener('click', () => {\n          if (typeof bootstrap === 'undefined' || !bootstrap.Modal) {\n            hideAdBannerModalSafely();\n          }\n        });\n      });\n\n      modalEl.addEventListener('click', (e) => {\n        if ((typeof bootstrap === 'undefined' || !bootstrap.Modal) && e.target === modalEl) {\n          hideAdBannerModalSafely();\n        }\n      });\n\n      document.addEventListener('keydown', (e) => {\n        if (e.key === 'Escape' && (typeof bootstrap === 'undefined' || !bootstrap.Modal)) {\n          if (modalEl.classList.contains('show')) {\n            hideAdBannerModalSafely();\n          }\n        }\n      });\n    }\n\n    async function loadAdBanners() {\n      const key = getAdminKey();\n      const tbody = document.getElementById('adBannersTbody');\n      const countEl = document.getElementById('adBannersFilterCount');\n      if (tbody && cachedAdBanners.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"7\" class=\"text-center py-4 text-secondary\">در حال دریافت بنرهای تبلیغاتی...</td></tr>';\n      }\n\n      try {\n        const res = await fetch('/api/admin/ad-banners', {\n          headers: { 'x-admin-key': key }\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success) {\n          const errMsg = data.message || data.error || `خطا در دریافت بنرها (کد ${res.status})`;\n          if (res.status === 401) {\n            showAdBannerSectionAlert('کلید امنیتی مدیریت معتبر نیست. می‌توانید کلید را اصلاح کنید یا پس از ورود مجدد لیست را بازخوانی کنید.', 'warning');\n          } else {\n            showAdBannerSectionAlert(errMsg, 'error');\n          }\n          if (countEl) countEl.textContent = 'خطا در دریافت اطلاعات';\n          if (tbody) {\n            const authBtnHtml = res.status === 401\n              ? '<button type=\"button\" class=\"btn btn-outline-warning btn-sm ms-2\" onclick=\"openAdminAuthModal()\"><i class=\"bi bi-key me-1\"></i> ورود کلید مدیریت</button>'\n              : '';\n            tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center py-4 text-danger\">${escapeHtml(errMsg)}<div class=\"mt-2\"><button type=\"button\" class=\"btn btn-outline-warning btn-sm\" onclick=\"loadAdBanners()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> تلاش مجدد</button>${authBtnHtml}</div></td></tr>`;\n          }\n          return;\n        }\n\n        cachedAdBanners = Array.isArray(data.banners) ? data.banners : [];\n        const s = data.summary || {};\n\n        setElText('adBannersTotalCount', Number(s.total || 0).toLocaleString('fa-IR'));\n        setElText('adBannersActiveCount', Number(s.activeCount || 0).toLocaleString('fa-IR'));\n        setElText('adBannersTotalImpressions', Number(s.totalImpressions || 0).toLocaleString('fa-IR'));\n        setElText('adBannersTotalClicksCtr', `${Number(s.totalClicks || 0).toLocaleString('fa-IR')} (${s.avgCtr || 0}٪)`);\n\n        const badge = document.getElementById('sidebarAdBannersBadge');\n        if (badge) {\n          if ((s.activeCount || 0) > 0) {\n            badge.textContent = Number(s.activeCount).toLocaleString('fa-IR');\n            badge.style.display = 'inline-block';\n          } else {\n            badge.style.display = 'none';\n          }\n        }\n\n        renderAdBannersTable();\n      } catch (err) {\n        console.error('[AdBanners] loadAdBanners failed:', err);\n        const errMsg = 'خطای ارتباط با سرور: ' + (err?.message || 'نامشخص');\n        showAdBannerSectionAlert(errMsg, 'error');\n        if (countEl) countEl.textContent = 'عدم دسترسی موقت به سرور';\n        if (tbody) {\n          tbody.innerHTML = `<tr><td colspan=\"7\" class=\"text-center py-4 text-danger\">${escapeHtml(errMsg)}<div class=\"mt-2\"><button type=\"button\" class=\"btn btn-outline-warning btn-sm\" onclick=\"loadAdBanners()\"><i class=\"bi bi-arrow-clockwise me-1\"></i> تلاش مجدد</button></div></td></tr>`;\n        }\n      }\n    }\n\n    function renderPlacementStatsBreakdown(stats) {\n      if (!stats || typeof stats !== 'object') return '';\n      const placementLabels = { home: 'خانه', leaderboard: 'رتبه‌ها', profile: 'پروفایل', squares: 'مربع' };\n      const parts = [];\n      for (const [key, label] of Object.entries(placementLabels)) {\n        const item = stats[key];\n        if (item && ((item.impressions || 0) > 0 || (item.clicks || 0) > 0)) {\n          parts.push(`<span class=\"badge bg-secondary bg-opacity-75 text-light\" style=\"font-size: 9px;\" title=\"${label}: ${item.impressions || 0} نمایش، ${item.clicks || 0} کلیک\">${label}: ${Number(item.impressions || 0).toLocaleString('fa-IR')}ن / ${Number(item.clicks || 0).toLocaleString('fa-IR')}ک</span>`);\n        }\n      }\n      if (parts.length === 0) return '';\n      return `<div class=\"mt-1 d-flex flex-wrap gap-1\">${parts.join('')}</div>`;\n    }\n\n    function renderAdBannersTable() {\n      const tbody = document.getElementById('adBannersTbody');\n      const countEl = document.getElementById('adBannersFilterCount');\n      if (!tbody) return;\n\n      const search = (document.getElementById('adBannerSearchInput')?.value || '').trim().toLowerCase();\n      const statusFilter = document.getElementById('adBannerStatusFilter')?.value || 'all';\n      const placementFilter = document.getElementById('adBannerPlacementFilter')?.value || 'all';\n\n      const filtered = cachedAdBanners.filter((b) => {\n        if (statusFilter !== 'all' && b.computed_status !== statusFilter) return false;\n        if (placementFilter !== 'all' && (!b.placements || !b.placements.includes(placementFilter))) return false;\n        if (search) {\n          const hay = `${b.title || ''} ${b.target_url || ''}`.toLowerCase();\n          if (!hay.includes(search)) return false;\n        }\n        return true;\n      });\n\n      if (countEl) {\n        countEl.textContent = `نمایش ${filtered.length.toLocaleString('fa-IR')} از ${cachedAdBanners.length.toLocaleString('fa-IR')} تبلیغ`;\n      }\n\n      if (filtered.length === 0) {\n        tbody.innerHTML = '<tr><td colspan=\"7\" class=\"text-center py-4 text-secondary\">هنوز بنر تبلیغاتی ثبت نشده یا موردی با فیلتر انتخابی یافت نشد.</td></tr>';\n        return;\n      }\n\n      const statusBadges = {\n        active: '<span class=\"badge bg-success\">فعال</span>',\n        inactive: '<span class=\"badge bg-secondary\">غیرفعال</span>',\n        scheduled: '<span class=\"badge bg-info text-dark\">زمان‌بندی‌شده</span>',\n        expired: '<span class=\"badge bg-danger\">منقضی‌شده</span>'\n      };\n\n      const placementLabels = {\n        home: 'صفحه اصلی',\n        leaderboard: 'رتبه‌بندی',\n        profile: 'پروفایل',\n        squares: '۱۰۰ مربع'\n      };\n\n      tbody.innerHTML = filtered.map((b, idx) => {\n        const modeBadge = b.link_open_mode === 'internal'\n          ? '<span class=\"badge bg-dark border border-info text-info\" style=\"font-size: 11px;\">مرورگر داخلی</span>'\n          : '<span class=\"badge bg-dark border border-warning text-warning\" style=\"font-size: 11px;\">مرورگر خارجی</span>';\n\n        const bannerPlacements = Array.isArray(b.placements) ? b.placements : ['home'];\n        const placementBadges = bannerPlacements.map(p => `<span class=\"badge bg-dark border border-secondary text-light me-1\" style=\"font-size: 10px;\">${placementLabels[p] || p}</span>`).join('');\n\n        const safeUrl = isValidHttpUrlFrontend(b.target_url) ? b.target_url : '';\n        const safeImgUrl = isSafeBannerImageUrl(b.image_url) ? b.image_url : '';\n\n        return `\n          <tr>\n            <td>\n              <div class=\"d-flex align-items-center gap-1\">\n                <span class=\"badge bg-dark border border-secondary px-2 py-1\">${Number(b.display_order || 0).toLocaleString('fa-IR')}</span>\n                <div class=\"btn-group-vertical btn-group-sm\">\n                  <button type=\"button\" class=\"btn btn-outline-secondary py-0 px-1\" title=\"انتقال به بالا\" onclick=\"moveAdBannerOrder('${escapeHtml(b.id)}', -1)\" ${idx === 0 ? 'disabled' : ''}>\n                    <i class=\"bi bi-caret-up-fill\" style=\"font-size: 10px;\"></i>\n                  </button>\n                  <button type=\"button\" class=\"btn btn-outline-secondary py-0 px-1\" title=\"انتقال به پایین\" onclick=\"moveAdBannerOrder('${escapeHtml(b.id)}', 1)\" ${idx === filtered.length - 1 ? 'disabled' : ''}>\n                    <i class=\"bi bi-caret-down-fill\" style=\"font-size: 10px;\"></i>\n                  </button>\n                </div>\n              </div>\n            </td>\n            <td>\n              ${safeImgUrl\n                ? `<img src=\"${escapeHtml(safeImgUrl)}\" alt=\"${escapeHtml(b.title)}\" class=\"rounded border border-secondary\" style=\"width: 116px; height: 60px; object-fit: cover; background: #0B192C;\" onerror=\"this.style.opacity='0.35'; this.alt='تصویر در دسترس نیست';\">`\n                : '<span class=\"badge bg-secondary\">بدون تصویر</span>'}\n            </td>\n            <td>\n              <div class=\"fw-bold text-white mb-1\">${escapeHtml(b.title)}</div>\n              <div class=\"d-flex align-items-center gap-2 flex-wrap mb-1\">\n                ${modeBadge}\n                <div>${placementBadges}</div>\n              </div>\n              <div>\n                ${safeUrl ? `<a href=\"${escapeHtml(safeUrl)}\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"small text-info text-truncate d-inline-block\" style=\"max-width: 260px; direction: ltr;\">${escapeHtml(safeUrl)}</a>` : '<span class=\"small text-danger\">لینک نامعتبر</span>'}\n              </div>\n            </td>\n            <td>\n              <div class=\"d-flex flex-column gap-1 align-items-start\">\n                ${statusBadges[b.computed_status] || '<span class=\"badge bg-secondary\">-</span>'}\n                <div class=\"form-check form-switch m-0\">\n                  <input class=\"form-check-input\" type=\"checkbox\" ${b.is_active ? 'checked' : ''} onchange=\"toggleAdBannerStatus('${escapeHtml(b.id)}')\" title=\"تغییر وضعیت فعال/غیرفعال\">\n                </div>\n              </div>\n            </td>\n            <td class=\"small text-secondary\">\n              <div>شروع: <span class=\"text-white\">${formatPersianDateTime(b.start_at)}</span></div>\n              <div>پایان: <span class=\"text-white\">${formatPersianDateTime(b.end_at)}</span></div>\n            </td>\n            <td class=\"small\">\n              <div>نمایش: <strong class=\"text-info\">${Number(b.impression_count || 0).toLocaleString('fa-IR')}</strong></div>\n              <div>کلیک: <strong class=\"text-warning\">${Number(b.click_count || 0).toLocaleString('fa-IR')}</strong></div>\n              <div class=\"text-secondary\">CTR: <strong class=\"text-success\">${b.ctr_percent || 0}٪</strong></div>\n              ${renderPlacementStatsBreakdown(b.placement_stats)}\n            </td>\n            <td>\n              <div class=\"d-flex gap-1 flex-wrap\">\n                <button type=\"button\" class=\"btn btn-sm btn-outline-warning\" onclick=\"openAdBannerModal('${escapeHtml(b.id)}')\" title=\"ویرایش\">\n                  <i class=\"bi bi-pencil-fill\"></i> ویرایش\n                </button>\n                <button type=\"button\" class=\"btn btn-sm btn-outline-danger\" onclick=\"deleteAdBanner('${escapeHtml(b.id)}')\" title=\"حذف\">\n                  <i class=\"bi bi-trash-fill\"></i>\n                </button>\n              </div>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function openAdBannerModal(bannerId = null) {\n      try {\n        const modalEl = document.getElementById('adBannerModal');\n        if (!modalEl) {\n          console.error('[AdBanners] #adBannerModal element missing from DOM');\n          showAdBannerSectionAlert('خطای داخلی: فرم ایجاد بنر تبلیغاتی در صفحه یافت نشد.', 'error');\n          return;\n        }\n\n        // Guarantee #adBannerModal is mounted directly under <body> so no parent container can hide or clip it\n        if (modalEl.parentElement !== document.body) {\n          document.body.appendChild(modalEl);\n        }\n\n        closeSidebar();\n        bindAdBannerModalLifecycle(modalEl);\n\n        const modalAlert = document.getElementById('adBannerModalAlert');\n        if (modalAlert) modalAlert.classList.add('d-none');\n\n        const fileInput = document.getElementById('adBannerImageFileInput');\n        if (fileInput) fileInput.value = '';\n        isUploadingAdBannerImage = false;\n\n        if (bannerId) {\n          const b = cachedAdBanners.find((item) => item.id === bannerId);\n          if (!b) {\n            showAdBannerSectionAlert('اطلاعات این بنر در لیست فعلی یافت نشد. لطفاً لیست را به‌روزرسانی کنید.', 'warning');\n            return;\n          }\n          document.getElementById('adBannerModalLabel').innerHTML = '<i class=\"bi bi-pencil-square text-warning me-2\"></i> ویرایش بنر تبلیغاتی';\n          document.getElementById('adBannerEditId').value = b.id;\n          document.getElementById('adBannerTitleInput').value = b.title || '';\n          document.getElementById('adBannerOrderInput').value = b.display_order ?? 0;\n          document.getElementById('adBannerImageUrlInput').value = b.image_url || '';\n          document.getElementById('adBannerTargetUrlInput').value = b.target_url || '';\n          document.getElementById('adBannerStatusSelect').value = b.is_active ? 'true' : 'false';\n          document.getElementById('adBannerLinkModeSelect').value = b.link_open_mode === 'internal' ? 'internal' : 'external';\n          document.getElementById('adBannerStartAtInput').value = toDatetimeLocalValue(b.start_at);\n          document.getElementById('adBannerEndAtInput').value = toDatetimeLocalValue(b.end_at);\n\n          const bannerPlacements = Array.isArray(b.placements) ? b.placements : ['home'];\n          document.querySelectorAll('.ad-banner-placement-chk').forEach(chk => {\n            chk.checked = bannerPlacements.includes(chk.value);\n          });\n          const allChk = document.getElementById('adBannerSelectAllPlacements');\n          if (allChk) allChk.checked = bannerPlacements.length === 4;\n\n          document.getElementById('adBannerUploadStatus').textContent = 'تصویر فعلی بارگذاری شده است (برای تغییر فایل جدید انتخاب کنید)';\n          document.getElementById('adBannerUploadStatus').className = 'small text-info';\n        } else {\n          document.getElementById('adBannerModalLabel').innerHTML = '<i class=\"bi bi-plus-circle-fill text-warning me-2\"></i> ایجاد بنر تبلیغاتی جدید';\n          document.getElementById('adBannerEditId').value = '';\n          document.getElementById('adBannerTitleInput').value = '';\n          const nextOrder = cachedAdBanners.length > 0\n            ? Math.max(...cachedAdBanners.map((x) => Number(x.display_order || 0))) + 1\n            : 1;\n          document.getElementById('adBannerOrderInput').value = nextOrder;\n          document.getElementById('adBannerImageUrlInput').value = '';\n          document.getElementById('adBannerTargetUrlInput').value = '';\n          document.getElementById('adBannerStatusSelect').value = 'true';\n          document.getElementById('adBannerLinkModeSelect').value = 'external';\n          document.getElementById('adBannerStartAtInput').value = '';\n          document.getElementById('adBannerEndAtInput').value = '';\n\n          document.querySelectorAll('.ad-banner-placement-chk').forEach(chk => {\n            chk.checked = (chk.value === 'home');\n          });\n          const allChk = document.getElementById('adBannerSelectAllPlacements');\n          if (allChk) allChk.checked = false;\n\n          document.getElementById('adBannerUploadStatus').textContent = 'تصویری انتخاب نشده است';\n          document.getElementById('adBannerUploadStatus').className = 'small text-secondary';\n        }\n\n        updateAdBannerPreview();\n\n        if (typeof bootstrap !== 'undefined' && bootstrap.Modal) {\n          bootstrapAdBannerModal = bootstrap.Modal.getOrCreateInstance(modalEl, {\n            backdrop: true,\n            keyboard: true\n          });\n          bootstrapAdBannerModal.show();\n        } else {\n          // Graceful fallback if Bootstrap CDN script failed to load\n          cleanupStaleAdBannerModalState();\n          adBannerFallbackBackdrop = document.createElement('div');\n          adBannerFallbackBackdrop.className = 'modal-backdrop fade show';\n          document.body.appendChild(adBannerFallbackBackdrop);\n          document.body.classList.add('modal-open');\n          modalEl.style.display = 'block';\n          modalEl.classList.add('show');\n          modalEl.setAttribute('aria-modal', 'true');\n          modalEl.setAttribute('role', 'dialog');\n          modalEl.removeAttribute('aria-hidden');\n        }\n      } catch (err) {\n        console.error('[AdBanners] openAdBannerModal error:', err);\n        cleanupStaleAdBannerModalState();\n        showAdBannerSectionAlert('خطا در باز کردن فرم تبلیغ: ' + (err?.message || 'خطای غیرمنتظره'), 'error');\n      }\n    }\n\n    function setAdBannerQuickEndDays(days) {\n      const targetDate = new Date(Date.now() + days * 24 * 60 * 60 * 1000);\n      document.getElementById('adBannerEndAtInput').value = toDatetimeLocalValue(targetDate);\n      updateAdBannerPreview();\n    }\n\n    async function handleAdBannerFileSelected(event) {\n      const file = event.target?.files?.[0];\n      if (!file) return;\n\n      const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];\n      if (!allowedTypes.includes(file.type)) {\n        document.getElementById('adBannerUploadStatus').textContent = 'فقط فرمت‌های JPG، PNG و WebP مجاز هستند.';\n        document.getElementById('adBannerUploadStatus').className = 'small text-danger';\n        return;\n      }\n      if (file.size > 5 * 1024 * 1024) {\n        document.getElementById('adBannerUploadStatus').textContent = 'حجم تصویر نباید بیشتر از ۵ مگابایت باشد.';\n        document.getElementById('adBannerUploadStatus').className = 'small text-danger';\n        return;\n      }\n\n      const statusEl = document.getElementById('adBannerUploadStatus');\n      statusEl.textContent = 'در حال بارگذاری تصویر...';\n      statusEl.className = 'small text-warning';\n      isUploadingAdBannerImage = true;\n\n      try {\n        const formData = new FormData();\n        formData.append('image', file);\n\n        const res = await fetch('/api/admin/ad-banners/upload-image', {\n          method: 'POST',\n          headers: { 'x-admin-key': getAdminKey() },\n          body: formData\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success || !data.url) {\n          statusEl.textContent = data.message || `خطا در آپلود تصویر (کد ${res.status})`;\n          statusEl.className = 'small text-danger';\n          return;\n        }\n\n        document.getElementById('adBannerImageUrlInput').value = data.url;\n        statusEl.textContent = 'تصویر با موفقیت بارگذاری شد.';\n        statusEl.className = 'small text-success';\n        updateAdBannerPreview();\n      } catch (err) {\n        console.error('[AdBanners] upload failed:', err);\n        statusEl.textContent = 'خطا در آپلود تصویر: ' + (err?.message || 'نامشخص');\n        statusEl.className = 'small text-danger';\n      } finally {\n        isUploadingAdBannerImage = false;\n      }\n    }\n\n    function updateAdBannerPreview() {\n      const imageUrl = (document.getElementById('adBannerImageUrlInput')?.value || '').trim();\n      const targetUrl = (document.getElementById('adBannerTargetUrlInput')?.value || '').trim();\n      const isActive = document.getElementById('adBannerStatusSelect')?.value === 'true';\n      const linkMode = document.getElementById('adBannerLinkModeSelect')?.value || 'external';\n      const startVal = document.getElementById('adBannerStartAtInput')?.value;\n      const endVal = document.getElementById('adBannerEndAtInput')?.value;\n\n      const imgEl = document.getElementById('adBannerPreviewImg');\n      const placeholderEl = document.getElementById('adBannerPreviewPlaceholder');\n      if (imgEl && placeholderEl) {\n        if (isSafeBannerImageUrl(imageUrl)) {\n          imgEl.onerror = () => {\n            imgEl.style.display = 'none';\n            placeholderEl.style.display = 'block';\n          };\n          imgEl.src = imageUrl;\n          imgEl.style.display = 'block';\n          placeholderEl.style.display = 'none';\n        } else {\n          imgEl.onerror = null;\n          imgEl.src = '';\n          imgEl.style.display = 'none';\n          placeholderEl.style.display = 'block';\n        }\n      }\n\n      const statusBadge = document.getElementById('adBannerPreviewStatusBadge');\n      if (statusBadge) {\n        const now = Date.now();\n        const startMs = startVal ? new Date(startVal).getTime() : null;\n        const endMs = endVal ? new Date(endVal).getTime() : null;\n        if (!isActive) {\n          statusBadge.className = 'badge bg-secondary';\n          statusBadge.textContent = 'غیرفعال';\n        } else if (startMs && startMs > now) {\n          statusBadge.className = 'badge bg-info text-dark';\n          statusBadge.textContent = 'زمان‌بندی‌شده';\n        } else if (endMs && endMs <= now) {\n          statusBadge.className = 'badge bg-danger';\n          statusBadge.textContent = 'منقضی‌شده';\n        } else {\n          statusBadge.className = 'badge bg-success';\n          statusBadge.textContent = 'فعال';\n        }\n      }\n\n      const modeBadge = document.getElementById('adBannerPreviewModeBadge');\n      if (modeBadge) {\n        if (linkMode === 'internal') {\n          modeBadge.className = 'badge bg-info text-dark';\n          modeBadge.textContent = 'مرورگر داخلی برنامه';\n        } else {\n          modeBadge.className = 'badge bg-warning text-dark';\n          modeBadge.textContent = 'مرورگر خارجی';\n        }\n      }\n\n      const urlText = document.getElementById('adBannerPreviewUrlText');\n      const testLink = document.getElementById('adBannerPreviewTestLink');\n      if (urlText && testLink) {\n        if (isValidHttpUrlFrontend(targetUrl)) {\n          urlText.textContent = targetUrl;\n          urlText.className = 'text-warning small text-truncate flex-grow-1';\n          testLink.href = targetUrl;\n          testLink.classList.remove('disabled');\n        } else {\n          urlText.textContent = targetUrl ? 'لینک نامعتبر (فقط http/https مجاز است)' : 'لینک وارد نشده است';\n          urlText.className = 'text-danger small text-truncate flex-grow-1';\n          testLink.href = '#';\n          testLink.classList.add('disabled');\n        }\n      }\n    }\n\n    async function submitAdBannerForm(event) {\n      event.preventDefault();\n      const modalAlert = document.getElementById('adBannerModalAlert');\n      const showModalErr = (msg) => {\n        if (modalAlert) {\n          modalAlert.textContent = msg;\n          modalAlert.classList.remove('d-none');\n        } else {\n          alert(msg);\n        }\n      };\n\n      if (modalAlert) modalAlert.classList.add('d-none');\n\n      if (isUploadingAdBannerImage) {\n        showModalErr('لطفاً تا پایان بارگذاری تصویر صبر کنید.');\n        return;\n      }\n\n      const editId = document.getElementById('adBannerEditId').value.trim();\n      const title = document.getElementById('adBannerTitleInput').value.trim();\n      const image_url = document.getElementById('adBannerImageUrlInput').value.trim();\n      const target_url = document.getElementById('adBannerTargetUrlInput').value.trim();\n      const is_active = document.getElementById('adBannerStatusSelect').value === 'true';\n      const link_open_mode = document.getElementById('adBannerLinkModeSelect').value;\n      const display_order = Number(document.getElementById('adBannerOrderInput').value || 0);\n      const startVal = document.getElementById('adBannerStartAtInput').value;\n      const endVal = document.getElementById('adBannerEndAtInput').value;\n\n      if (!title) {\n        showModalErr('نام داخلی تبلیغ الزامی است.');\n        return;\n      }\n      if (!image_url) {\n        showModalErr('لطفاً تصویر بنر را از دستگاه انتخاب و بارگذاری کنید.');\n        return;\n      }\n      if (!isValidHttpUrlFrontend(target_url)) {\n        showModalErr('لینک مقصد باید یک آدرس معتبر با http:// یا https:// باشد.');\n        return;\n      }\n\n      const placements = Array.from(document.querySelectorAll('.ad-banner-placement-chk:checked')).map(el => el.value);\n      if (placements.length === 0) {\n        showModalErr('حداقل یک محل نمایش برای بنر باید انتخاب شود.');\n        return;\n      }\n\n      const start_at = startVal ? new Date(startVal).toISOString() : null;\n      const end_at = endVal ? new Date(endVal).toISOString() : null;\n      if (start_at && end_at && new Date(end_at).getTime() <= new Date(start_at).getTime()) {\n        showModalErr('تاریخ پایان نمایش باید بعد از تاریخ شروع باشد.');\n        return;\n      }\n\n      const spinner = document.getElementById('saveAdBannerSpinner');\n      const saveBtn = document.getElementById('saveAdBannerBtn');\n      if (spinner) spinner.classList.remove('d-none');\n      if (saveBtn) saveBtn.disabled = true;\n\n      try {\n        const endpoint = editId ? `/api/admin/ad-banners/${encodeURIComponent(editId)}` : '/api/admin/ad-banners';\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(endpoint, {\n          method,\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': getAdminKey()\n          },\n          body: JSON.stringify({\n            title,\n            image_url,\n            target_url,\n            is_active,\n            link_open_mode,\n            display_order,\n            start_at,\n            end_at,\n            placements\n          })\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success) {\n          showModalErr(data.message || data.error || `خطا در ذخیره بنر تبلیغاتی (کد ${res.status})`);\n          return;\n        }\n\n        hideAdBannerModalSafely();\n        showAdBannerSectionAlert(data.message || 'بنر تبلیغاتی با موفقیت ذخیره شد.', 'success');\n        await loadAdBanners();\n      } catch (err) {\n        console.error('[AdBanners] submitAdBannerForm failed:', err);\n        showModalErr('خطای ارتباط با سرور: ' + (err?.message || 'نامشخص'));\n      } finally {\n        if (spinner) spinner.classList.add('d-none');\n        if (saveBtn) saveBtn.disabled = false;\n      }\n    }\n\n    function toggleAllAdBannerPlacements(masterChk) {\n      const checked = masterChk.checked;\n      document.querySelectorAll('.ad-banner-placement-chk').forEach(chk => {\n        chk.checked = checked;\n      });\n    }\n\n    async function toggleAdBannerStatus(bannerId) {\n      try {\n        const res = await fetch(`/api/admin/ad-banners/${encodeURIComponent(bannerId)}/toggle`, {\n          method: 'PATCH',\n          headers: { 'x-admin-key': getAdminKey() }\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success) {\n          showAdBannerSectionAlert(data.message || 'تغییر وضعیت انجام نشد.', 'error');\n        } else {\n          showAdBannerSectionAlert(data.message || 'وضعیت تبلیغ تغییر کرد.', 'success');\n        }\n        await loadAdBanners();\n      } catch (err) {\n        console.error('[AdBanners] toggleAdBannerStatus failed:', err);\n        showAdBannerSectionAlert('خطا در تغییر وضعیت: ' + (err?.message || 'نامشخص'), 'error');\n      }\n    }\n\n    async function moveAdBannerOrder(bannerId, direction) {\n      const sorted = [...cachedAdBanners].sort((a, b) => (a.display_order - b.display_order));\n      const idx = sorted.findIndex((b) => b.id === bannerId);\n      const targetIdx = idx + direction;\n      if (idx < 0 || targetIdx < 0 || targetIdx >= sorted.length) return;\n\n      const swapped = [...sorted];\n      const temp = swapped[idx];\n      swapped[idx] = swapped[targetIdx];\n      swapped[targetIdx] = temp;\n\n      const items = swapped.map((b, i) => ({ id: b.id, display_order: i + 1 }));\n      try {\n        const res = await fetch('/api/admin/ad-banners/reorder', {\n          method: 'PATCH',\n          headers: {\n            'Content-Type': 'application/json',\n            'x-admin-key': getAdminKey()\n          },\n          body: JSON.stringify({ items })\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success) {\n          showAdBannerSectionAlert(data.message || 'تغییر ترتیب انجام نشد.', 'error');\n          return;\n        }\n        await loadAdBanners();\n      } catch (err) {\n        console.error('[AdBanners] moveAdBannerOrder failed:', err);\n        showAdBannerSectionAlert('خطا در تغییر ترتیب نمایش: ' + (err?.message || 'نامشخص'), 'error');\n      }\n    }\n\n    async function deleteAdBanner(bannerId) {\n      const targetBanner = cachedAdBanners.find((b) => b.id === bannerId);\n      const title = targetBanner?.title || 'این تبلیغ';\n      if (!confirm(`آیا از حذف بنر تبلیغاتی «${title}» اطمینان دارید؟`)) return;\n      try {\n        const res = await fetch(`/api/admin/ad-banners/${encodeURIComponent(bannerId)}`, {\n          method: 'DELETE',\n          headers: { 'x-admin-key': getAdminKey() }\n        });\n        const data = await parseJsonResponseSafely(res);\n        if (!res.ok || !data.success) {\n          showAdBannerSectionAlert(data.message || 'حذف تبلیغ ناموفق بود.', 'error');\n          return;\n        }\n        showAdBannerSectionAlert('بنر تبلیغاتی با موفقیت حذف شد.', 'success');\n        await loadAdBanners();\n      } catch (err) {\n        console.error('[AdBanners] deleteAdBanner failed:', err);\n        showAdBannerSectionAlert('خطا در حذف بنر: ' + (err?.message || 'نامشخص'), 'error');\n      }\n    }\n\n    // Auto-refresh every 12 seconds with live data\n    loadDashboard();\n    setInterval(loadDashboard, 12000);\n  </script>\n</body>\n</html>\n";
const EMBEDDED_USERS_HTML = "<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=5.0, viewport-fit=cover\">\n  <title>فهرست کاربران واقعی | رقابت کن، جایزه ببر</title>\n  <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.rtl.min.css\" rel=\"stylesheet\">\n  <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css\">\n  <style>\n    * {\n      box-sizing: border-box;\n    }\n    body {\n      font-family: system-ui, -apple-system, \"Segoe UI\", Roboto, \"Vazirmatn\", Tahoma, sans-serif;\n      background-color: #0B192C;\n      color: #F8FAFC;\n      min-height: 100vh;\n      margin: 0;\n      padding: 0;\n      overflow-x: hidden;\n      -webkit-font-smoothing: antialiased;\n    }\n    .page-wrapper {\n      width: 100%;\n      max-width: 960px;\n      margin: 0 auto;\n      padding: 12px 10px;\n    }\n    @media (min-width: 576px) {\n      .page-wrapper {\n        padding: 24px 20px;\n      }\n    }\n    .header-bar {\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n      margin-bottom: 14px;\n    }\n    @media (min-width: 576px) {\n      .header-bar {\n        flex-direction: row;\n        justify-content: space-between;\n        align-items: center;\n        margin-bottom: 18px;\n      }\n    }\n    .main-title {\n      font-size: 20px;\n      color: #FFB703;\n      font-weight: 800;\n      letter-spacing: -0.3px;\n      margin: 0;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    @media (min-width: 576px) {\n      .main-title {\n        font-size: 23px;\n      }\n    }\n    .search-wrapper {\n      width: 100%;\n    }\n    @media (min-width: 576px) {\n      .search-wrapper {\n        width: 280px;\n      }\n    }\n    .form-control-dark {\n      background-color: #152A44;\n      border: 1px solid #2E5077;\n      color: #fff;\n      font-size: 13px;\n      border-radius: 10px;\n      padding: 8px 12px;\n      width: 100%;\n      height: 40px;\n    }\n    .form-control-dark:focus {\n      background-color: #1E3E62;\n      border-color: #FFB703;\n      color: #fff;\n      box-shadow: 0 0 0 0.2rem rgba(255,183,3,0.25);\n    }\n    .form-control-dark::placeholder {\n      color: #94A3B8;\n      font-size: 12.5px;\n    }\n    .table-card {\n      background-color: #1E3E62;\n      border: 1px solid #2E5077;\n      border-radius: 14px;\n      padding: 6px;\n      box-shadow: 0 4px 16px rgba(0,0,0,0.35);\n      overflow: hidden;\n    }\n    @media (min-width: 576px) {\n      .table-card {\n        border-radius: 16px;\n        padding: 12px;\n      }\n    }\n    .table-responsive-custom {\n      width: 100%;\n      overflow-x: auto;\n      -webkit-overflow-scrolling: touch;\n      margin: 0;\n    }\n    .users-table {\n      width: 100%;\n      min-width: 300px;\n      margin-bottom: 0;\n      border-collapse: separate;\n      border-spacing: 0;\n      font-size: 13px;\n    }\n    .users-table th {\n      background-color: #152A44;\n      color: #94A3B8;\n      font-size: 12px;\n      font-weight: 700;\n      padding: 10px 8px;\n      border-bottom: 1px solid #2E5077;\n      white-space: nowrap;\n      text-align: center;\n    }\n    .users-table th.th-name {\n      text-align: right;\n    }\n    .users-table td {\n      padding: 10px 8px;\n      vertical-align: middle;\n      border-bottom: 1px solid rgba(46, 80, 119, 0.45);\n      color: #F8FAFC;\n      line-height: 1.35;\n    }\n    .users-table tbody tr:last-child td {\n      border-bottom: none;\n    }\n    .users-table tbody tr:hover {\n      background-color: rgba(255, 183, 3, 0.05);\n    }\n    .col-rank {\n      width: 50px;\n      text-align: center;\n      font-weight: 700;\n      color: #94A3B8;\n      font-size: 13px;\n    }\n    .col-name {\n      text-align: right;\n      font-weight: 600;\n      font-size: 13px;\n      word-break: break-word;\n    }\n    .col-score {\n      width: 120px;\n      text-align: center;\n    }\n    .badge-gold {\n      background: linear-gradient(135deg, #FFB703, #FB8500);\n      color: #0B192C;\n      font-weight: 800;\n      padding: 5px 10px;\n      border-radius: 12px;\n      font-size: 12px;\n      display: inline-block;\n      white-space: nowrap;\n    }\n    .rank-top-1 {\n      color: #FFD700 !important;\n      font-weight: 900;\n    }\n    .rank-top-2 {\n      color: #E2E8F0 !important;\n      font-weight: 800;\n    }\n    .rank-top-3 {\n      color: #F59E0B !important;\n      font-weight: 800;\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"page-wrapper\">\n    <!-- Header with Title and Search -->\n    <div class=\"header-bar\">\n      <h2 class=\"main-title\">\n        <i class=\"bi bi-trophy-fill text-warning\"></i>\n        <span>فهرست کاربران واقعی</span>\n      </h2>\n      <div class=\"search-wrapper\">\n        <input type=\"text\" id=\"userSearchInput\" class=\"form-control-dark\" placeholder=\"جستجو بر اساس نام...\" onkeyup=\"filterUsers()\" autocomplete=\"off\">\n      </div>\n    </div>\n\n    <!-- Auth Prompt Card -->\n    <div id=\"authPromptCard\" class=\"card p-3 mb-3 d-none\" style=\"background-color: #152A44; border: 1px solid #FFB703; border-radius: 12px;\">\n      <div class=\"d-flex flex-column flex-sm-row gap-2 align-items-center justify-content-between\">\n        <div class=\"text-warning small fw-bold\">\n          <i class=\"bi bi-shield-lock-fill me-1\"></i> احراز هویت الزامی است. لطفاً کلید مدیریت را وارد نمایید:\n        </div>\n        <div class=\"d-flex gap-2 w-100\" style=\"max-width: 340px;\">\n          <input type=\"password\" id=\"adminKeyInput\" class=\"form-control-dark\" placeholder=\"کلید مدیریت (ADMIN_KEY)...\">\n          <button class=\"btn btn-warning fw-bold text-dark px-3\" onclick=\"submitAdminKey()\">ورود</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Alert Box -->\n    <div id=\"alertBox\" class=\"alert alert-danger d-none shadow-sm py-2 px-3 small mb-3\" role=\"alert\"></div>\n\n    <!-- Responsive Users Table Card -->\n    <div class=\"table-card\">\n      <div class=\"table-responsive-custom\">\n        <table class=\"users-table\">\n          <thead>\n            <tr>\n              <th scope=\"col\" class=\"col-rank\">#</th>\n              <th scope=\"col\" class=\"th-name\">نام و نام خانوادگی</th>\n              <th scope=\"col\" class=\"col-score\">مجموع امتیاز</th>\n            </tr>\n          </thead>\n          <tbody id=\"usersTbody\">\n            <tr>\n              <td colspan=\"3\" class=\"text-center py-4 text-secondary small\">\n                <span class=\"spinner-border spinner-border-sm me-2 text-warning\" role=\"status\"></span>\n                در حال دریافت اطلاعات از سرور...\n              </td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    let cachedUsers = [];\n\n    function getSavedKey() {\n      return (localStorage.getItem('reqabat_admin_key') || '09876poiuyAA').trim();\n    }\n\n    function submitAdminKey() {\n      const input = document.getElementById('adminKeyInput')?.value.trim();\n      if (!input) {\n        showAlert('لطفاً کلید مدیریت را وارد کنید.');\n        return;\n      }\n      localStorage.setItem('reqabat_admin_key', input);\n      document.getElementById('authPromptCard')?.classList.add('d-none');\n      hideAlert();\n      loadUsers();\n    }\n\n    function showAlert(msg) {\n      const el = document.getElementById('alertBox');\n      if (el) {\n        el.innerText = msg;\n        el.classList.remove('d-none');\n      }\n    }\n\n    function hideAlert() {\n      const el = document.getElementById('alertBox');\n      if (el) el.classList.add('d-none');\n    }\n\n    function sortUsersList(list) {\n      return list.sort((a, b) => {\n        const scoreA = Number(a.score) || 0;\n        const scoreB = Number(b.score) || 0;\n        if (scoreB !== scoreA) {\n          return scoreB - scoreA;\n        }\n        const timeA = typeof a.registeredAt === 'number' ? a.registeredAt : (new Date(a.registeredAt || 0).getTime() || 0);\n        const timeB = typeof b.registeredAt === 'number' ? b.registeredAt : (new Date(b.registeredAt || 0).getTime() || 0);\n        if (timeA !== timeB) {\n          return timeA - timeB;\n        }\n        return (a.firstName || '').localeCompare(b.firstName || '');\n      });\n    }\n\n    async function loadUsers() {\n      hideAlert();\n\n      const key = getSavedKey();\n      const authCard = document.getElementById('authPromptCard');\n\n      if (!key) {\n        if (authCard) authCard.classList.remove('d-none');\n        showAlert('برای مشاهده فهرست کاربران، لطفاً کلید مدیریت را وارد کنید.');\n        const tbody = document.getElementById('usersTbody');\n        if (tbody) {\n          tbody.innerHTML = '<tr><td colspan=\"3\" class=\"text-center py-4 text-warning small\"><i class=\"bi bi-shield-lock me-1\"></i> دسترسی نیازمند ورود کلید مدیریت است.</td></tr>';\n        }\n        return;\n      }\n\n      try {\n        const res = await fetch('/api/admin/users', {\n          headers: {\n            'x-admin-key': key\n          }\n        });\n\n        if (res.status === 401) {\n          if (authCard) authCard.classList.remove('d-none');\n          localStorage.removeItem('reqabat_admin_key');\n          throw new Error('کلید امنیتی مدیریت نامعتبر است. لطفاً کلید صحیح را وارد کنید.');\n        }\n\n        if (!res.ok) {\n          throw new Error('خطا در دریافت اطلاعات از سرور (کد ' + res.status + ')');\n        }\n\n        if (authCard) authCard.classList.add('d-none');\n        const data = await res.json();\n        cachedUsers = sortUsersList(data.users || []);\n        renderUsers(cachedUsers);\n\n      } catch (err) {\n        console.error('Error loading users:', err);\n        showAlert(err.message || 'خطا در ارتباط با سرور.');\n      }\n    }\n\n    function renderUsers(users) {\n      const tbody = document.getElementById('usersTbody');\n      if (!users || users.length === 0) {\n        tbody.innerHTML = `\n          <tr>\n            <td colspan=\"3\" class=\"text-center py-4 text-secondary small\">\n              <i class=\"bi bi-people fs-4 d-block mb-1 text-secondary\"></i>\n              هیچ کاربری در پایگاه داده سرور یافت نشد.\n            </td>\n          </tr>\n        `;\n        return;\n      }\n\n      tbody.innerHTML = users.map((u, index) => {\n        const rankNumber = index + 1;\n        const rankClass = rankNumber === 1 ? 'rank-top-1' : (rankNumber === 2 ? 'rank-top-2' : (rankNumber === 3 ? 'rank-top-3' : ''));\n        const fullName = ((u.firstName || '') + ' ' + (u.lastName || '')).trim() || 'کاربر بدون نام';\n        return `\n          <tr>\n            <td class=\"col-rank ${rankClass}\">${rankNumber}</td>\n            <td class=\"col-name\">${fullName}</td>\n            <td class=\"col-score\">\n              <span class=\"badge-gold\">${u.score || 0} امتیاز</span>\n            </td>\n          </tr>\n        `;\n      }).join('');\n    }\n\n    function filterUsers() {\n      const q = document.getElementById('userSearchInput').value.trim().toLowerCase();\n      if (!q) {\n        renderUsers(cachedUsers);\n        return;\n      }\n      const filtered = cachedUsers.filter(u => {\n        const fullName = ((u.firstName || '') + ' ' + (u.lastName || '')).toLowerCase();\n        return fullName.includes(q);\n      });\n      renderUsers(filtered);\n    }\n\n    // Direct initial load\n    loadUsers();\n\n    // Auto-refresh every 12 seconds with live data\n    setInterval(loadUsers, 12000);\n  </script>\n</body>\n</html>\n";

function getIndexHtml() {
  if (cachedIndex) return cachedIndex;
  try {
    const p = path.join(__dirname, '..', 'public', 'index.html');
    if (fs.existsSync(p)) {
      cachedIndex = fs.readFileSync(p, 'utf8');
      return cachedIndex;
    }
  } catch (_) {}
  cachedIndex = EMBEDDED_INDEX_HTML;
  return cachedIndex;
}

function getUsersHtml() {
  if (cachedUsers) return cachedUsers;
  try {
    const p = path.join(__dirname, '..', 'public', 'users.html');
    if (fs.existsSync(p)) {
      cachedUsers = fs.readFileSync(p, 'utf8');
      return cachedUsers;
    }
  } catch (_) {}
  cachedUsers = EMBEDDED_USERS_HTML;
  return cachedUsers;
}

module.exports = { getIndexHtml, getUsersHtml };

const GIFT_BANNER_B64 = "";
function getGiftBannerBuffer() {
  return Buffer.from(GIFT_BANNER_B64, "base64");
}
module.exports.getGiftBannerBuffer = getGiftBannerBuffer;
